insert into edu.bible_simulations (no,title,testament,book,book_order,ref,characters,summary,meaning,themes,question,audience,style,path)
values
(1,'천지창조','구약','창세기',1,'창 1:1-2:3',ARRAY['하나님']::text[],'하나님이 말씀으로 빛과 하늘과 땅, 바다와 육지, 해와 달과 별, 동식물과 사람을 엿새 동안 창조하시고 일곱째 날에 안식하셨다.','세상 모든 것은 하나님의 창조 질서 안에 있으며, 안식은 창조의 완성이자 선물이다.',ARRAY['창조와 섭리']::text[],'내 삶에서 하나님이 정해주신 질서와 쉼을 어떻게 지키고 있는지 나눠보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/001'),
(2,'에덴동산과 사람의 창조','구약','창세기',1,'창 2:4-25',ARRAY['하나님','아담','하와']::text[],'하나님이 흙으로 아담을 지어 생기를 불어넣으시고 에덴동산에 두셨으며, 아담의 갈빗대로 하와를 만들어 짝지어 주셨다.','사람은 하나님의 형상대로 지음받은 존귀한 존재이며, 돕는 배필과의 관계도 하나님의 선물이다.',ARRAY['창조와 섭리','가정과 관계']::text[],'나는 나 자신과 가족을 하나님이 지으신 존귀한 존재로 여기고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/002'),
(3,'선악과와 타락','구약','창세기',1,'창 3:1-24',ARRAY['하나님','아담','하와','뱀']::text[],'뱀의 유혹으로 아담과 하와가 선악을 알게 하는 나무의 열매를 먹고 하나님의 명령을 어겨 에덴동산에서 쫓겨났다.','죄는 하나님과의 관계를 끊어놓지만, 하나님은 심판 중에도 구원의 약속(여자의 후손)을 주셨다.',ARRAY['죄와 타락']::text[],'내가 하나님의 말씀보다 내 판단을 앞세운 적은 없는지 돌아보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/003'),
(4,'가인과 아벨','구약','창세기',1,'창 4:1-16',ARRAY['가인','아벨','하나님']::text[],'가인이 자기 제물이 열납되지 않자 분노하여 동생 아벨을 죽였고, 하나님은 가인에게 표를 주어 보호하시되 유리하는 삶을 살게 하셨다.','죄는 문 앞에 엎드려 있으나 우리는 죄를 다스려야 하며, 하나님은 심판 중에도 은혜를 베푸신다.',ARRAY['죄와 타락','분노 다스림']::text[],'시기심이나 분노가 마음에 들어올 때 나는 어떻게 그것을 다스리는가?',ARRAY['청소년','성인']::text[],'v1','/s/004'),
(5,'에녹이 하나님과 동행함','구약','창세기',1,'창 5:21-24',ARRAY['에녹','하나님']::text[],'에녹은 므두셀라를 낳은 후 삼백 년을 하나님과 동행하다가 죽음을 보지 않고 하나님이 데려가셨다.','날마다 하나님과 동행하는 삶은 세상 풍조와 다른 특별한 은혜의 삶이다.',ARRAY['순종과 믿음']::text[],'오늘 하루 하나님과 동행한다는 것은 구체적으로 어떤 모습일까?',ARRAY['청소년','성인']::text[],'v1','/s/005'),
(6,'노아가 방주를 지음','구약','창세기',1,'창 6:1-22',ARRAY['노아','하나님']::text[],'사람의 죄악이 세상에 가득하자 하나님이 홍수로 심판하기로 하시고, 의인 노아에게 방주를 지어 가족과 동물들을 구원할 것을 명하셨다.','세상이 악해질 때도 하나님은 순종하는 사람을 통해 구원의 길을 예비하신다.',ARRAY['순종과 믿음','하나님의 심판']::text[],'노아처럼 주변과 다르게 하나님께 순종해야 했던 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/006'),
(7,'홍수 심판과 방주','구약','창세기',1,'창 7:1-8:19',ARRAY['노아','노아의 가족','하나님']::text[],'사십 주야 비가 내려 온 땅이 물에 잠기고 방주에 탄 사람과 동물만 살아남았으며, 물이 줄자 비둘기가 감람나무 잎을 물고 돌아와 육지가 드러났음을 알렸다.','하나님은 심판 중에도 순종한 자를 끝까지 지켜 보존하신다.',ARRAY['하나님의 심판','인도하심과 보호']::text[],'기다림의 시간(방주 안에서의 시간) 속에서 하나님을 신뢰한다는 것은 어떤 의미일까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/007'),
(8,'무지개 언약','구약','창세기',1,'창 9:1-17',ARRAY['노아','하나님']::text[],'방주에서 나온 노아에게 하나님이 다시는 물로 세상을 멸하지 않으시겠다는 언약을 맺으시고 무지개를 그 증거로 주셨다.','하나님의 언약은 사람의 행위와 상관없이 신실하게 지켜지는 약속이다.',ARRAY['하나님의 언약']::text[],'무지개를 볼 때 하나님의 신실하심을 기억한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/008'),
(9,'바벨탑 사건','구약','창세기',1,'창 11:1-9',ARRAY['온 땅의 사람들','하나님']::text[],'사람들이 하늘에 닿는 탑을 쌓아 이름을 내려 하자 하나님이 언어를 혼잡하게 하여 그들을 온 땅에 흩으셨다.','사람이 하나님의 자리를 대신하려는 교만은 결국 흩어짐을 가져온다.',ARRAY['겸손과 교만']::text[],'내 삶이나 공동체에서 하나님보다 이름을 높이려는 시도는 없는지 살펴보자.',ARRAY['청소년','성인']::text[],'v1','/s/009'),
(10,'아브람을 부르심','구약','창세기',1,'창 12:1-9',ARRAY['아브람','사라','하나님']::text[],'하나님이 아브람에게 고향과 친척을 떠나 지시할 땅으로 가라 명하시고 그를 통해 큰 민족을 이루고 모든 족속이 복을 얻게 하겠다 약속하셨다.','믿음의 여정은 익숙한 것을 떠나 하나님의 부르심을 따르는 데서 시작된다.',ARRAY['순종과 믿음','하나님의 언약']::text[],'지금 내게 익숙한 것을 떠나 하나님을 따르라는 부르심이 있다면 무엇일까?',ARRAY['청소년','성인']::text[],'v1','/s/010'),
(11,'아브람과 롯의 분리','구약','창세기',1,'창 13:1-18',ARRAY['아브람','롯','하나님']::text[],'아브람과 롯의 소유가 많아져 다툼이 생기자 아브람은 롯에게 먼저 선택권을 양보했고, 롯은 요단 온 들을 택해 소돔 근처로 옮겼다.','관계의 평화를 위해 자신의 권리를 양보하는 것은 믿음의 성숙을 보여준다.',ARRAY['가정과 관계','겸손과 교만']::text[],'나는 다툼이 생겼을 때 먼저 양보할 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/011'),
(12,'아브람이 롯을 구출하고 멜기세덱을 만남','구약','창세기',1,'창 14:1-24',ARRAY['아브람','롯','멜기세덱']::text[],'동방 왕들에게 롯이 사로잡히자 아브람이 사병을 거느리고 구출했고, 돌아오는 길에 살렘 왕 멜기세덱이 그를 축복하며 떡과 포도주를 내어주었다.','하나님은 위기의 순간 구원자를 예비하시며, 승리 후에는 하나님께 영광을 돌려야 한다.',ARRAY['인도하심과 보호','예배와 경배']::text[],'내가 얻은 승리나 성공을 누구에게 영광 돌리고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/012'),
(13,'아브람과 맺으신 횃불 언약','구약','창세기',1,'창 15:1-21',ARRAY['아브람','하나님']::text[],'하나님이 후사가 없는 아브람에게 하늘의 별처럼 많은 자손을 약속하시고, 쪼갠 짐승 사이로 타는 횃불이 지나가는 것으로 언약을 확증하셨다.','아브람은 하나님을 믿었고 그것이 그의 의로 여겨졌으니, 믿음은 하나님과 바른 관계의 근거이다.',ARRAY['순종과 믿음','하나님의 언약']::text[],'눈에 보이는 증거가 없어도 하나님의 약속을 믿는다는 것은 어떤 모습일까?',ARRAY['청소년','성인']::text[],'v1','/s/013'),
(14,'하갈과 이스마엘의 출생','구약','창세기',1,'창 16:1-16',ARRAY['아브람','사래','하갈','이스마엘']::text[],'자녀가 없던 사래가 여종 하갈을 통해 아들을 얻게 했으나 하갈이 사래를 무시하다 광야로 도망하였고, 하나님의 천사가 그를 만나 돌아가라 하시며 이스마엘의 출생을 예고하셨다.','사람의 조급함으로 만든 방법은 갈등을 낳지만, 하나님은 소외된 자의 부르짖음도 들으신다.',ARRAY['하나님의 언약','인도하심과 보호']::text[],'조급함으로 하나님의 때를 앞서가려 한 적은 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/014'),
(15,'할례 언약과 아브라함으로 개명','구약','창세기',1,'창 17:1-27',ARRAY['아브라함','사라','하나님']::text[],'하나님이 아브람과 사래의 이름을 아브라함과 사라로 바꾸시고 언약의 표징으로 할례를 명하시며 사라를 통해 아들 이삭을 주시겠다 약속하셨다.','하나님의 언약 백성은 그분이 주신 새 정체성과 표징을 따라 구별된 삶을 산다.',ARRAY['하나님의 언약']::text[],'내 정체성을 규정하는 것은 세상의 이름인가, 하나님이 주신 이름인가?',ARRAY['청소년','성인']::text[],'v1','/s/015'),
(16,'세 나그네의 방문과 이삭 출생 예고','구약','창세기',1,'창 18:1-15',ARRAY['아브라함','사라','세 사람(하나님과 두 천사)']::text[],'마므레 상수리나무 곁에서 나그네를 대접한 아브라함에게 하나님이 내년에 사라가 아들을 낳을 것을 예고하시니 사라는 속으로 웃었다.','하나님께는 능치 못할 일이 없으며, 나그네 대접은 뜻밖의 복으로 이어질 수 있다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나는 낯선 이를 대접하는 일에 얼마나 열려 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/016'),
(17,'아브라함의 중보기도','구약','창세기',1,'창 18:16-33',ARRAY['아브라함','하나님']::text[],'소돔을 멸하려는 계획을 들은 아브라함이 의인 오십 명부터 열 명까지 낮춰가며 그 성을 위해 간절히 중보기도 하였다.','의인을 위한 중보기도는 하나님의 자비를 구하는 신앙의 특권이다.',ARRAY['기도와 응답']::text[],'나는 심판받아 마땅한 이들을 위해 얼마나 간절히 중보하는가?',ARRAY['청소년','성인']::text[],'v1','/s/017'),
(18,'소돔과 고모라의 멸망','구약','창세기',1,'창 19:1-29',ARRAY['롯','롯의 아내','하나님','두 천사']::text[],'소돔의 죄악이 가득하여 하나님이 유황과 불로 그 성을 멸하실 때 천사들이 롯의 가족을 구원해 피신시켰으나 뒤돌아본 롯의 아내는 소금 기둥이 되었다.','죄악에 대한 하나님의 심판은 엄중하지만, 그 가운데서도 구원의 길을 여신다.',ARRAY['하나님의 심판','순종과 믿음']::text[],'돌아보지 말라는 말씀처럼 내가 미련을 두고 끊어내지 못하는 것은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/018'),
(19,'이삭의 출생','구약','창세기',1,'창 21:1-7',ARRAY['아브라함','사라','이삭']::text[],'하나님의 약속대로 사라가 백 세 된 아브라함에게서 아들 이삭을 낳으니 사라가 웃음을 얻었다고 고백하였다.','하나님의 약속은 사람의 능력을 넘어서는 때에도 반드시 이루어진다.',ARRAY['하나님의 언약']::text[],'내가 불가능하다고 여겼지만 하나님이 이루신 약속이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/019'),
(20,'아브라함이 이삭을 번제로 드리라는 시험','구약','창세기',1,'창 22:1-19',ARRAY['아브라함','이삭','하나님','여호와의 사자']::text[],'하나님이 아브라함에게 독자 이삭을 번제로 드리라 명하시자 그가 순종하여 모리아 산으로 올라갔고, 마지막 순간 하나님이 수풀에 걸린 숫양을 예비하여 이삭을 대신하게 하셨다.','여호와 이레, 하나님은 순종하는 자를 위해 친히 예비하시는 분이다.',ARRAY['순종과 믿음','하나님의 구원']::text[],'내게 가장 소중한 것을 하나님께 온전히 내어드릴 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/020'),
(21,'이삭의 신부 리브가를 구함','구약','창세기',1,'창 24:1-67',ARRAY['아브라함의 종','리브가','이삭']::text[],'아브라함의 종이 하나님께 기도하며 우물가에서 낙타에게 물을 길어주는 리브가를 이삭의 신붓감으로 인도받아 데려왔다.','작은 순종의 기도에도 응답하시는 하나님은 인생의 중요한 만남을 세밀히 인도하신다.',ARRAY['기도와 응답','인도하심과 보호']::text[],'중요한 결정을 앞두고 나는 얼마나 구체적으로 기도하며 인도를 구하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/021'),
(22,'에서와 야곱의 출생, 장자권을 팔다','구약','창세기',1,'창 25:19-34',ARRAY['이삭','리브가','에서','야곱']::text[],'리브가가 쌍둥이 에서와 야곱을 낳았고, 훗날 에서는 배고픔 때문에 팥죽 한 그릇에 장자의 명분을 야곱에게 팔았다.','눈앞의 욕구 때문에 영원한 가치를 가볍게 여기는 어리석음을 경계해야 한다.',ARRAY['지혜와 분별']::text[],'나는 순간의 만족을 위해 더 소중한 것을 소홀히 한 적이 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/022'),
(23,'야곱이 에서의 축복을 가로챔','구약','창세기',1,'창 27:1-40',ARRAY['이삭','리브가','에서','야곱']::text[],'눈이 어두워진 이삭이 장자 에서에게 축복하려 하자 리브가와 야곱이 속임수를 써서 야곱이 대신 축복을 받았고, 이 일로 에서의 분노를 사 야곱은 집을 떠나게 되었다.','속임수로 얻은 것은 결국 가정에 깊은 상처와 갈등을 남긴다.',ARRAY['가정과 관계','죄와 타락']::text[],'정직하지 못한 방법으로 원하는 것을 얻으려 했던 적은 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/023'),
(24,'야곱의 사다리 꿈(벧엘)','구약','창세기',1,'창 28:10-22',ARRAY['야곱','하나님']::text[],'도망하던 야곱이 광야에서 돌을 베고 자다가 하늘에 닿은 사다리와 오르내리는 천사들을 보았고, 하나님이 아브라함의 언약을 그에게도 이어 주겠다 약속하셨다.','하나님은 가장 외롭고 두려운 순간에도 함께하시며 언약을 이어가신다.',ARRAY['하나님의 언약','인도하심과 보호']::text[],'인생의 광야 같은 시기에 하나님이 함께하셨음을 깨달은 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/024'),
(25,'야곱이 라반의 집에서 레아와 라헬을 얻음','구약','창세기',1,'창 29:1-30',ARRAY['야곱','라반','레아','라헬']::text[],'야곱이 외삼촌 라반의 집에서 라헬을 사랑하여 칠 년을 섬겼으나 라반의 속임수로 먼저 레아와 결혼하고 다시 칠 년을 더 섬겨 라헬을 얻었다.','속이던 야곱이 속임을 당하는 이야기는 뿌린 대로 거둔다는 원리를 보여준다.',ARRAY['순종과 믿음','가정과 관계']::text[],'내가 뿌린 것을 거두게 된 경험을 돌아보자.',ARRAY['청소년','성인']::text[],'v1','/s/025'),
(26,'야곱이 얍복강에서 천사와 씨름함','구약','창세기',1,'창 32:22-32',ARRAY['야곱','하나님의 사자']::text[],'에서를 만나기 전날 밤 야곱이 얍복강 나루에서 한 사람과 밤새도록 씨름하며 축복을 구했고, 환도뼈가 위골된 채 이스라엘이라는 새 이름을 받았다.','진정한 축복은 하나님을 붙들고 씨름하는 간절함 속에서 주어지며, 옛 자아가 꺾여야 새 정체성을 얻는다.',ARRAY['기도와 응답','하나님의 언약']::text[],'나는 응답을 얻을 때까지 하나님을 붙드는 간절함이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/026'),
(27,'야곱과 에서의 화해','구약','창세기',1,'창 33:1-17',ARRAY['야곱','에서']::text[],'이십 년 만에 만난 에서가 두려워하던 야곱을 오히려 달려와 안고 입 맞추며 화해하였다.','깨어진 관계도 하나님의 은혜 안에서 회복될 수 있다.',ARRAY['회개와 용서','가정과 관계']::text[],'오래 소원했던 관계를 회복하기 위해 내가 먼저 할 수 있는 일은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/027'),
(28,'요셉의 꿈','구약','창세기',1,'창 37:1-11',ARRAY['요셉','야곱','요셉의 형들']::text[],'야곱이 요셉을 편애하여 채색옷을 지어 입혔고, 요셉이 형들의 곡식단과 해와 달과 별이 자신에게 절하는 꿈을 꾸어 형들의 미움을 샀다.','하나님이 주신 비전은 때로 당장의 갈등과 오해를 불러올 수 있다.',ARRAY['하나님의 섭리','가정과 관계']::text[],'내게 주신 하나님의 비전을 나누는 지혜로운 태도는 어떤 모습일까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/028'),
(29,'요셉이 형들에 의해 팔려감','구약','창세기',1,'창 37:12-36',ARRAY['요셉','요셉의 형들','르우벤','유다','미디안 상인']::text[],'형들이 요셉을 시기하여 죽이려다 은 이십에 미디안 상인에게 팔았고, 그의 옷에 피를 묻혀 야곱에게 요셉이 죽은 것처럼 속였다.','사람의 악한 계획 가운데서도 하나님은 더 큰 구원의 계획을 이루어 가신다.',ARRAY['하나님의 섭리','시기와 갈등']::text[],'형제 사이의 시기심이 얼마나 큰 상처를 남길 수 있는지 생각해보자.',ARRAY['청소년','성인']::text[],'v1','/s/029'),
(30,'유다와 다말','구약','창세기',1,'창 38:1-30',ARRAY['유다','다말']::text[],'유다가 며느리 다말과의 언약을 저버리자 다말이 지혜롭게 행하여 자신의 권리를 되찾았고, 이 사건은 훗날 다윗의 계보로 이어졌다.','사람의 허물 많은 이야기 속에서도 하나님의 구원 역사는 이어져 간다.',ARRAY['하나님의 섭리']::text[],'완벽하지 않은 가정사 속에서도 일하시는 하나님을 어떻게 신뢰할 수 있을까?',ARRAY['성인']::text[],'v1','/s/030'),
(31,'요셉과 보디발의 아내','구약','창세기',1,'창 39:1-20',ARRAY['요셉','보디발','보디발의 아내']::text[],'애굽 시위대장 보디발의 집에서 형통하던 요셉이 주인의 아내의 유혹을 단호히 거절하다 누명을 쓰고 감옥에 갇혔다.','하나님을 향한 정결함은 당장의 손해를 감수하더라도 지켜야 할 가치이다.',ARRAY['고난과 인내','충성과 신실함']::text[],'유혹 앞에서 손해를 감수하고서라도 옳은 길을 택한 경험이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/031'),
(32,'요셉이 옥에서 꿈을 해몽함','구약','창세기',1,'창 40:1-23',ARRAY['요셉','술 맡은 관원장','떡 굽는 관원장']::text[],'감옥에서 요셉이 바로의 두 관원장의 꿈을 하나님이 주신 지혜로 해몽했고, 그 해석대로 한 사람은 복직되고 한 사람은 처형되었다.','고난 중에도 자신의 은사를 통해 남을 섬기는 태도는 하나님이 사용하시는 통로가 된다.',ARRAY['고난과 인내','지혜와 분별']::text[],'어려운 상황 속에서도 내가 가진 것으로 남을 도운 적이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/032'),
(33,'요셉이 바로의 꿈을 해몽하고 총리가 됨','구약','창세기',1,'창 41:1-40',ARRAY['요셉','바로']::text[],'바로가 꾼 일곱 암소와 이삭의 꿈을 요셉이 앞으로 있을 칠 년 풍년과 칠 년 흉년으로 해석하고 대책을 제안하니, 바로가 요셉을 애굽의 총리로 세웠다.','하나님이 주신 지혜는 위기를 준비하고 많은 사람을 구원하는 데 쓰임받는다.',ARRAY['하나님의 섭리','지혜와 분별']::text[],'내게 주신 지혜와 재능을 공동체를 위해 어떻게 준비시켜 쓸 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/033'),
(34,'요셉의 형들이 애굽에 곡식을 사러 옴','구약','창세기',1,'창 42:1-38',ARRAY['요셉','요셉의 형들','야곱']::text[],'가나안에 흉년이 들자 요셉의 형들이 애굽에 곡식을 사러 왔고, 총리가 된 요셉을 알아보지 못한 채 그 앞에 엎드렸다.','오래전 꾸었던 꿈이 세월이 지나 그대로 이루어지는 하나님의 섭리를 보여준다.',ARRAY['하나님의 섭리']::text[],'내 삶에서 오래된 약속이나 소망이 뜻밖에 이루어진 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/034'),
(35,'유다가 베냐민을 위해 자신을 내어놓음','구약','창세기',1,'창 44:1-34',ARRAY['유다','베냐민','요셉']::text[],'요셉이 형들을 시험하기 위해 베냐민의 자루에 은잔을 넣게 하자, 한때 요셉을 팔았던 유다가 아버지를 생각하며 자신이 대신 종이 되겠다고 간청하였다.','진정한 회개는 과거의 잘못을 되풀이하지 않고 희생으로 책임지는 삶으로 나타난다.',ARRAY['회개와 용서','가정과 관계']::text[],'나는 과거의 잘못을 어떻게 다른 태도로 바꾸어 살고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/035'),
(36,'요셉이 형들에게 자신을 알림','구약','창세기',1,'창 45:1-28',ARRAY['요셉','요셉의 형들','야곱']::text[],'더 이상 참지 못한 요셉이 형들 앞에서 자신이 요셉임을 밝히며 울었고, 하나님이 생명을 구원하시려고 자신을 먼저 보내셨다 말하며 형들을 위로하였다.','사람이 악을 계획해도 하나님은 그것을 선으로 바꾸어 생명을 구원하는 데 사용하신다.',ARRAY['회개와 용서','하나님의 섭리']::text[],'나를 힘들게 했던 사람이나 사건을 하나님의 더 큰 그림 안에서 다시 바라볼 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/036'),
(37,'야곱 가족이 애굽으로 이주함','구약','창세기',1,'창 46:1-7,27-30',ARRAY['야곱','요셉','하나님']::text[],'야곱이 온 가족을 이끌고 애굽으로 내려가는 길에 브엘세바에서 하나님이 함께하시겠다 약속하셨고, 요셉과 재회한 야곱은 이제 죽어도 여한이 없다고 고백했다.','하나님은 이주와 변화의 길에도 함께하시며 약속을 지키신다.',ARRAY['하나님의 언약','인도하심과 보호']::text[],'낯선 환경으로의 변화 앞에서 하나님의 동행을 어떻게 붙들 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/037'),
(38,'야곱이 열두 아들을 축복하고 죽음','구약','창세기',1,'창 49:1-33',ARRAY['야곱','야곱의 열두 아들']::text[],'죽음을 앞둔 야곱이 열두 아들을 불러 각 지파의 미래를 예언적으로 축복하고 가나안 땅에 장사되기를 부탁한 후 숨을 거두었다.','한 세대의 축복과 믿음의 유산은 다음 세대로 이어져야 한다.',ARRAY['충성과 신실함','가정과 관계']::text[],'나는 다음 세대에게 어떤 신앙의 유산을 물려주고 있는가?',ARRAY['성인']::text[],'v1','/s/038'),
(39,'요셉이 형들을 용서함','구약','창세기',1,'창 50:15-21',ARRAY['요셉','요셉의 형들']::text[],'야곱이 죽은 후 형들이 보복을 두려워하자 요셉은 형들이 악을 계획했으나 하나님이 선으로 바꾸어 오늘의 구원을 이루셨다며 그들을 위로하고 용서하였다.','완전한 용서는 하나님의 더 큰 섭리를 믿을 때 가능해진다.',ARRAY['회개와 용서','하나님의 섭리']::text[],'내게 상처준 사람을 하나님의 섭리 안에서 용서할 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/039'),
(40,'애굽에서 학대받는 이스라엘','구약','출애굽기',2,'출 1:1-22',ARRAY['바로','히브리 산파들(십브라','부아)']::text[],'이스라엘 백성이 번성하자 두려움을 느낀 새 바로가 그들을 학대하고 남자 아기를 죽이라 명했으나, 산파들은 하나님을 경외하여 그 명을 거부했다.','하나님을 경외함은 세상의 권력 앞에서도 옳은 일을 선택할 용기를 준다.',ARRAY['순종과 믿음','용기와 결단']::text[],'권력이나 다수의 압박 속에서 옳은 것을 선택할 용기가 내게 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/040'),
(41,'모세의 출생과 구조','구약','출애굽기',2,'출 2:1-10',ARRAY['모세','모세의 어머니','바로의 딸','미리암']::text[],'모세의 어머니가 아기를 갈대 상자에 담아 나일강에 띄웠고, 바로의 딸이 그를 발견해 길러 모세라 이름 지었다.','작은 순종과 믿음의 결단이 훗날 큰 구원의 시작이 될 수 있다.',ARRAY['하나님의 섭리','인도하심과 보호']::text[],'위기 속에서 내가 할 수 있는 작은 순종은 무엇일까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/041'),
(42,'모세가 미디안으로 도망함','구약','출애굽기',2,'출 2:11-25',ARRAY['모세','애굽인','히브리인','하나님']::text[],'장성한 모세가 동족을 학대하는 애굽인을 쳐 죽이고 발각되자 미디안으로 도망하여 목자가 되었다.','성급한 방법으로 이루려던 계획은 실패하지만, 하나님은 광야의 시간을 통해 사람을 준비시키신다.',ARRAY['순종과 믿음','인도하심과 보호']::text[],'내 삶에서 광야의 훈련 기간이라 느껴지는 시기가 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/042'),
(43,'떨기나무 불꽃과 모세를 부르심','구약','출애굽기',2,'출 3:1-4:17',ARRAY['모세','하나님']::text[],'호렙산에서 불이 붙었으나 타지 않는 떨기나무를 본 모세에게 하나님이 나타나 이스라엘을 구원하라 명하시며 ''스스로 있는 자''라는 이름을 알려주셨다.','하나님은 부족하다고 느끼는 사람을 부르셔서 자신의 이름과 함께하심으로 사명을 감당하게 하신다.',ARRAY['순종과 믿음','인도하심과 보호']::text[],'나의 부족함을 이유로 하나님의 부르심을 주저한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/043'),
(44,'바로 앞에 선 모세, 첫 거절','구약','출애굽기',2,'출 5:1-6:1',ARRAY['모세','아론','바로']::text[],'모세와 아론이 바로에게 백성을 보내라 요구했으나 바로는 오히려 노역을 더 무겁게 하여 백성의 원망을 샀다.','하나님의 뜻을 따르는 길이 처음에는 상황을 더 어렵게 만드는 것처럼 보일 수 있다.',ARRAY['고난과 인내','순종과 믿음']::text[],'상황이 더 어려워질 때도 하나님의 계획을 신뢰할 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/044'),
(45,'아홉 가지 재앙','구약','출애굽기',2,'출 7:14-10:29',ARRAY['모세','아론','바로','하나님']::text[],'하나님이 물이 피로 변함, 개구리, 이, 파리, 가축의 죽음, 악성 종기, 우박, 메뚜기, 흑암의 아홉 재앙으로 애굽을 치셨으나 바로는 마음이 완악하여 계속 거절했다.','완악한 마음은 반복된 경고에도 회개로 나아가지 못하게 만든다.',ARRAY['하나님의 심판','순종과 믿음']::text[],'반복된 은혜의 경고 앞에서도 내 마음이 완악해진 적은 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/045'),
(46,'유월절 제정과 장자의 죽음','구약','출애굽기',2,'출 11:1-12:30',ARRAY['모세','이스라엘 백성','바로']::text[],'하나님이 마지막 재앙으로 애굽의 모든 장자를 치실 것을 예고하시며 어린양의 피를 문설주에 바른 집은 재앙이 넘어가는 유월절을 제정하셨다.','어린양의 피로 인한 구원은 훗날 그리스도의 희생을 예표하는 은혜의 표징이다.',ARRAY['하나님의 구원','예배와 경배']::text[],'유월절 어린양이 예수 그리스도를 어떻게 가리키는지 묵상해보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/046'),
(47,'홍해를 건넘','구약','출애굽기',2,'출 13:17-14:31',ARRAY['모세','이스라엘 백성','바로의 군대']::text[],'애굽 군대에 쫓기던 이스라엘 백성 앞에서 모세가 지팡이를 들자 바다가 갈라져 마른 땅으로 건너고, 뒤따르던 애굽 군대는 물에 잠겼다.','하나님은 막다른 길에서도 백성을 위해 친히 싸우시는 구원자이시다.',ARRAY['하나님의 구원','인도하심과 보호']::text[],'오늘 내가 막다른 길이라고 느끼는 상황에서 하나님을 어떻게 신뢰할 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/047'),
(48,'마라의 쓴물과 만나·메추라기','구약','출애굽기',2,'출 15:22-16:36',ARRAY['모세','이스라엘 백성','하나님']::text[],'마라의 쓴물이 나무로 인해 달게 되었고, 광야에서 굶주린 백성에게 하나님이 매일 만나와 메추라기를 내려 먹이셨다.','하나님은 광야 같은 환경에서도 날마다 필요한 양식을 공급하시는 분이다.',ARRAY['인도하심과 보호','기도와 응답']::text[],'오늘 하루 필요한 것을 하나님께 신뢰함으로 구하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/048'),
(49,'반석에서 물이 남과 아말렉과의 전쟁','구약','출애굽기',2,'출 17:1-16',ARRAY['모세','여호수아','아론','훌','하나님']::text[],'르비딤에서 목마른 백성을 위해 반석에서 물을 내셨고, 아말렉과의 전쟁에서는 모세가 손을 들면 이기고 내리면 지므로 아론과 훌이 그의 팔을 붙들어 주었다.','공동체가 서로 붙들어 세워줄 때 함께 승리를 경험한다.',ARRAY['가정과 관계','기도와 응답']::text[],'나는 지쳐 있는 누군가의 팔을 붙들어준 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/049'),
(50,'이드로의 조언과 재판관 세움','구약','출애굽기',2,'출 18:1-27',ARRAY['모세','이드로']::text[],'장인 이드로가 홀로 모든 백성을 재판하느라 지친 모세에게 능력 있는 자들을 세워 일을 나누라 조언했고, 모세는 그 지혜를 받아들였다.','혼자 모든 짐을 지려는 태도보다 지혜롭게 나누고 위임하는 것이 공동체를 건강하게 한다.',ARRAY['지도자의 리더십','지혜와 분별']::text[],'나는 혼자 감당하려다 지친 일을 나누어야 할 필요는 없는가?',ARRAY['성인']::text[],'v1','/s/050'),
(51,'시내산 강림과 십계명','구약','출애굽기',2,'출 19:1-20:21',ARRAY['모세','이스라엘 백성','하나님']::text[],'하나님이 우레와 번개, 빽빽한 구름 가운데 시내산에 강림하시어 십계명을 비롯한 언약의 법을 백성에게 주셨다.','십계명은 하나님을 향한 사랑과 이웃을 향한 사랑을 구체적으로 가르치는 언약의 기준이다.',ARRAY['율법과 계명']::text[],'십계명 중 오늘 내 삶에 가장 적용이 필요한 계명은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/051'),
(52,'금송아지 사건','구약','출애굽기',2,'출 32:1-35',ARRAY['아론','이스라엘 백성','모세','하나님']::text[],'모세가 산에 오래 머물자 백성이 아론에게 금송아지를 만들게 하여 우상숭배에 빠졌고, 산에서 내려온 모세는 크게 진노하며 율법판을 깨뜨렸다.','눈에 보이는 확신이 사라질 때 사람은 쉽게 우상을 만들어 의지하려 한다.',ARRAY['우상숭배 경계','순종과 믿음']::text[],'기다림이 길어질 때 나는 무엇에 의지하려 하는가?',ARRAY['청소년','성인']::text[],'v1','/s/052'),
(53,'모세가 하나님의 영광을 구함','구약','출애굽기',2,'출 33:12-34:9',ARRAY['모세','하나님']::text[],'금송아지 사건 이후 모세가 하나님의 영광을 보여달라 간구하자 하나님이 그의 등을 지나가시며 자신의 선하심과 이름을 선포하셨다.','하나님을 더 깊이 알고자 하는 간절한 구함에 하나님은 자신을 나타내 보이신다.',ARRAY['기도와 응답','예배와 경배']::text[],'나는 하나님을 더 깊이 알고자 얼마나 간절히 구하는가?',ARRAY['성인']::text[],'v1','/s/053'),
(54,'성막을 위한 자원 예물과 완성','구약','출애굽기',2,'출 35:4-40:38',ARRAY['이스라엘 백성','브살렐','오홀리압','모세']::text[],'백성이 자원하여 예물을 드려 성막의 재료를 마련했고, 완성된 성막에 구름이 덮이며 여호와의 영광이 충만히 임하였다.','기쁨으로 드리는 자원의 헌신이 모여 하나님이 함께하시는 처소를 이룬다.',ARRAY['예배와 경배','사랑과 섬김']::text[],'나는 무엇을 자원하는 마음으로 하나님께 드리고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/054'),
(55,'아론의 제사장 위임식','구약','레위기',3,'레 8:1-9:24',ARRAY['아론','아론의 아들들','모세']::text[],'모세가 하나님의 명대로 아론과 그 아들들에게 제사장 옷을 입히고 기름을 부어 위임했고, 첫 제사 후 여호와의 영광이 나타나 불이 내려와 제물을 살랐다.','거룩한 직분은 하나님의 정하신 방법과 순서를 따라 구별되게 세워진다.',ARRAY['예배와 경배','율법과 계명']::text[],'내가 맡은 섬김의 자리를 얼마나 거룩하고 신중하게 여기고 있는가?',ARRAY['성인']::text[],'v1','/s/055'),
(56,'나답과 아비후의 죽음','구약','레위기',3,'레 10:1-7',ARRAY['나답','아비후','아론','하나님']::text[],'아론의 아들 나답과 아비후가 하나님이 명하지 않은 다른 불로 분향하다가 여호와 앞에서 불이 나와 죽임을 당했다.','하나님을 향한 예배는 자기 방식이 아니라 하나님이 정하신 방법을 따라야 한다.',ARRAY['예배와 경배','순종과 믿음']::text[],'나는 신앙생활에서 내 방식과 하나님의 방식 중 어느 것을 우선하는가?',ARRAY['성인']::text[],'v1','/s/056'),
(57,'대속죄일 규례','구약','레위기',3,'레 16:1-34',ARRAY['아론','이스라엘 백성','하나님']::text[],'일 년에 한 번 대제사장이 지성소에 들어가 속죄제를 드리고, 아사셀 염소에게 백성의 죄를 지워 광야로 보내는 대속죄일 규례가 주어졌다.','죄 사함을 위해서는 반드시 피 흘림이 필요하며, 이는 그리스도의 온전한 속죄를 예표한다.',ARRAY['하나님의 구원','회개와 용서']::text[],'대속죄일의 그림이 그리스도의 십자가와 어떻게 연결되는지 나눠보자.',ARRAY['성인']::text[],'v1','/s/057'),
(58,'희년 규례','구약','레위기',3,'레 25:1-55',ARRAY['이스라엘 백성','하나님']::text[],'하나님이 칠 년마다 안식년을, 오십 년마다 희년을 지켜 땅을 쉬게 하고 종을 자유케 하며 팔린 기업을 되돌려주라 명하셨다.','희년의 정신은 회복과 자유를 통해 공동체 안의 불균형을 정기적으로 바로잡는 하나님의 정의이다.',ARRAY['율법과 계명','사랑과 섬김']::text[],'내 주변에서 회복과 자유가 필요한 관계나 상황은 무엇인가?',ARRAY['성인']::text[],'v1','/s/058'),
(59,'열두 정탐꾼과 백성의 반역','구약','민수기',4,'민 13:1-14:38',ARRAY['여호수아','갈렙','열 명의 정탐꾼','이스라엘 백성']::text[],'가나안을 정탐한 열두 명 중 열 명은 두려움에 부정적 보고를 했으나 여호수아와 갈렙은 믿음으로 올라가자 했고, 백성이 그들을 돌로 치려 하자 하나님은 그 세대가 광야에서 죽으리라 선고하셨다.','눈에 보이는 장애물보다 하나님의 약속을 믿는 믿음의 보고가 필요하다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 상황을 보고할 때 두려움과 믿음 중 무엇을 앞세우는가?',ARRAY['청소년','성인']::text[],'v1','/s/059'),
(60,'고라의 반역','구약','민수기',4,'민 16:1-35',ARRAY['고라','다단','아비람','모세','아론']::text[],'고라와 그 무리가 모세와 아론의 지도력에 도전하여 반역했으나 땅이 갈라져 그들을 삼키고 불이 내려와 나머지를 태웠다.','하나님이 세우신 질서와 지도력에 대한 도전은 심각한 결과를 낳는다.',ARRAY['지도자의 리더십','시기와 갈등']::text[],'공동체 안의 리더십에 대해 나는 어떤 태도로 반응하는가?',ARRAY['성인']::text[],'v1','/s/060'),
(61,'놋뱀 사건','구약','민수기',4,'민 21:4-9',ARRAY['모세','이스라엘 백성','하나님']::text[],'백성이 다시 원망하자 불뱀이 물어 많은 사람이 죽었고, 모세가 하나님의 명대로 놋뱀을 만들어 장대에 달자 그것을 본 자마다 살았다.','죄로 인한 죽음 앞에서 하나님이 정하신 구원의 표를 바라보는 믿음이 생명을 준다.',ARRAY['하나님의 구원','순종과 믿음']::text[],'예수님이 놋뱀처럼 들리신 사건(요 3장)과 이 이야기를 연결해보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/061'),
(62,'발람과 나귀','구약','민수기',4,'민 22:1-38',ARRAY['발람','발락','나귀','여호와의 사자']::text[],'모압 왕 발락이 이스라엘을 저주하도록 발람을 청했으나, 하나님이 나귀의 입을 열어 발람을 꾸짖으시고 결국 발람은 저주 대신 축복만을 선포하게 되었다.','하나님은 이방인의 계획과 짐승의 입까지도 사용하셔서 자신의 뜻을 이루신다.',ARRAY['하나님의 섭리','지혜와 분별']::text[],'하나님의 뜻을 거스르려던 내 계획이 오히려 막힌 경험이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/062'),
(63,'여호수아를 후계자로 세움','구약','민수기',4,'민 27:12-23',ARRAY['모세','여호수아','엘르아살','하나님']::text[],'약속의 땅에 들어가지 못하게 된 모세가 하나님의 명대로 여호수아에게 안수하여 백성을 이끌 후계자로 세웠다.','한 세대의 지도력은 하나님의 인도 아래 다음 세대로 아름답게 이어져야 한다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 다음 세대에게 리더십을 넘겨줄 준비를 하고 있는가?',ARRAY['성인']::text[],'v1','/s/063'),
(64,'쉐마: 이스라엘아 들으라','구약','신명기',5,'신 6:1-9',ARRAY['모세','이스라엘 백성']::text[],'모세가 백성에게 마음과 뜻과 힘을 다해 하나님을 사랑하고 그 말씀을 자녀에게 부지런히 가르치라고 당부하였다.','하나님을 향한 사랑은 삶의 모든 순간과 다음 세대 교육의 중심이 되어야 한다.',ARRAY['순종과 믿음','가정과 관계']::text[],'나는 일상 속에서 신앙을 자녀나 다음 세대에게 어떻게 가르치고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/064'),
(65,'생명과 복, 죽음과 저주 중 택하라','구약','신명기',5,'신 30:11-20',ARRAY['모세','이스라엘 백성','하나님']::text[],'모세가 하나님의 말씀은 멀리 있지 않고 마음에 있다 말하며, 백성에게 생명과 복 혹은 죽음과 저주 중에서 생명을 택하라고 권면하였다.','순종의 말씀은 실천 불가능한 먼 것이 아니라 이미 우리 마음 가까이 주어져 있다.',ARRAY['순종과 믿음','용기와 결단']::text[],'오늘 나는 생명의 길과 안일한 길 중 무엇을 택하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/065'),
(66,'모세의 죽음','구약','신명기',5,'신 34:1-12',ARRAY['모세','여호수아','하나님']::text[],'백이십 세의 모세가 느보산에서 약속의 땅을 바라본 후 그 땅에 들어가지 못한 채 죽었고, 하나님이 친히 그를 장사하셨다.','평생을 하나님께 순종한 종의 삶은 마지막까지 존귀하게 기억된다.',ARRAY['충성과 신실함','고난과 인내']::text[],'나는 결과를 다 보지 못하더라도 끝까지 순종할 믿음이 있는가?',ARRAY['성인']::text[],'v1','/s/066'),
(67,'라합과 정탐꾼','구약','여호수아',6,'수 2:1-24',ARRAY['라합','두 정탐꾼','여호수아']::text[],'여리고에 보낸 두 정탐꾼을 기생 라합이 숨겨 보호하며 자기 가족을 살려달라 요청했고, 정탐꾼들은 붉은 줄을 창에 매달면 구원받으리라 약속했다.','믿음으로 행한 라합의 결단은 이방 여인이었음에도 구원과 은혜의 계보에 들어가는 길이 되었다.',ARRAY['순종과 믿음','하나님의 구원']::text[],'외부인이나 소외된 이의 작은 믿음의 결단을 우리는 어떻게 존중하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/067'),
(68,'요단강을 건넘','구약','여호수아',6,'수 3:1-4:24',ARRAY['여호수아','제사장들','이스라엘 백성']::text[],'제사장들이 언약궤를 메고 요단강에 발을 내딛자 강물이 멈춰 백성이 마른 땅으로 건넜고, 열두 지파를 따라 기념비를 세웠다.','하나님은 순종의 첫걸음을 내딛는 자 앞에서 길을 여시며, 기념은 다음 세대에게 신앙을 전수하는 방법이다.',ARRAY['순종과 믿음','하나님의 구원']::text[],'우리 가정과 공동체에는 하나님의 은혜를 기념하는 표가 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/068'),
(69,'여리고 성 함락','구약','여호수아',6,'수 6:1-27',ARRAY['여호수아','이스라엘 백성','라합']::text[],'하나님의 지시대로 이스라엘 백성이 엿새 동안 여리고 성을 돌고 일곱째 날 일곱 바퀴를 돈 후 외치자 성벽이 무너졌다.','사람의 눈에 어리석어 보이는 방법도 순종하면 하나님의 능력으로 승리를 이룬다.',ARRAY['순종과 믿음','하나님의 구원']::text[],'이해되지 않아도 순종했을 때 하나님이 이루신 일이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/069'),
(70,'아간의 범죄와 아이 성 패배','구약','여호수아',6,'수 7:1-26',ARRAY['아간','여호수아','이스라엘 백성']::text[],'여리고에서 바친 물건을 몰래 취한 아간의 범죄로 인해 이스라엘이 작은 아이 성 전투에서 패배했고, 죄가 드러난 아간은 심판을 받았다.','한 사람의 숨겨진 죄가 공동체 전체의 승패에 영향을 미칠 수 있다.',ARRAY['죄와 타락','충성과 신실함']::text[],'드러나지 않았지만 공동체에 영향을 줄 수 있는 나의 숨은 죄는 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/070'),
(71,'기브온 족속의 속임수','구약','여호수아',6,'수 9:1-27',ARRAY['기브온 사람들','여호수아','이스라엘 지도자들']::text[],'기브온 사람들이 먼 나라에서 온 것처럼 속여 이스라엘과 화친 조약을 맺었고, 이스라엘 지도자들은 하나님께 묻지 않고 성급히 맹세하여 훗날 이를 지키기 위해 애썼다.','중요한 결정을 내릴 때 하나님께 묻지 않고 겉모습만으로 판단하면 낭패를 볼 수 있다.',ARRAY['지혜와 분별']::text[],'중요한 결정 전에 나는 하나님께 충분히 묻고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/071'),
(72,'태양이 멈춘 전쟁','구약','여호수아',6,'수 10:1-15',ARRAY['여호수아','이스라엘 백성','다섯 아모리 왕']::text[],'기브온을 도우러 나선 여호수아가 전쟁 중 하나님께 태양이 머물기를 구하자 하루 동안 해가 지지 않아 이스라엘이 완전한 승리를 거두었다.','하나님은 자기 백성을 위해 자연 질서까지도 움직이시는 분이다.',ARRAY['하나님의 구원','기도와 응답']::text[],'불가능해 보이는 상황에서 담대히 하나님께 구한 기도가 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/072'),
(73,'여호수아의 마지막 당부와 언약 갱신','구약','여호수아',6,'수 23:1-24:28',ARRAY['여호수아','이스라엘 백성']::text[],'늙은 여호수아가 백성을 세겜에 모아 지난날 하나님의 신실하심을 회고하며 오늘날 섬길 자를 택하라 권면했고, 백성은 여호와를 섬기겠다 언약했다.','신앙의 유산을 이어받은 세대는 스스로 하나님을 섬기기로 결단해야 한다.',ARRAY['순종과 믿음','충성과 신실함']::text[],'나는 부모 세대의 신앙을 물려받아 스스로 하나님을 섬기기로 결단했는가?',ARRAY['청소년','성인']::text[],'v1','/s/073'),
(74,'사사 시대의 반복되는 패턴','구약','사사기',7,'삿 2:6-23',ARRAY['이스라엘 백성','하나님','사사들']::text[],'여호수아 세대가 지나자 백성은 우상을 섬기다 압제를 받고 부르짖으면 하나님이 사사를 세워 구원하시는 패턴이 사사기 내내 반복되었다.','죄와 회개, 구원이 반복되는 역사는 사람의 연약함과 하나님의 변함없는 긍휼을 동시에 보여준다.',ARRAY['죄와 타락','하나님의 구원']::text[],'내 신앙생활에도 반복되는 죄와 회개의 패턴이 있다면 무엇인가?',ARRAY['성인']::text[],'v1','/s/074'),
(75,'드보라와 바락','구약','사사기',7,'삿 4:1-5:31',ARRAY['드보라','바락','야엘','시스라']::text[],'여선지자 드보라가 바락에게 가나안 군대장관 시스라와 싸우라 명했고, 승리 후 도망친 시스라는 야엘의 장막에서 죽임을 당했다.','하나님은 시대의 필요를 따라 남녀를 가리지 않고 지도자를 세워 구원을 이루신다.',ARRAY['지도자의 리더십','용기와 결단']::text[],'하나님이 주신 자리에서 담대히 순종한 여성 지도자들을 떠올려보자.',ARRAY['청소년','성인']::text[],'v1','/s/075'),
(76,'기드온의 부르심과 삼백 용사','구약','사사기',7,'삿 6:1-7:25',ARRAY['기드온','이스라엘 백성','미디안 군대']::text[],'두려움 많던 기드온이 하나님의 부르심을 받아 양털 표징으로 확인받고, 삼만 이천 명 중 삼백 명만으로 미디안 대군을 물리쳤다.','적은 수라도 하나님이 함께하시면 큰 승리를 이룰 수 있으니, 승리의 영광은 사람이 아닌 하나님께 있다.',ARRAY['하나님의 구원','용기와 결단']::text[],'내가 부족하다고 느끼는 상황에서도 하나님을 신뢰하며 나아갈 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/076'),
(77,'아비멜렉의 반역과 몰락','구약','사사기',7,'삿 8:22-9:57',ARRAY['아비멜렉','기드온의 아들들','세겜 사람들']::text[],'기드온의 아들 아비멜렉이 칠십 형제를 죽이고 스스로 왕이 되었으나 결국 세겜 사람들의 배신과 한 여인이 던진 맷돌에 맞아 비참하게 죽었다.','권력을 위해 형제를 해치는 야망은 결국 스스로를 파멸로 이끈다.',ARRAY['시기와 갈등','겸손과 교만']::text[],'권력이나 성공을 위해 관계를 해치려는 유혹을 어떻게 경계할 수 있을까?',ARRAY['성인']::text[],'v1','/s/077'),
(78,'입다와 그의 서원','구약','사사기',7,'삿 11:1-40',ARRAY['입다','입다의 딸','암몬 자손']::text[],'버림받았던 입다가 암몬과의 전쟁에서 사사로 부름받아 승리했으나, 경솔한 서원으로 인해 자신의 딸을 잃는 슬픔을 겪었다.','경솔한 말과 서원은 돌이킬 수 없는 아픔을 남길 수 있으니 말을 신중히 해야 한다.',ARRAY['지혜와 분별','고난과 인내']::text[],'나는 말을 하기 전에 그 결과를 충분히 생각하는가?',ARRAY['성인']::text[],'v1','/s/078'),
(79,'삼손의 출생과 부르심','구약','사사기',7,'삿 13:1-25',ARRAY['마노아','마노아의 아내','삼손','여호와의 사자']::text[],'자녀가 없던 마노아 부부에게 천사가 나타나 나실인으로 구별된 아들 삼손의 출생을 예고하였다.','하나님은 특별한 사명을 위해 태어나기 전부터 사람을 구별하여 준비시키신다.',ARRAY['하나님의 섭리','순종과 믿음']::text[],'내 삶을 향한 하나님의 특별한 계획이 있다고 믿는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/079'),
(80,'삼손과 들릴라','구약','사사기',7,'삿 16:1-31',ARRAY['삼손','들릴라','블레셋 사람들']::text[],'삼손이 들릴라의 거듭된 유혹에 넘어가 자신의 힘의 비밀을 말했다가 머리털이 잘리고 두 눈이 뽑혔으나, 마지막 기도로 다곤 신전을 무너뜨리며 죽었다.','반복된 유혹에 타협하면 하나님이 주신 은사와 자유마저 잃을 수 있으나, 회개하는 자에게는 마지막 기회도 주어진다.',ARRAY['죄와 타락','회개와 용서']::text[],'반복해서 나를 넘어뜨리는 유혹은 무엇이며 어떻게 끊어낼 수 있을까?',ARRAY['청소년','성인']::text[],'v1','/s/080'),
(81,'레위인의 첩 사건과 도덕적 혼란','구약','사사기',7,'삿 19:1-21:25',ARRAY['레위인','베냐민 지파','이스라엘 백성']::text[],'기브아에서 벌어진 참혹한 사건으로 이스라엘 지파들 간에 내전이 일어났고, ''그 때에는 왕이 없으므로 각자 자기 소견에 옳은 대로 행하였더라''는 말씀으로 사사기가 끝난다.','지도력과 기준이 무너진 사회는 극심한 혼란과 폭력으로 치닫게 된다.',ARRAY['지도자의 리더십','하나님의 심판']::text[],'우리 사회와 공동체에는 옳고 그름의 분명한 기준이 세워져 있는가?',ARRAY['성인']::text[],'v1','/s/081'),
(82,'나오미와 룻의 결단','구약','룻기',8,'룻 1:1-22',ARRAY['나오미','룻','오르바']::text[],'흉년에 모압으로 갔던 나오미가 남편과 두 아들을 잃고 고향으로 돌아가려 하자, 며느리 룻은 ''어머니의 하나님이 나의 하나님''이라며 끝까지 동행하기로 결단했다.','진정한 사랑과 신실함은 손해를 감수하고도 끝까지 함께하는 결단으로 드러난다.',ARRAY['충성과 신실함','가정과 관계']::text[],'나는 어려운 상황에서도 끝까지 신의를 지킨 관계가 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/082'),
(83,'룻이 보아스의 밭에서 이삭을 줍다','구약','룻기',8,'룻 2:1-23',ARRAY['룻','보아스','나오미']::text[],'가난한 룻이 이삭줍기를 하러 나간 밭이 마침 나오미의 친족 보아스의 밭이었고, 보아스는 룻의 성실함과 효성을 알고 그를 특별히 배려하였다.','성실하게 최선을 다하는 삶에 하나님은 뜻밖의 은혜의 통로를 예비하신다.',ARRAY['인도하심과 보호','사랑과 섬김']::text[],'작은 성실함이 큰 은혜로 이어진 경험이 내게도 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/083'),
(84,'보아스가 기업 무를 자가 됨','구약','룻기',8,'룻 3:1-4:22',ARRAY['룻','보아스','나오미','기업 무를 자']::text[],'나오미의 지혜로운 인도로 룻이 보아스에게 기업 무를 자의 역할을 구하였고, 보아스는 절차를 따라 룻을 아내로 맞아 오벳을 낳았으니 그는 다윗의 조상이 되었다.','신실한 순종과 헌신은 한 가정을 넘어 하나님의 큰 구원 역사의 계보로 이어진다.',ARRAY['하나님의 섭리','충성과 신실함']::text[],'작은 순종이 하나님의 큰 그림 속에서 어떻게 쓰이는지 생각해보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/084'),
(85,'한나의 기도와 사무엘의 출생','구약','사무엘상',9,'삼상 1:1-28',ARRAY['한나','엘가나','엘리','사무엘']::text[],'자녀가 없어 슬퍼하던 한나가 성전에서 간절히 기도하여 아들 사무엘을 얻은 후, 그를 하나님께 드리겠다는 서원대로 성전에 바쳤다.','간절한 기도와 서원의 헌신은 하나님이 응답하신 것을 다시 하나님께 온전히 드리는 신앙의 본이 된다.',ARRAY['기도와 응답','사랑과 섬김']::text[],'응답받은 기도의 제목을 다시 하나님께 드린 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/085'),
(86,'사무엘을 부르시는 하나님','구약','사무엘상',9,'삼상 3:1-21',ARRAY['사무엘','엘리','하나님']::text[],'밤에 성전에서 자던 어린 사무엘이 자신을 부르는 음성을 듣고 엘리의 가르침대로 ''여호와여 말씀하옵소서 종이 듣겠나이다'' 응답하며 선지자로 부름받았다.','하나님의 음성에 귀 기울이고 순종하는 자세는 어릴 때부터 훈련될 수 있다.',ARRAY['순종과 믿음','예배와 경배']::text[],'나는 일상에서 하나님의 음성을 분별하고 듣는 훈련을 하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/086'),
(87,'언약궤를 빼앗기고 엘리가 죽음','구약','사무엘상',9,'삼상 4:1-22',ARRAY['엘리','홉니','비느하스','블레셋 사람들']::text[],'이스라엘이 블레셋과의 전쟁에서 언약궤를 미신처럼 앞세웠다가 빼앗기고 엘리의 두 아들이 죽었으며, 소식을 들은 엘리도 뒤로 넘어져 죽었다.','하나님의 임재의 상징을 부적처럼 여기는 형식적 신앙은 참된 능력이 될 수 없다.',ARRAY['우상숭배 경계','예배와 경배']::text[],'나는 신앙의 형식과 하나님과의 실제 관계 중 무엇에 더 의지하는가?',ARRAY['청소년','성인']::text[],'v1','/s/087'),
(88,'언약궤가 블레셋에서 돌아옴','구약','사무엘상',9,'삼상 5:1-7:2',ARRAY['블레셋 사람들','다곤 신상','이스라엘 백성']::text[],'언약궤를 빼앗은 블레셋 땅에 재앙이 임하고 다곤 신상이 엎드러지자 그들은 두려워하며 언약궤를 수레에 실어 이스라엘로 돌려보냈다.','하나님의 주권은 어떤 상황에서도 훼손되지 않으며 우상은 하나님 앞에 설 수 없다.',ARRAY['하나님의 심판','우상숭배 경계']::text[],'내 삶에서 하나님보다 앞세우고 있는 것은 없는지 돌아보자.',ARRAY['청소년','성인']::text[],'v1','/s/088'),
(89,'백성이 왕을 요구함','구약','사무엘상',9,'삼상 8:1-22',ARRAY['이스라엘 장로들','사무엘','하나님']::text[],'늙은 사무엘의 아들들이 부패하자 백성은 다른 나라처럼 왕을 세워달라 요구했고, 하나님은 이를 자신을 버리는 것으로 여기셨지만 백성의 요구를 허락하셨다.','사람의 눈에 좋아 보이는 선택이 하나님을 왕으로 모시지 않으려는 마음일 수 있음을 경계해야 한다.',ARRAY['지도자의 리더십','순종과 믿음']::text[],'나는 하나님보다 사람의 방법과 기준을 더 의지하려 한 적이 없는가?',ARRAY['성인']::text[],'v1','/s/089'),
(90,'사울이 왕으로 기름부음 받음','구약','사무엘상',9,'삼상 9:1-10:27',ARRAY['사울','사무엘','하나님']::text[],'아버지의 잃어버린 나귀를 찾으러 나섰던 사울이 사무엘을 만나 이스라엘의 초대 왕으로 기름부음을 받았다.','하나님은 사람이 예상치 못한 평범한 일상 속에서 특별한 부르심을 시작하신다.',ARRAY['하나님의 섭리','지도자의 리더십']::text[],'평범한 일상 가운데 하나님이 예비하신 부르심이 있다면 무엇일까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/090'),
(91,'사울이 제사를 잘못 드려 책망받음','구약','사무엘상',9,'삼상 13:1-14',ARRAY['사울','사무엘','이스라엘 군대']::text[],'블레셋과의 전쟁 중 사무엘을 기다리지 못한 사울이 제사장이 아님에도 번제를 직접 드렸다가 사무엘에게 책망을 받고 왕조가 이어지지 못하리라는 말을 들었다.','조급함으로 하나님이 정하신 질서를 넘어서는 것은 신뢰를 잃는 결과를 낳는다.',ARRAY['순종과 믿음','겸손과 교만']::text[],'기다림이 힘들 때 나는 하나님의 질서를 넘어서려 한 적이 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/091'),
(92,'사울이 아말렉을 진멸하지 않아 버림받음','구약','사무엘상',9,'삼상 15:1-35',ARRAY['사울','사무엘','아각','하나님']::text[],'하나님이 아말렉을 진멸하라 명하셨으나 사울이 좋은 것들을 남기고 자기 뜻대로 행하자, 사무엘은 순종이 제사보다 낫다고 책망하며 그가 왕위에서 버림받았음을 선포했다.','부분적 순종은 온전한 불순종과 같으며, 하나님은 형식적 제사보다 진심 어린 순종을 원하신다.',ARRAY['순종과 믿음','겸손과 교만']::text[],'나는 하나님의 명령을 내 방식대로 조정해서 지키려 한 적이 없는가?',ARRAY['청소년','성인']::text[],'v1','/s/092'),
(93,'다윗이 왕으로 기름부음 받음','구약','사무엘상',9,'삼상 16:1-13',ARRAY['다윗','사무엘','이새','하나님']::text[],'하나님이 사무엘을 이새의 집으로 보내 외모가 아닌 중심을 보시고 막내 다윗을 이스라엘의 왕으로 택하여 기름 붓게 하셨다.','사람은 외모를 보나 하나님은 중심을 보시니, 겉모습으로 사람을 판단하지 않아야 한다.',ARRAY['지혜와 분별','하나님의 섭리']::text[],'나는 사람을 외모나 조건이 아닌 중심으로 바라보려 노력하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/093'),
(94,'다윗과 골리앗','구약','사무엘상',9,'삼상 17:1-58',ARRAY['다윗','골리앗','사울','이스라엘 군대']::text[],'블레셋 거인 골리앗이 이스라엘을 조롱할 때 어린 다윗이 물맷돌 하나로 그를 쓰러뜨리며 전쟁이 여호와께 속했음을 선포했다.','크기와 힘이 아니라 하나님을 향한 믿음이 진정한 승리의 근거이다.',ARRAY['순종과 믿음','용기와 결단']::text[],'내 앞의 ''골리앗'' 같은 문제 앞에서 나는 무엇을 의지하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/094'),
(95,'다윗과 요나단의 우정','구약','사무엘상',9,'삼상 18:1-4,20:1-42',ARRAY['다윗','요나단','사울']::text[],'사울의 아들 요나단이 다윗을 자기 생명처럼 사랑하여 언약을 맺었고, 아버지 사울이 다윗을 죽이려 하자 위험을 무릅쓰고 그에게 사실을 알려주었다.','진정한 우정은 자신의 지위와 안전을 넘어 상대를 지키는 신실함으로 나타난다.',ARRAY['가정과 관계','충성과 신실함']::text[],'나는 손해를 감수하고서라도 친구를 지켜준 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/095'),
(96,'다윗이 사울을 살려줌','구약','사무엘상',9,'삼상 24:1-22,26:1-25',ARRAY['다윗','사울','아비새']::text[],'사울이 자신을 죽이려 쫓아다니는 중에도 다윗은 엔게디 동굴과 진영에서 두 번이나 사울을 죽일 기회를 얻었으나 기름부음 받은 자를 해치지 않겠다며 그를 살려주었다.','원수를 갚을 기회가 있어도 하나님의 때를 기다리는 것이 참된 신앙의 성숙이다.',ARRAY['고난과 인내','회개와 용서']::text[],'복수할 힘이 있어도 참고 하나님께 맡긴 경험이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/096'),
(97,'다윗과 아비가일','구약','사무엘상',9,'삼상 25:1-42',ARRAY['다윗','아비가일','나발']::text[],'다윗의 도움을 받고도 은혜를 모르는 나발에게 분노한 다윗이 보복하려 하자, 나발의 지혜로운 아내 아비가일이 그를 설득하여 피 흘림을 막았다.','지혜로운 중재는 순간의 분노로 인한 돌이킬 수 없는 죄를 막아준다.',ARRAY['지혜와 분별','분노 다스림']::text[],'분노로 잘못된 행동을 하려 할 때 나를 멈추게 하는 것은 무엇인가?',ARRAY['성인']::text[],'v1','/s/097'),
(98,'사울이 엔돌의 신접한 여인을 찾아감','구약','사무엘상',9,'삼상 28:3-25',ARRAY['사울','엔돌의 신접한 여인','사무엘의 영']::text[],'전쟁을 앞두고 하나님의 응답을 받지 못한 사울이 금지된 신접한 여인을 찾아가 죽은 사무엘의 영을 불러 패망을 예고받았다.','하나님을 떠난 자리에서 금지된 방법으로 답을 구하는 것은 더 깊은 절망으로 이어진다.',ARRAY['우상숭배 경계','하나님의 심판']::text[],'응답이 없을 때 나는 하나님이 금하신 방법에 기대려 한 적은 없는가?',ARRAY['성인']::text[],'v1','/s/098'),
(99,'사울의 죽음','구약','사무엘상',9,'삼상 31:1-13',ARRAY['사울','요나단','블레셋 사람들']::text[],'길보아 산 전투에서 아들들을 잃고 크게 부상당한 사울이 블레셋의 손에 죽기보다 스스로 목숨을 끊어 파란만장한 통치가 끝났다.','하나님을 떠난 통치의 결말은 비극으로 끝날 수 있음을 엄중히 보여준다.',ARRAY['하나님의 심판','순종과 믿음']::text[],'내 삶의 방향이 하나님을 떠난 길로 가고 있지는 않은지 돌아보자.',ARRAY['성인']::text[],'v1','/s/099'),
(100,'다윗이 사울과 요나단의 죽음을 애도함','구약','사무엘하',10,'삼하 1:1-27',ARRAY['다윗','사울','요나단']::text[],'사울과 요나단의 전사 소식을 들은 다윗은 원수였던 사울에 대해서도 진심으로 애곡하며 그들의 죽음을 슬퍼하는 노래를 지었다.','원수였던 사람의 죽음 앞에서도 인간에 대한 존중과 슬픔을 표현하는 성숙한 태도가 필요하다.',ARRAY['가정과 관계','고난과 인내']::text[],'나는 나와 갈등했던 사람의 아픔에도 진심으로 공감할 수 있는가?',ARRAY['성인']::text[],'v1','/s/100'),
(101,'다윗이 온 이스라엘의 왕이 되고 예루살렘을 점령함','구약','사무엘하',10,'삼하 5:1-10',ARRAY['다윗','이스라엘 장로들','여부스 족속']::text[],'유다의 왕이었던 다윗이 마침내 온 이스라엘의 왕으로 기름부음을 받고 여부스 족속의 성 예루살렘을 정복하여 다윗성이라 이름했다.','오랜 기다림 끝에 하나님의 약속이 온전히 이루어지는 때가 반드시 찾아온다.',ARRAY['하나님의 섭리','지도자의 리더십']::text[],'오랫동안 기다려온 하나님의 약속이 이루어진 경험을 나눠보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/101'),
(102,'언약궤를 예루살렘으로 옮김','구약','사무엘하',10,'삼하 6:1-23',ARRAY['다윗','웃사','언약궤']::text[],'다윗이 언약궤를 예루살렘으로 옮기던 중 규례를 어겨 웃사가 죽는 일을 겪은 후, 다시 규례대로 옮기며 기쁨으로 춤추며 찬양했다.','하나님께 나아가는 예배는 기쁨이 넘치되 그분이 정하신 거룩한 방법을 따라야 한다.',ARRAY['예배와 경배','율법과 계명']::text[],'나는 예배할 때 형식과 진심, 기쁨과 거룩함의 균형을 이루고 있는가?',ARRAY['성인']::text[],'v1','/s/102'),
(103,'다윗 언약','구약','사무엘하',10,'삼하 7:1-29',ARRAY['다윗','나단','하나님']::text[],'성전을 짓고자 했던 다윗에게 하나님은 오히려 그의 집(왕조)을 영원히 세우시겠다는 언약을 나단을 통해 주셨다.','하나님의 언약은 사람의 계획을 뛰어넘어 더 크고 영원한 은혜로 응답하신다.',ARRAY['하나님의 언약']::text[],'내가 하나님께 드리려던 계획보다 더 크게 응답하신 은혜가 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/103'),
(104,'다윗과 밧세바','구약','사무엘하',10,'삼하 11:1-27',ARRAY['다윗','밧세바','우리아']::text[],'전장에 나가지 않고 왕궁에 머물던 다윗이 밧세바를 범하고 그 죄를 숨기려 충성스러운 우리아를 죽음에 이르게 했다.','안일함 속에서 시작된 작은 유혹이 회개하지 않으면 더 큰 죄로 이어질 수 있다.',ARRAY['죄와 타락','회개와 용서']::text[],'작은 유혹의 순간에 나는 어떻게 멈춰 서고 있는가?',ARRAY['성인']::text[],'v1','/s/104'),
(105,'나단의 책망과 다윗의 회개','구약','사무엘하',10,'삼하 12:1-25',ARRAY['다윗','나단','하나님']::text[],'나단 선지자가 ''한 마리 양을 빼앗은 부자'' 비유로 다윗의 죄를 깨닫게 하자, 다윗은 ''내가 여호와께 죄를 범하였노라'' 고백하며 진심으로 회개했다.','죄를 지적받을 때 변명하지 않고 즉시 인정하며 돌이키는 것이 참된 회개이다.',ARRAY['회개와 용서','죄와 타락']::text[],'나는 잘못을 지적받았을 때 변명 대신 정직하게 인정하는가?',ARRAY['성인']::text[],'v1','/s/105'),
(106,'압살롬의 반역','구약','사무엘하',10,'삼하 15:1-18:33',ARRAY['압살롬','다윗','요압']::text[],'다윗의 아들 압살롬이 백성의 마음을 훔쳐 반역을 일으켰고, 다윗은 예루살렘을 떠나 피신했으며 결국 압살롬은 전투 중 나무에 걸려 죽었다.','가정 안의 죄와 방치된 갈등은 자녀 세대에 더 큰 아픔으로 되돌아올 수 있다.',ARRAY['가정과 관계','고난과 인내']::text[],'우리 가정 안에 오래 방치된 갈등이나 상처는 없는지 살펴보자.',ARRAY['성인']::text[],'v1','/s/106'),
(107,'솔로몬이 왕이 되고 지혜를 구함','구약','열왕기상',11,'왕상 1:1-3:15',ARRAY['솔로몬','다윗','하나님']::text[],'다윗을 이어 왕이 된 솔로몬이 기브온에서 제사를 드릴 때 하나님이 무엇을 원하느냐 물으시니 그는 부귀 대신 백성을 다스릴 지혜를 구하여 하나님을 기쁘시게 했다.','자신의 유익보다 맡겨진 사람들을 잘 섬기기 위한 지혜를 구하는 것이 참된 리더십의 시작이다.',ARRAY['지도자의 리더십','지혜와 분별']::text[],'나는 내 유익과 공동체를 위한 지혜 중 무엇을 먼저 구하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/107'),
(108,'솔로몬의 재판(두 어머니와 한 아기)','구약','열왕기상',11,'왕상 3:16-28',ARRAY['솔로몬','두 여인']::text[],'한 아기를 두고 서로 자기 아들이라 다투는 두 여인 앞에서 솔로몬이 아기를 반으로 가르라 명하자 진짜 어머니가 포기하겠다며 자비를 구해 지혜롭게 진실을 가려냈다.','참된 지혜는 겉모습이 아니라 마음의 진심을 꿰뚫어 보는 통찰에서 나온다.',ARRAY['지혜와 분별']::text[],'나는 겉모습이 아닌 진심을 분별하는 지혜를 구하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/108'),
(109,'성전 건축과 봉헌','구약','열왕기상',11,'왕상 6:1-8:66',ARRAY['솔로몬','이스라엘 백성','하나님']::text[],'솔로몬이 칠 년에 걸쳐 웅장한 성전을 건축하고 봉헌 기도를 드리자 여호와의 영광이 구름 가운데 성전에 가득하였다.','백성의 예배 중심인 성전은 하나님이 임재하시는 처소로서 정성과 헌신으로 세워져야 한다.',ARRAY['예배와 경배','순종과 믿음']::text[],'나는 하나님이 거하실 처소로서의 내 마음을 얼마나 정성껏 준비하는가?',ARRAY['성인']::text[],'v1','/s/109'),
(110,'스바 여왕의 방문','구약','열왕기상',11,'왕상 10:1-13',ARRAY['스바 여왕','솔로몬']::text[],'솔로몬의 지혜와 영화에 대한 소문을 들은 스바 여왕이 직접 찾아와 어려운 질문들로 그를 시험하고 그 지혜와 부요함에 크게 감탄하였다.','진정한 지혜와 영광은 멀리서도 소문을 듣고 찾아올 만큼 사람을 이끄는 힘이 있다.',ARRAY['지혜와 분별']::text[],'내 삶이나 공동체의 무엇이 다른 이들에게 하나님을 궁금하게 만들 수 있을까?',ARRAY['청소년','성인']::text[],'v1','/s/110'),
(111,'솔로몬의 타락','구약','열왕기상',11,'왕상 11:1-13',ARRAY['솔로몬','이방 왕비들','하나님']::text[],'말년의 솔로몬이 이방 여인들을 아내로 맞아들여 그들의 우상을 따라 섬기니 하나님이 진노하시어 나라가 그의 아들 대에 갈라질 것을 선고하셨다.','아무리 지혜로운 사람도 마음이 하나님을 떠나면 결국 우상숭배와 몰락으로 이어질 수 있다.',ARRAY['우상숭배 경계','죄와 타락']::text[],'나는 신앙의 연륜이 쌓일수록 오히려 안일해지는 부분은 없는가?',ARRAY['성인']::text[],'v1','/s/111'),
(112,'나라가 둘로 갈라짐','구약','열왕기상',11,'왕상 12:1-33',ARRAY['르호보암','여로보암','이스라엘 백성']::text[],'솔로몬의 아들 르호보암이 백성의 부담을 줄여달라는 요청을 거절하자 열 지파가 등을 돌려 여로보암을 왕으로 세우고 나라가 북이스라엘과 남유다로 갈라졌다.','지도자의 교만하고 독선적인 태도는 공동체의 분열을 불러올 수 있다.',ARRAY['지도자의 리더십','시기와 갈등']::text[],'나는 지도자로서 사람들의 목소리에 귀 기울이고 있는가?',ARRAY['성인']::text[],'v1','/s/112'),
(113,'여로보암의 금송아지 우상','구약','열왕기상',11,'왕상 12:25-33',ARRAY['여로보암','이스라엘 백성']::text[],'백성이 예루살렘 성전으로 돌아갈 것을 두려워한 여로보암이 벧엘과 단에 금송아지를 만들어 세우고 백성을 우상숭배로 이끌었다.','정치적 두려움 때문에 하나님보다 사람의 계산을 앞세우면 온 공동체를 죄로 이끌 수 있다.',ARRAY['우상숭배 경계','지도자의 리더십']::text[],'나는 두려움 때문에 신앙의 원칙을 타협한 적이 없는가?',ARRAY['성인']::text[],'v1','/s/113'),
(114,'엘리야와 까마귀, 사르밧 과부','구약','열왕기상',11,'왕상 17:1-24',ARRAY['엘리야','사르밧 과부','하나님']::text[],'가뭄을 선포한 엘리야를 하나님이 그릿 시냇가에서 까마귀로 먹이시고, 이후 사르밧 과부에게 보내 마지막 가루와 기름으로 기적을 베푸시며 그 아들을 살리셨다.','하나님은 가장 궁핍한 순간에도 뜻밖의 방법으로 자기 종과 순종하는 이들을 먹이신다.',ARRAY['인도하심과 보호','순종과 믿음']::text[],'궁핍하고 막막한 순간에 하나님이 채워주신 경험을 나눠보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/114'),
(115,'갈멜산 대결','구약','열왕기상',11,'왕상 18:1-46',ARRAY['엘리야','바알 선지자들','아합','이스라엘 백성']::text[],'엘리야가 갈멜산에서 바알 선지자 사백오십 명과 대결하여 하늘에서 불을 내려 제물을 태우시는 여호와의 살아계심을 온 백성 앞에 증명하였다.','참 하나님과 거짓 신 사이에서 머뭇거리는 마음은 분명한 결단으로 나아가야 한다.',ARRAY['우상숭배 경계','예배와 경배']::text[],'나는 신앙과 세상 사이에서 머뭇거리는 부분이 있다면 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/115'),
(116,'엘리야가 호렙산으로 도망함','구약','열왕기상',11,'왕상 19:1-18',ARRAY['엘리야','이세벨','하나님']::text[],'이세벨의 위협에 낙심하여 죽기를 구하던 엘리야에게 하나님이 세미한 음성으로 나타나시고 새 힘을 주시며 새로운 사명을 맡기셨다.','큰 승리 뒤에 찾아오는 극심한 무기력과 두려움 속에서도 하나님은 세미한 음성으로 회복시키신다.',ARRAY['고난과 인내','인도하심과 보호']::text[],'지치고 낙심될 때 나는 하나님의 세미한 음성에 귀 기울이고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/116'),
(117,'나봇의 포도원','구약','열왕기상',11,'왕상 21:1-29',ARRAY['아합','이세벨','나봇']::text[],'아합이 나봇의 포도원을 탐내자 이세벨이 거짓 증인을 세워 나봇을 죽이고 포도원을 빼앗았으며, 엘리야는 이 죄를 엄히 책망하였다.','권력을 이용해 약자의 것을 빼앗는 불의를 하나님은 반드시 심판하신다.',ARRAY['하나님의 심판','지도자의 리더십']::text[],'나는 힘이나 지위를 이용해 부당하게 무언가를 취한 적이 없는가?',ARRAY['성인']::text[],'v1','/s/117'),
(118,'엘리야가 불수레를 타고 승천함','구약','열왕기하',12,'왕하 2:1-14',ARRAY['엘리야','엘리사']::text[],'엘리야가 요단강을 가르고 건넌 후 불수레와 불말에 이끌려 회오리바람으로 하늘로 올라갔고, 엘리사가 그의 겉옷을 얻어 갑절의 영감을 이어받았다.','한 세대의 사명은 죽음으로 끝나지 않고 다음 세대에게 신실하게 이어질 수 있다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 다음 세대에게 물려줄 신앙의 유산을 준비하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/118'),
(119,'엘리사의 기적들','구약','열왕기하',12,'왕하 4:1-6:7',ARRAY['엘리사','수넴 여인','나아만','과부']::text[],'엘리사는 과부의 기름을 채우고 수넴 여인의 죽은 아들을 살리며 물에 빠진 도끼를 떠오르게 하는 등 여러 기적으로 하나님의 능력을 나타냈다.','하나님의 능력은 크고 작은 일상의 필요 속에서도 구체적으로 나타난다.',ARRAY['하나님의 구원','인도하심과 보호']::text[],'내 일상의 필요 속에서 하나님의 능력을 구체적으로 구해본 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/119'),
(120,'나아만 장군의 나병 치유','구약','열왕기하',12,'왕하 5:1-27',ARRAY['나아만','엘리사','어린 이스라엘 소녀','게하시']::text[],'아람 장군 나아만이 어린 소녀의 말을 듣고 엘리사를 찾아가 요단강에 일곱 번 몸을 씻어 나병이 나았으나, 엘리사의 종 게하시는 욕심을 부려 그 병을 대신 얻었다.','겸손히 순종하면 놀라운 치유를 경험하지만, 탐욕은 오히려 저주를 자초한다.',ARRAY['순종과 믿음','겸손과 교만']::text[],'나는 단순한 순종의 길과 내 방식을 고집하는 것 중 무엇을 택하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/120'),
(121,'엘리사와 아람 군대(불말과 불병거)','구약','열왕기하',12,'왕하 6:8-23',ARRAY['엘리사','엘리사의 사환','아람 군대']::text[],'아람 군대에 포위된 엘리사의 사환이 두려워하자 엘리사는 눈을 열어달라 기도했고, 사환은 불말과 불병거가 그들을 둘러싼 것을 보게 되었다.','눈에 보이지 않아도 하나님의 보호하시는 군대는 언제나 우리를 둘러싸고 있다.',ARRAY['인도하심과 보호','순종과 믿음']::text[],'보이지 않는 하나님의 보호하심을 믿음의 눈으로 바라볼 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/121'),
(122,'예후의 쿠데타','구약','열왕기하',12,'왕하 9:1-10:36',ARRAY['예후','이세벨','아합의 집']::text[],'엘리사가 보낸 선지자를 통해 기름부음을 받은 예후가 아합의 집과 이세벨을 심판하며 바알 숭배를 이스라엘에서 대대적으로 제거하였다.','하나님의 심판은 오래 쌓인 죄에 대해 반드시 이루어지며, 개혁은 때로 단호한 결단을 요구한다.',ARRAY['하나님의 심판','우상숭배 경계']::text[],'내 삶이나 공동체에서 단호히 끊어내야 할 오래된 죄는 무엇인가?',ARRAY['성인']::text[],'v1','/s/122'),
(123,'요아스가 성전을 수리함','구약','열왕기하',12,'왕하 12:1-16',ARRAY['요아스','제사장 여호야다','백성']::text[],'어릴 때 제사장 여호야다의 보호를 받고 왕이 된 요아스가 백성의 헌금을 모아 낡은 성전을 보수하였다.','다음 세대를 신실하게 양육하면 그들이 자라 공동체를 새롭게 하는 지도자가 될 수 있다.',ARRAY['지도자의 리더십','예배와 경배']::text[],'나는 다음 세대를 신앙 안에서 신실하게 양육하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/123'),
(124,'히스기야의 개혁과 앗수르의 위협','구약','열왕기하',12,'왕하 18:1-19:37',ARRAY['히스기야','이사야','산헤립']::text[],'히스기야가 우상을 제거하는 개혁을 단행했고, 앗수르 왕 산헤립이 예루살렘을 포위하며 위협할 때 성전에서 간절히 기도하니 하나님의 천사가 하룻밤에 앗수르 군대를 치셨다.','절체절명의 위기 속에서 드리는 간절한 기도에 하나님은 놀라운 방법으로 응답하신다.',ARRAY['기도와 응답','인도하심과 보호']::text[],'내가 지금 직면한 위기 앞에서 히스기야처럼 기도로 나아가고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/124'),
(125,'히스기야의 병과 생명 연장','구약','열왕기하',12,'왕하 20:1-11',ARRAY['히스기야','이사야','하나님']::text[],'죽을병에 걸린 히스기야가 벽을 향해 울며 기도하자 하나님이 그의 기도를 들으시고 생명을 십오 년 더 연장해 주시며 해 그림자를 뒤로 물러가게 하는 표징을 주셨다.','간절한 기도는 사람의 정해진 것처럼 보이는 한계마저도 움직일 수 있다.',ARRAY['기도와 응답','고난과 인내']::text[],'생명이나 건강의 위기 앞에서 나는 얼마나 간절히 기도로 나아가는가?',ARRAY['성인']::text[],'v1','/s/125'),
(126,'요시야의 개혁과 율법책 발견','구약','열왕기하',12,'왕하 22:1-23:30',ARRAY['요시야','대제사장 힐기야','백성']::text[],'성전 수리 중 잃어버렸던 율법책이 발견되자 어린 왕 요시야는 옷을 찢으며 회개하고 온 나라적인 신앙 개혁을 단행하여 우상을 제거하고 유월절을 성대히 지켰다.','말씀을 되찾고 그 말씀 앞에 진심으로 회개할 때 개인과 공동체 모두 새로워질 수 있다.',ARRAY['회개와 용서','율법과 계명']::text[],'오랫동안 잊고 지낸 말씀을 다시 대할 때 나는 어떻게 반응하는가?',ARRAY['청소년','성인']::text[],'v1','/s/126'),
(127,'예루살렘의 함락과 포로로 끌려감','구약','열왕기하',12,'왕하 25:1-21',ARRAY['시드기야','느부갓네살','백성']::text[],'바벨론 왕 느부갓네살이 예루살렘을 함락시켜 성전과 성벽을 불태우고 많은 백성을 포로로 끌고 가니, 오랜 불순종의 역사가 마침내 심판으로 귀결되었다.','오래 참으시는 하나님의 심판도 결국 회개하지 않는 죄에 대해 반드시 이루어진다.',ARRAY['하나님의 심판']::text[],'돌이킬 기회가 있을 때 미리 회개하는 것이 왜 중요한지 생각해보자.',ARRAY['성인']::text[],'v1','/s/127'),
(128,'다윗의 인구조사와 오르난의 타작마당','구약','역대상',13,'대상 21:1-30',ARRAY['다윗','오르난','하나님','선지자 갓']::text[],'다윗이 교만한 마음으로 인구조사를 하여 전염병의 재앙이 임하자 회개하며 오르난의 타작마당에 제단을 쌓았고, 그 자리는 훗날 성전 터가 되었다.','지도자의 교만한 결정은 공동체 전체에 아픔을 가져올 수 있으나, 진실한 회개의 자리는 은혜의 자리로 바뀔 수 있다.',ARRAY['죄와 타락','회개와 용서']::text[],'나의 교만한 결정이 다른 이들에게 영향을 미친 적은 없는가?',ARRAY['성인']::text[],'v1','/s/128'),
(129,'다윗이 성전 건축을 솔로몬에게 위임함','구약','역대상',13,'대상 28:1-29:9',ARRAY['다윗','솔로몬','이스라엘 지도자들']::text[],'다윗은 자신이 성전을 짓지 못함을 알고 아들 솔로몬에게 설계도와 재료를 물려주며 백성과 함께 기쁨으로 자원하여 예물을 드렸다.','자신이 완성하지 못할 일이라도 다음 세대를 위해 신실하게 준비하는 것이 참된 헌신이다.',ARRAY['충성과 신실함','사랑과 섬김']::text[],'나는 내 세대에 다 이루지 못하더라도 다음 세대를 위해 무엇을 준비하고 있는가?',ARRAY['성인']::text[],'v1','/s/129'),
(130,'여호사밧의 기도와 찬양의 승리','구약','역대하',14,'대하 20:1-30',ARRAY['여호사밧','이스라엘 백성','찬양대']::text[],'연합군의 침공 앞에 두려워한 여호사밧이 온 백성과 금식하며 기도하자 하나님이 승리를 약속하셨고, 찬양대를 군대 앞에 세워 노래하자 적군이 스스로 무너졌다.','위기 앞에서 두려움 대신 기도와 찬양으로 나아가면 하나님이 싸우시는 승리를 경험한다.',ARRAY['기도와 응답','예배와 경배']::text[],'두려운 상황 속에서 나는 찬양과 기도로 먼저 나아가는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/130'),
(131,'므낫세의 회개','구약','역대하',14,'대하 33:1-20',ARRAY['므낫세','하나님']::text[],'우상숭배와 악행으로 유다를 가장 크게 더럽혔던 므낫세 왕이 앗수르에 포로로 끌려가 사슬에 매인 고통 속에서 하나님께 겸손히 회개하니 하나님이 그의 기도를 들으시고 회복시키셨다.','아무리 큰 죄를 지은 사람이라도 진심으로 겸손히 회개하면 하나님의 용서와 회복을 경험할 수 있다.',ARRAY['회개와 용서','하나님의 구원']::text[],'내가 돌이킬 수 없다고 여겼던 죄나 사람도 하나님 앞에서는 회복 가능함을 믿는가?',ARRAY['성인']::text[],'v1','/s/131'),
(132,'고레스 왕의 조서와 귀환 허락','구약','에스라',15,'스 1:1-11',ARRAY['고레스','유다 포로들','하나님']::text[],'바사 왕 고레스가 하나님의 감동으로 조서를 내려 포로 된 유다 백성이 예루살렘으로 돌아가 성전을 재건하도록 허락하고 성전 기구들을 돌려주었다.','하나님은 이방 왕의 마음까지도 움직이셔서 자기 백성을 향한 약속을 이루신다.',ARRAY['하나님의 섭리','인도하심과 보호']::text[],'하나님이 뜻밖의 사람이나 상황을 통해 나를 도우신 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/132'),
(133,'성전 기초를 놓음','구약','에스라',15,'스 3:1-13',ARRAY['스룹바벨','예수아','백성']::text[],'돌아온 백성이 제단을 재건하고 성전 기초를 놓을 때 젊은이들은 기쁨으로 노래하고 성전을 기억하는 노인들은 감격의 눈물을 흘렸다.','같은 은혜의 자리에서도 세대에 따라 기쁨과 눈물이 함께 어우러질 수 있으며 둘 다 소중한 신앙의 표현이다.',ARRAY['예배와 경배','가정과 관계']::text[],'우리 신앙공동체는 세대 간의 서로 다른 감정과 표현을 얼마나 존중하는가?',ARRAY['성인']::text[],'v1','/s/133'),
(134,'에스라의 귀환과 율법 교육','구약','에스라',15,'스 7:1-10',ARRAY['에스라','백성']::text[],'학사 겸 제사장 에스라가 여호와의 율법을 연구하고 준행하며 가르치기로 결심하고 예루살렘으로 돌아와 백성에게 말씀을 가르쳤다.','말씀을 배우는 것과 실천하는 것, 가르치는 것은 신앙의 성숙에서 함께 가야 할 세 걸음이다.',ARRAY['율법과 계명','순종과 믿음']::text[],'나는 말씀을 배우고 실천하고 나누는 이 세 가지 균형을 이루고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/134'),
(135,'에스라의 회개 기도와 개혁','구약','에스라',15,'스 9:1-10:44',ARRAY['에스라','백성']::text[],'이방 민족과의 잘못된 결혼으로 신앙 공동체가 흔들리는 것을 본 에스라가 옷을 찢고 통회하며 기도하니 백성도 함께 죄를 자백하고 돌이켰다.','지도자의 진심 어린 회개는 공동체 전체의 회복으로 이어지는 힘이 있다.',ARRAY['회개와 용서','지도자의 리더십']::text[],'나는 공동체를 위해 진심으로 슬퍼하며 중보한 적이 있는가?',ARRAY['성인']::text[],'v1','/s/135'),
(136,'느헤미야가 예루살렘 소식을 듣고 기도함','구약','느헤미야',16,'느 1:1-11',ARRAY['느헤미야','하나니']::text[],'바사 왕궁의 술 관원 느헤미야가 예루살렘 성벽이 무너지고 백성이 고통받는다는 소식을 듣고 여러 날 슬퍼하며 금식하고 기도하였다.','멀리 떨어진 곳에서도 하나님 백성의 아픔에 진심으로 반응하는 마음이 사명의 출발점이 된다.',ARRAY['기도와 응답','사랑과 섬김']::text[],'나는 내가 속하지 않은 공동체의 아픔에도 진심으로 마음 아파하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/136'),
(137,'느헤미야가 왕의 허락을 받고 예루살렘으로 감','구약','느헤미야',16,'느 2:1-20',ARRAY['느헤미야','아닥사스다 왕']::text[],'슬픈 얼굴빛을 본 왕이 이유를 묻자 느헤미야는 순간 하늘의 하나님께 묵상기도하고 담대히 요청하여 예루살렘으로 갈 허락과 필요한 물자를 얻었다.','중요한 순간 짧게라도 하나님께 기도하며 준비된 마음으로 담대히 구하는 태도가 필요하다.',ARRAY['기도와 응답','용기와 결단']::text[],'중요한 결정의 순간, 나는 하나님께 먼저 묵상기도하는 습관이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/137'),
(138,'대적들의 방해와 성벽 재건','구약','느헤미야',16,'느 4:1-23',ARRAY['느헤미야','산발랏','도비야','백성']::text[],'산발랏과 도비야가 조롱과 위협으로 성벽 재건을 방해하자 느헤미야는 백성 절반은 일하고 절반은 무기를 들고 경계하게 하며 기도와 경계를 함께 하였다.','하나님의 일을 이룰 때 기도와 함께 지혜로운 준비와 경계도 병행해야 한다.',ARRAY['지도자의 리더십','고난과 인내']::text[],'나는 어려움 속에서 기도와 실제적 대비를 함께 하고 있는가?',ARRAY['성인']::text[],'v1','/s/138'),
(139,'성벽 완공','구약','느헤미야',16,'느 6:1-19',ARRAY['느헤미야','산발랏','백성']::text[],'여러 계략과 위협에도 흔들리지 않은 느헤미야의 인도 아래 백성이 오십이 일 만에 성벽 재건을 완성하니 대적들도 이 일이 하나님께로 말미암은 것을 깨달았다.','집중력 있는 헌신과 하나님을 향한 신뢰는 불가능해 보이는 일도 짧은 시간에 이루게 한다.',ARRAY['지도자의 리더십','순종과 믿음']::text[],'나는 방해와 위협 속에서도 맡겨진 사명에 집중하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/139'),
(140,'에스라가 율법을 낭독함','구약','느헤미야',16,'느 8:1-18',ARRAY['에스라','느헤미야','백성']::text[],'수문 앞 광장에 모인 백성에게 에스라가 새벽부터 정오까지 율법을 낭독하자 백성이 말씀을 깨닫고 울었으나, 지도자들은 오늘은 기뻐하는 날이라며 그들을 위로하고 초막절을 함께 지켰다.','말씀 앞에서의 애통함은 곧 하나님이 주시는 기쁨으로 전환되어야 한다.',ARRAY['예배와 경배','회개와 용서']::text[],'말씀을 들을 때 내 마음에 애통함과 회복의 기쁨이 함께 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/140'),
(141,'와스디 왕후가 폐위됨','구약','에스더',17,'에 1:1-22',ARRAY['아하수에로 왕','와스디']::text[],'잔치에서 왕의 명령을 거절한 와스디 왕후가 왕후의 자리에서 폐위되어 새로운 왕후를 세우는 절차가 시작되었다.','높은 자리도 하나님의 섭리 안에서 뜻밖의 방식으로 바뀔 수 있으며, 이는 더 큰 구원 계획의 시작이 되기도 한다.',ARRAY['하나님의 섭리']::text[],'예상치 못한 변화가 하나님의 더 큰 계획의 일부였던 경험이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/141'),
(142,'에스더가 왕후로 간택됨','구약','에스더',17,'에 2:1-18',ARRAY['에스더','모르드개','아하수에로 왕']::text[],'고아였던 유대인 처녀 에스더가 사촌 모르드개의 양육을 받고 여러 후보 중에 뽑혀 페르시아의 왕후가 되었다.','하나님은 평범해 보이는 사람을 통해서도 놀라운 섭리의 자리를 예비하신다.',ARRAY['하나님의 섭리','인도하심과 보호']::text[],'내가 지금 있는 자리도 하나님이 예비하신 뜻이 있다고 믿는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/142'),
(143,'하만의 음모','구약','에스더',17,'에 3:1-15',ARRAY['하만','모르드개','아하수에로 왕']::text[],'모르드개가 절하지 않는 것에 분노한 하만이 왕의 허락을 얻어 제국 내 모든 유대인을 진멸하려는 조서를 내렸다.','한 사람의 교만한 분노가 한 민족 전체를 위협하는 거대한 음모로 커질 수 있다.',ARRAY['시기와 갈등','하나님의 심판']::text[],'작은 분노나 시기가 얼마나 큰 결과로 이어질 수 있는지 생각해보자.',ARRAY['청소년','성인']::text[],'v1','/s/143'),
(144,'''이때를 위함이 아닌지''','구약','에스더',17,'에 4:1-17',ARRAY['모르드개','에스더']::text[],'모르드개가 에스더에게 민족을 구할 것을 요청하며 ''네가 왕후의 위를 얻은 것이 이때를 위함이 아닌지 누가 알겠느냐'' 도전하자 에스더는 ''죽으면 죽으리이다'' 결단하고 금식을 요청했다.','우리가 지금 있는 자리와 지위는 결정적인 순간을 위한 하나님의 준비일 수 있다.',ARRAY['용기와 결단','하나님의 섭리']::text[],'지금 내가 있는 자리가 누군가를 위한 ''이때''일 수 있다고 생각해본 적이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/144'),
(145,'에스더의 용기와 하만의 몰락','구약','에스더',17,'에 5:1-8:2',ARRAY['에스더','하만','아하수에로 왕','모르드개']::text[],'목숨을 걸고 왕 앞에 나아간 에스더가 지혜로운 잔치를 통해 하만의 음모를 밝히니, 모르드개를 죽이려던 나무에 하만 자신이 달려 처형되었다.','자기를 위해 판 함정에 스스로 빠지는 것처럼, 악한 계획은 결국 하나님의 정의 앞에 무너진다.',ARRAY['하나님의 심판','용기와 결단']::text[],'위험을 무릅쓰고 옳은 일을 위해 나서야 했던 순간이 있었는가?',ARRAY['청소년','성인']::text[],'v1','/s/145'),
(146,'유대인의 구원과 부림절 제정','구약','에스더',17,'에 9:1-10:3',ARRAY['에스더','모르드개','유대인들']::text[],'진멸의 위기에서 구원받은 유대인들이 큰 기쁨으로 승리를 기념하며 부림절을 대대로 지키기로 제정하였다.','위기에서 구원받은 은혜는 잊지 않고 대대로 기념하며 감사해야 할 이유가 된다.',ARRAY['하나님의 구원','예배와 경배']::text[],'내 삶에서 하나님이 베푸신 구원의 은혜를 어떻게 기념하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/146'),
(147,'욥의 고난과 사탄의 시험','구약','욥기',18,'욥 1:1-2:13',ARRAY['욥','사탄','하나님']::text[],'흠 없이 신실했던 욥이 사탄의 시험으로 재산과 자녀, 건강까지 모두 잃는 극심한 고난을 당했으나 하나님을 향한 신뢰를 저버리지 않았다.','극심한 고난 속에서도 하나님을 원망하지 않는 믿음은 사람의 노력이 아니라 하나님의 은혜로 가능하다.',ARRAY['고난과 인내','순종과 믿음']::text[],'이유를 알 수 없는 고난 앞에서 나는 어떤 태도를 보이는가?',ARRAY['청소년','성인']::text[],'v1','/s/147'),
(148,'세 친구의 위로와 논쟁','구약','욥기',18,'욥 4:1-31:40',ARRAY['욥','엘리바스','빌닷','소발']::text[],'욥을 위로하러 온 세 친구가 고난은 죄의 결과라는 틀에 갇혀 욥을 정죄하며 논쟁했으나, 욥은 자신의 무고함을 주장하며 하나님께 답을 구했다.','고난받는 이를 함부로 정죄하기보다 그 곁에서 진심으로 함께 슬퍼하는 것이 참된 위로이다.',ARRAY['고난과 인내','지혜와 분별']::text[],'나는 고통받는 사람을 판단하기보다 곁에서 함께 울어준 적이 있는가?',ARRAY['성인']::text[],'v1','/s/148'),
(149,'하나님이 폭풍우 속에서 응답하심','구약','욥기',18,'욥 38:1-42:6',ARRAY['욥','하나님']::text[],'하나님이 폭풍우 가운데 나타나 창조의 신비와 광대하심을 물으시자 욥은 자신의 무지를 깨닫고 겸손히 회개하며 하나님을 눈으로 뵈었다고 고백했다.','모든 답을 알지 못해도 하나님의 광대하심 앞에 겸손히 신뢰하는 것이 믿음의 자리이다.',ARRAY['겸손과 교만','순종과 믿음']::text[],'이해되지 않는 질문 앞에서 나는 하나님의 크심을 신뢰할 수 있는가?',ARRAY['성인']::text[],'v1','/s/149'),
(150,'욥의 회복','구약','욥기',18,'욥 42:7-17',ARRAY['욥','하나님','욥의 친구들']::text[],'회개한 욥을 위해 기도하자 하나님이 그의 친구들을 책망하시고 욥에게 이전보다 갑절의 복을 주시며 회복시키셨다.','진실한 회개와 중보 이후에 하나님은 상상 이상의 회복을 허락하신다.',ARRAY['회개와 용서','하나님의 구원']::text[],'고난 이후의 회복을 경험했거나 소망하는 부분이 있다면 나눠보자.',ARRAY['청소년','성인']::text[],'v1','/s/150'),
(151,'시편 23편: 여호와는 나의 목자시니','구약','시편',19,'시 23:1-6',ARRAY['다윗','하나님']::text[],'다윗은 여호와를 자신의 목자로 고백하며 푸른 풀밭과 쉴 만한 물가로 인도하시고 사망의 음침한 골짜기에서도 함께하시는 하나님을 노래했다.','선한 목자이신 하나님은 인생의 모든 순간, 특히 가장 어두운 골짜기에서도 함께하신다.',ARRAY['인도하심과 보호','예배와 경배']::text[],'내 인생의 ''음침한 골짜기''에서 하나님의 동행을 어떻게 경험했는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/151'),
(152,'시편 51편: 다윗의 참회','구약','시편',19,'시 51:1-19',ARRAY['다윗','하나님']::text[],'밧세바 사건 이후 다윗은 ''하나님이여 내 속에 정한 마음을 창조하시고''라며 자신의 죄를 숨기지 않고 철저히 회개하는 기도를 드렸다.','진정한 회개는 변명 없이 죄를 인정하고 하나님께 새로운 마음을 구하는 것이다.',ARRAY['회개와 용서','죄와 타락']::text[],'나는 죄를 지적받을 때 다윗처럼 정직하게 회개하는가?',ARRAY['청소년','성인']::text[],'v1','/s/152'),
(153,'시편 121편: 도움이 어디서 올까','구약','시편',19,'시 121:1-8',ARRAY['시인','하나님']::text[],'시인은 산을 향해 눈을 들며 자신의 도움이 천지를 지으신 여호와께로부터 온다고 고백하며 그분이 졸지도 주무시지도 않고 지키신다 노래했다.','인생의 어려운 순간, 우리의 시선을 산이 아니라 산을 지으신 하나님께로 향해야 한다.',ARRAY['기도와 응답','인도하심과 보호']::text[],'나는 어려움 속에서 시선을 어디로 향하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/153'),
(154,'시편 139편: 나를 아시는 하나님','구약','시편',19,'시 139:1-24',ARRAY['다윗','하나님']::text[],'다윗은 하나님이 자신의 앉고 일어섬을 아시며 모태에서부터 자신을 지으셨고 어디를 가든 그 앞을 피할 수 없다고 고백하며 자신을 살펴달라 기도했다.','하나님은 우리의 모든 것을 아시고 지으신 분이시니, 그분 앞에 숨김없이 나아갈 수 있다.',ARRAY['창조와 섭리','기도와 응답']::text[],'하나님이 나를 속속들이 아신다는 사실이 내게 위로가 되는가, 부담이 되는가?',ARRAY['청소년','성인']::text[],'v1','/s/154'),
(155,'시편 150편: 호흡이 있는 자마다 찬양하라','구약','시편',19,'시 150:1-6',ARRAY['시인']::text[],'시인은 여러 악기와 춤으로 성소에서 하나님의 권능을 찬양하라 권하며 호흡이 있는 모든 자에게 여호와를 찬양하라는 말로 시편 전체를 마무리한다.','찬양은 특정한 방식에 갇히지 않고 생명을 가진 모든 존재가 마땅히 드려야 할 반응이다.',ARRAY['예배와 경배']::text[],'나는 어떤 방식으로 하나님께 찬양을 표현하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/155'),
(156,'지혜의 시작은 여호와를 경외함','구약','잠언',20,'잠 1:1-9:18',ARRAY['솔로몬','지혜']::text[],'솔로몬은 여호와를 경외하는 것이 지식의 근본이라 선포하며 지혜를 얻으라는 아버지의 권면과 함께, 지혜를 사람처럼 의인화하여 그 부르심에 귀 기울이라 권한다.','참된 지혜는 지식의 축적이 아니라 하나님을 경외하는 마음에서 시작된다.',ARRAY['지혜와 분별','순종과 믿음']::text[],'나는 지식과 하나님을 경외하는 지혜 중 무엇을 더 추구하는가?',ARRAY['청소년','성인']::text[],'v1','/s/156'),
(157,'현숙한 여인','구약','잠언',20,'잠 31:10-31',ARRAY['현숙한 여인']::text[],'잠언은 부지런하고 지혜로우며 가정과 이웃을 성실히 돌보는 현숙한 여인을 그 값이 진주보다 귀하다고 칭송하며 마무리된다.','성실함과 지혜, 사랑으로 자신의 자리를 채우는 삶은 겉모습을 넘어서는 참된 가치를 지닌다.',ARRAY['가정과 관계','지혜와 분별']::text[],'나는 나에게 맡겨진 자리를 얼마나 성실하고 지혜롭게 채우고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/157'),
(158,'해 아래에는 새것이 없다','구약','전도서',21,'전 1:1-2:26',ARRAY['전도자(솔로몬)']::text[],'전도자는 모든 수고와 지혜, 쾌락과 부귀를 다 누려보았으나 해 아래의 모든 것이 헛되다 고백하며 인생의 참된 의미를 찾고자 했다.','세상의 성취와 즐거움만으로는 채워지지 않는 인생의 공허함을 정직하게 마주해야 한다.',ARRAY['지혜와 분별','고난과 인내']::text[],'나는 무엇으로 인생의 헛헛함을 채우려 하고 있는가?',ARRAY['성인']::text[],'v1','/s/158'),
(159,'모든 것에는 때가 있다','구약','전도서',21,'전 3:1-15',ARRAY['전도자(솔로몬)']::text[],'전도자는 날 때와 죽을 때, 심을 때와 거둘 때 등 인생의 모든 일에 하나님이 정하신 때가 있다고 노래한다.','인생의 모든 계절과 타이밍은 하나님의 손 안에 있으며, 그 질서를 신뢰하는 것이 지혜이다.',ARRAY['창조와 섭리','지혜와 분별']::text[],'지금 내 인생은 어떤 ''때''를 지나고 있다고 생각하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/159'),
(160,'네 창조주를 기억하라','구약','전도서',21,'전 12:1-14',ARRAY['전도자(솔로몬)']::text[],'전도서는 젊은 날에 창조주를 기억하라 권면하며 모든 것의 결론은 하나님을 경외하고 그 명령을 지키는 것이라 마무리한다.','인생의 모든 경험 끝에 다다르는 결론은 결국 하나님을 경외하며 사는 삶이다.',ARRAY['순종과 믿음','지혜와 분별']::text[],'나는 인생의 이른 시기부터 하나님을 기억하며 살고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/160'),
(161,'사랑의 노래','구약','아가',22,'아 1:1-8:14',ARRAY['솔로몬','술람미 여인']::text[],'솔로몬과 술람미 여인의 사랑을 시적으로 노래한 아가서는 서로를 향한 깊은 그리움과 기쁨, 신실한 사랑의 아름다움을 생생하게 표현한다.','진실하고 신실한 사랑은 하나님이 주신 아름다운 선물이며 존중받아야 할 가치이다.',ARRAY['가정과 관계']::text[],'나는 하나님이 주신 사랑과 관계를 얼마나 소중히 여기고 가꾸는가?',ARRAY['성인']::text[],'v1','/s/161'),
(162,'이사야의 소명(스랍 환상)','구약','이사야',23,'사 6:1-13',ARRAY['이사야','스랍','하나님']::text[],'웃시야 왕이 죽던 해 이사야가 높이 들린 보좌에 앉으신 하나님과 스랍들의 ''거룩하다'' 외침을 보고 자신의 부정함을 고백하니, 숯불로 입술이 정결케 되고 선지자로 보냄받았다.','하나님의 거룩하심 앞에 자신의 죄를 정직히 고백할 때 참된 정결함과 사명이 주어진다.',ARRAY['예배와 경배','순종과 믿음']::text[],'하나님의 거룩하심 앞에서 나는 나의 부족함을 정직히 인정하는가?',ARRAY['청소년','성인']::text[],'v1','/s/162'),
(163,'임마누엘 예언','구약','이사야',23,'사 7:1-16',ARRAY['이사야','아하스 왕']::text[],'적의 침공으로 두려워하는 아하스 왕에게 이사야는 처녀가 잉태하여 아들을 낳을 것이며 그 이름을 임마누엘이라 하리라는 표징을 전했다.','하나님이 우리와 함께하신다는 약속은 가장 두려운 위기 속에서도 소망의 근거가 된다.',ARRAY['하나님의 언약','예수 그리스도의 정체성']::text[],'임마누엘, ''하나님이 우리와 함께하심''이 내게 어떤 의미인지 나눠보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/163'),
(164,'평강의 왕 예언','구약','이사야',23,'사 9:1-7',ARRAY['이사야']::text[],'이사야는 어둠 가운데 있던 백성에게 한 아기가 나실 것이며 그 이름은 기묘자, 모사, 전능하신 하나님, 영존하시는 아버지, 평강의 왕이라 예언했다.','메시아의 오심은 어둠 속에 있는 백성에게 참된 빛과 평강을 가져오는 소망이다.',ARRAY['예수 그리스도의 정체성','종말과 소망']::text[],'내 삶의 어두운 영역에 이 평강의 왕이 어떻게 빛을 비추시는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/164'),
(165,'고난받는 종의 노래','구약','이사야',23,'사 53:1-12',ARRAY['고난받는 종','이사야']::text[],'이사야는 그가 우리의 죄악을 위해 찔림과 상함을 당하셨고 그가 받은 채찍에 우리가 나음을 입었다며 고난받는 종의 대속적 희생을 예언했다.','메시아의 고난은 자신의 죄가 아니라 우리의 죄를 대신 짊어지신 사랑의 희생이었다.',ARRAY['하나님의 구원','예수 그리스도의 정체성']::text[],'예수님의 십자가 고난이 나를 위한 것이었음을 어떻게 고백할 수 있을까?',ARRAY['청소년','성인']::text[],'v1','/s/165'),
(166,'위로의 말씀과 독수리같이 날개치며 올라감','구약','이사야',23,'사 40:1-31',ARRAY['이사야','이스라엘 백성']::text[],'이사야는 지친 백성에게 하나님이 위로하시며 여호와를 앙망하는 자는 새 힘을 얻어 독수리처럼 날개치며 올라갈 것이라 선포했다.','지치고 피곤한 인생길에도 여호와를 앙망하는 자에게는 새 힘이 주어진다.',ARRAY['고난과 인내','인도하심과 보호']::text[],'지금 지쳐 있는 부분에서 나는 여호와를 앙망하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/166'),
(167,'예레미야의 소명','구약','예레미야',24,'렘 1:1-19',ARRAY['예레미야','하나님']::text[],'자신이 어리다며 주저하는 예레미야에게 하나님은 모태에 짓기 전부터 그를 알고 예정하셨다며 두려워하지 말라 명하시고 그 입에 말씀을 두셨다.','하나님의 부르심은 사람의 자격이나 나이가 아니라 그분의 예정과 함께하심에 근거한다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나의 부족함을 이유로 하나님의 부르심 앞에서 주저한 적이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/167'),
(168,'토기장이의 집','구약','예레미야',24,'렘 18:1-11',ARRAY['예레미야','토기장이','하나님']::text[],'하나님이 예레미야를 토기장이의 집으로 보내 흠 있는 그릇을 다시 빚는 모습을 보이시며, 이스라엘도 진흙처럼 자신의 손에 있어 돌이키면 다시 빚어질 수 있다 말씀하셨다.','실패하고 깨어진 인생도 토기장이이신 하나님의 손 안에서 다시 빚어질 수 있다.',ARRAY['회개와 용서','창조와 섭리']::text[],'내 인생에서 다시 빚어지길 원하는 깨어진 부분은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/168'),
(169,'여호야김이 두루마리를 불태움','구약','예레미야',24,'렘 36:1-32',ARRAY['예레미야','바룩','여호야김 왕']::text[],'예레미야가 바룩을 통해 기록한 하나님의 말씀 두루마리를 여호야김 왕이 칼로 베어 화로에 던져 태웠으나, 하나님은 다시 그 말씀을 기록하게 하셨다.','권력으로 하나님의 말씀을 없애려 해도 그 말씀은 결코 소멸되지 않는다.',ARRAY['순종과 믿음','하나님의 심판']::text[],'말씀을 거부하고 싶은 순간에도 그 말씀의 능력을 나는 신뢰하는가?',ARRAY['성인']::text[],'v1','/s/169'),
(170,'예레미야가 구덩이에 던져짐','구약','예레미야',24,'렘 38:1-13',ARRAY['예레미야','에벳멜렉','시드기야 왕']::text[],'진실을 전했다는 이유로 관리들에 의해 진흙 구덩이에 던져진 예레미야가 에벳멜렉의 도움으로 구조되었다.','진실을 말하는 것이 큰 대가를 요구할 때도 하나님은 뜻밖의 사람을 통해 구원하신다.',ARRAY['고난과 인내','용기와 결단']::text[],'옳은 것을 말하다 어려움을 겪을 때 나는 끝까지 진실을 지킬 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/170'),
(171,'새 언약 예언','구약','예레미야',24,'렘 31:31-34',ARRAY['예레미야','하나님']::text[],'하나님은 장차 돌판이 아닌 마음에 율법을 기록하는 새 언약을 맺으실 것이며 백성의 죄를 다시 기억하지 않으시겠다 약속하셨다.','새 언약의 핵심은 외적 규례가 아니라 마음에 새겨지는 하나님과의 인격적 관계이다.',ARRAY['하나님의 언약','회개와 용서']::text[],'내 신앙은 형식적인 규례인가, 마음에 새겨진 인격적 관계인가?',ARRAY['청소년','성인']::text[],'v1','/s/171'),
(172,'예루살렘의 슬픔을 애곡함','구약','예레미야애가',25,'애 1:1-22',ARRAY['예레미야','예루살렘']::text[],'한때 사람들로 가득했던 예루살렘이 황폐해진 모습을 예레미야가 슬픔으로 애곡하며 백성의 죄로 인한 참담한 결과를 노래한다.','죄의 결과로 인한 고통을 회피하지 않고 정직하게 슬퍼하는 것도 신앙의 한 표현이다.',ARRAY['하나님의 심판','고난과 인내']::text[],'나는 죄의 결과로 인한 아픔 앞에서 정직하게 슬퍼하고 있는가?',ARRAY['성인']::text[],'v1','/s/172'),
(173,'여호와의 인자와 긍휼이 무궁함','구약','예레미야애가',25,'애 3:19-33',ARRAY['예레미야']::text[],'깊은 고통 속에서도 예레미야는 여호와의 인자와 긍휼이 무궁하여 아침마다 새로우며 그 성실이 크시다고 고백하며 소망을 노래했다.','가장 깊은 절망 속에서도 하나님의 신실하심은 매일 아침 새롭게 임한다.',ARRAY['고난과 인내','인도하심과 보호']::text[],'오늘 아침 나는 하나님의 새로운 긍휼을 어떻게 경험했는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/173'),
(174,'에스겔의 소명(네 생물과 바퀴 환상)','구약','에스겔',26,'겔 1:1-3:15',ARRAY['에스겔','하나님']::text[],'포로 중이던 에스겔이 그발강 가에서 네 생물과 바퀴, 하나님의 영광의 형상을 보는 웅장한 환상을 통해 선지자로 부름받았다.','포로와 절망의 자리에서도 하나님은 자신의 영광을 보이시며 사명을 주신다.',ARRAY['하나님의 섭리','순종과 믿음']::text[],'가장 낮고 절망적인 자리에서도 하나님이 나를 부르실 수 있음을 믿는가?',ARRAY['성인']::text[],'v1','/s/174'),
(175,'파수꾼의 사명','구약','에스겔',26,'겔 3:16-21',ARRAY['에스겔','하나님']::text[],'하나님은 에스겔을 이스라엘의 파수꾼으로 세우시며 백성에게 경고하지 않아 그들이 죄 중에 죽으면 그 피 값을 파수꾼에게 물으시겠다 하셨다.','진리를 알고도 침묵하는 것은 자신뿐 아니라 다른 이의 생명에도 책임이 따르는 일이다.',ARRAY['충성과 신실함','전도와 선교']::text[],'나는 알고 있는 진리를 필요한 이에게 전하는 데 신실한가?',ARRAY['성인']::text[],'v1','/s/175'),
(176,'마른 뼈 골짜기 환상','구약','에스겔',26,'겔 37:1-14',ARRAY['에스겔','마른 뼈들','하나님']::text[],'하나님이 에스겔을 마른 뼈로 가득한 골짜기로 데려가 대언하게 하시니 뼈들이 서로 연결되고 힘줄과 살이 오르며 생기가 들어가 큰 군대가 되었다.','가장 소망 없어 보이는 죽은 것 같은 상황도 하나님의 영이 임하면 새 생명으로 살아날 수 있다.',ARRAY['하나님의 구원','종말과 소망']::text[],'내 삶이나 공동체에서 ''마른 뼈''처럼 소망 없어 보이는 부분은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/176'),
(177,'다니엘과 세 친구의 결심','구약','다니엘',27,'단 1:1-21',ARRAY['다니엘','사드락','메삭','아벳느고']::text[],'바벨론 포로로 끌려간 다니엘과 세 친구가 왕의 진미로 자신을 더럽히지 않기로 결심하고 채소만 먹었으나, 하나님이 그들에게 지혜와 총명을 더하여 다른 이들보다 뛰어나게 하셨다.','세상의 압력 속에서도 신앙의 원칙을 지키기로 결단하면 하나님이 그 신실함에 복을 주신다.',ARRAY['순종과 믿음','용기와 결단']::text[],'세상의 기준과 다른 신앙의 결단을 내려야 했던 순간이 있었는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/177'),
(178,'느부갓네살의 꿈과 신상 해석','구약','다니엘',27,'단 2:1-49',ARRAY['다니엘','느부갓네살 왕']::text[],'느부갓네살 왕의 꿈을 아무도 해석하지 못할 때 다니엘이 기도로 응답을 받아 금, 은, 놋, 철로 이루어진 신상이 장차 있을 나라들을 뜻하며 하나님 나라만이 영원하다 해석했다.','세상의 모든 왕국은 흥망성쇠를 겪지만 하나님의 나라만이 영원히 서 있는 나라이다.',ARRAY['하나님 나라','지혜와 분별']::text[],'나는 영원한 하나님 나라와 이 세상의 것들 중 무엇에 더 소망을 두는가?',ARRAY['청소년','성인']::text[],'v1','/s/178'),
(179,'풀무불 속의 세 친구','구약','다니엘',27,'단 3:1-30',ARRAY['사드락','메삭','아벳느고','느부갓네살 왕']::text[],'금 신상에 절하기를 거부한 세 친구가 풀무불에 던져졌으나 불 가운데서도 상하지 않았고, 넷째 사람이 함께 있는 것을 본 왕은 하나님의 위대하심을 인정했다.','목숨을 건 순종의 자리에도 하나님은 함께하시며 불꽃 가운데서도 지키신다.',ARRAY['순종과 믿음','인도하심과 보호']::text[],'타협하라는 압박 속에서도 나는 신앙의 원칙을 지킬 용기가 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/179'),
(180,'느부갓네살의 교만과 광인이 됨','구약','다니엘',27,'단 4:1-37',ARRAY['느부갓네살 왕','다니엘']::text[],'자신의 권세를 자랑하던 느부갓네살이 하나님의 경고대로 이성을 잃고 짐승처럼 지내다가 하늘을 우러러 하나님을 찬양하니 다시 나라를 회복하였다.','가장 높은 권세를 가진 자라도 교만하면 낮아질 수 있고, 하나님을 인정하면 회복될 수 있다.',ARRAY['겸손과 교만','회개와 용서']::text[],'나는 내 능력과 성취를 누구의 것으로 돌리고 있는가?',ARRAY['성인']::text[],'v1','/s/180'),
(181,'벨사살 왕과 벽에 쓴 글자','구약','다니엘',27,'단 5:1-31',ARRAY['벨사살 왕','다니엘']::text[],'성전 기구로 잔치를 벌이던 벨사살 왕 앞에 벽에 손가락이 나타나 글자를 썼고, 다니엘이 그것을 ''메네 메네 데겔 우바르신''으로 해석하며 그의 나라가 그날 밤 끝날 것을 선포했다.','거룩한 것을 함부로 여기는 교만은 하나님의 즉각적인 심판을 부를 수 있다.',ARRAY['하나님의 심판','겸손과 교만']::text[],'나는 거룩한 것들을 얼마나 신중하고 경외함으로 대하고 있는가?',ARRAY['성인']::text[],'v1','/s/181'),
(182,'사자굴 속의 다니엘','구약','다니엘',27,'단 6:1-28',ARRAY['다니엘','다리오 왕','대신들']::text[],'다니엘을 시기한 대신들의 계략으로 사자굴에 던져진 다니엘이 하나님의 보호하심으로 상하지 않고 살아나오니, 다리오 왕은 온 나라에 하나님을 경외하라 명했다.','날마다의 기도 습관을 목숨 걸고 지킨 신실함에 하나님은 놀라운 방법으로 응답하신다.',ARRAY['충성과 신실함','인도하심과 보호']::text[],'위협 속에서도 나는 기도의 습관과 신앙의 원칙을 지키고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/182'),
(183,'다니엘의 회개 기도와 칠십 이레 예언','구약','다니엘',27,'단 9:1-27',ARRAY['다니엘','가브리엘','하나님']::text[],'예레미야의 예언을 깨달은 다니엘이 민족의 죄를 자기 죄처럼 여기며 금식하고 회개하자 가브리엘 천사가 나타나 칠십 이레의 예언으로 메시아의 오심을 알려주었다.','공동체의 죄를 자신의 죄처럼 여기며 회개하는 중보의 기도에 하나님은 깊은 계시로 응답하신다.',ARRAY['기도와 응답','회개와 용서']::text[],'나는 공동체나 민족의 죄를 나의 죄처럼 여기며 기도한 적이 있는가?',ARRAY['성인']::text[],'v1','/s/183'),
(184,'호세아와 고멜의 결혼','구약','호세아',28,'호 1:1-3:5',ARRAY['호세아','고멜','하나님']::text[],'하나님이 호세아에게 음란한 여인 고멜과 결혼하라 명하셨고, 고멜이 다른 남자에게로 떠난 후에도 호세아는 그를 값을 주고 다시 찾아와 사랑했다.','신실치 못한 백성을 향한 하나님의 사랑은 배신당해도 끝까지 찾아가 회복시키는 끈질긴 사랑이다.',ARRAY['하나님의 사랑','회개와 용서']::text[],'나를 향한 하나님의 끈질긴 사랑을 어떻게 경험하고 있는가?',ARRAY['성인']::text[],'v1','/s/184'),
(185,'나는 인애를 원하고 제사를 원하지 않는다','구약','호세아',28,'호 6:1-6',ARRAY['호세아','이스라엘 백성']::text[],'호세아는 형식적인 제사보다 하나님을 아는 지식과 인애를 원하신다는 하나님의 마음을 전하며 진심 없는 회개의 얕음을 지적했다.','하나님이 원하시는 것은 형식적 종교 행위가 아니라 진심 어린 관계와 사랑이다.',ARRAY['예배와 경배','회개와 용서']::text[],'나의 신앙은 형식에 머무는가, 진심 어린 관계로 나아가는가?',ARRAY['성인']::text[],'v1','/s/185'),
(186,'여호와의 날과 성령을 부어주심','구약','요엘',29,'욜 2:1-32',ARRAY['요엘','이스라엘 백성','하나님']::text[],'메뚜기 재앙을 겪은 백성에게 요엘은 마음을 찢고 돌아오라 촉구하며, 장차 하나님이 모든 육체에 성령을 부어주실 날을 예언했다.','진정한 회개는 겉옷이 아니라 마음을 찢는 것이며, 그 회개 위에 하나님의 영이 부어진다.',ARRAY['회개와 용서','성령의 역사']::text[],'나는 겉모습이 아닌 마음으로 하나님께 돌아가고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/186'),
(187,'정의가 물같이, 공의가 강같이','구약','아모스',30,'암 5:1-27',ARRAY['아모스','이스라엘 백성']::text[],'목자 출신 선지자 아모스는 형식적 예배에 치중하면서 가난한 자를 착취하는 이스라엘을 책망하며 정의가 물같이, 공의가 강같이 흐르게 하라 외쳤다.','형식적인 종교 행위는 사회적 정의와 이웃 사랑이 없이는 하나님께 열납되지 않는다.',ARRAY['사랑과 섬김','하나님의 심판']::text[],'나의 신앙은 실제적인 정의와 나눔의 삶으로 이어지고 있는가?',ARRAY['성인']::text[],'v1','/s/187'),
(188,'에돔의 교만에 대한 심판','구약','오바댜',31,'옵 1:1-21',ARRAY['오바댜','에돔']::text[],'오바댜는 형제 나라 이스라엘의 환난 날에 오히려 기뻐하고 약탈에 가담한 에돔의 교만을 책망하며 그들에게 임할 심판을 선포했다.','형제의 고난을 이용하거나 방관하는 태도는 하나님 앞에서 무겁게 다뤄지는 죄이다.',ARRAY['시기와 갈등','하나님의 심판']::text[],'나는 가까운 이의 어려움 앞에서 돕는 자인가, 방관하는 자인가?',ARRAY['성인']::text[],'v1','/s/188'),
(189,'요나가 니느웨로 가라는 명령을 피함','구약','요나',32,'욘 1:1-17',ARRAY['요나','선원들','하나님']::text[],'니느웨에 가서 외치라는 하나님의 명령을 피해 다시스로 도망하던 요나는 폭풍 속에서 바다에 던져져 큰 물고기에게 삼켜졌다.','하나님의 부르심을 피해 도망쳐도 그분의 계획은 예상치 못한 방법으로 우리를 붙드신다.',ARRAY['순종과 믿음','하나님의 섭리']::text[],'나는 하기 싫은 하나님의 명령을 피해 도망친 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/189'),
(190,'물고기 뱃속에서의 기도','구약','요나',32,'욘 2:1-10',ARRAY['요나','하나님']::text[],'물고기 뱃속에서 사흘을 지낸 요나가 죽음의 자리에서 하나님께 부르짖어 기도하니 물고기가 그를 육지에 토해냈다.','가장 절망적인 상황에서도 하나님을 향한 부르짖음은 결코 헛되지 않는다.',ARRAY['기도와 응답','회개와 용서']::text[],'내 인생의 ''물고기 뱃속'' 같은 순간에 나는 하나님께 부르짖었는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/190'),
(191,'니느웨가 회개함','구약','요나',32,'욘 3:1-10',ARRAY['요나','니느웨 왕','니느웨 백성']::text[],'다시 명령받은 요나가 니느웨에 가서 외치자 왕부터 백성까지 굵은 베를 입고 금식하며 악한 길에서 돌이키니 하나님이 그 심판을 거두셨다.','진심 어린 회개는 크고 악한 도시라도 하나님의 긍휼을 이끌어낼 수 있다.',ARRAY['회개와 용서','전도와 선교']::text[],'나는 전혀 가망 없어 보이는 사람이나 공동체의 회개 가능성을 믿는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/191'),
(192,'요나의 분노와 하나님의 마지막 가르침','구약','요나',32,'욘 4:1-11',ARRAY['요나','하나님']::text[],'니느웨가 멸망하지 않자 분노한 요나에게 하나님은 박넝쿨의 비유로 요나 자신은 수고 없이 얻은 것을 아까워하면서 왜 자신은 십이만 명이 넘는 영혼을 아끼지 말아야 하느냐 물으셨다.','우리의 좁은 편견과 달리 하나님의 긍휼은 모든 민족과 생명을 품는 넓은 사랑이다.',ARRAY['하나님의 사랑','전도와 선교']::text[],'나는 하나님의 긍휼을 나와 다른 사람에게도 똑같이 적용하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/192'),
(193,'정의를 행하며 인자를 사랑하며 겸손히 행하라','구약','미가',33,'미 6:1-8',ARRAY['미가','이스라엘 백성']::text[],'미가는 수많은 제물과 예물보다 하나님이 진정 원하시는 것은 정의를 행하고 인자를 사랑하며 겸손히 하나님과 함께 행하는 것이라 선포했다.','하나님이 원하시는 신앙의 본질은 화려한 종교 행위가 아니라 정의와 사랑, 겸손의 삶이다.',ARRAY['사랑과 섬김','겸손과 교만']::text[],'정의, 인자, 겸손 중 오늘 내게 가장 부족한 것은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/193'),
(194,'베들레헴에서 나실 통치자 예언','구약','미가',33,'미 5:2-5',ARRAY['미가']::text[],'미가는 작고 보잘것없는 베들레헴에서 장차 이스라엘을 다스릴 자가 나올 것이며 그의 근본은 상고에, 영원에 있다고 예언했다.','하나님은 가장 작고 낮은 곳을 통해 가장 위대한 구원의 계획을 이루신다.',ARRAY['예수 그리스도의 정체성','하나님의 섭리']::text[],'하나님은 작고 낮은 것을 통해서도 크게 일하신다는 사실이 내게 주는 위로는 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/194'),
(195,'니느웨의 멸망 예언','구약','나훔',34,'나 1:1-3:19',ARRAY['나훔','니느웨']::text[],'요나 시대에 회개했던 니느웨가 다시 악해지자 나훔은 하나님이 악을 참지 않으시는 공의로운 재판장이심을 선포하며 그 도시의 멸망을 예언했다.','일시적인 회개 이후 다시 악으로 돌아가면 하나님의 공의로운 심판을 피할 수 없다.',ARRAY['하나님의 심판','회개와 용서']::text[],'한때의 회개 이후 다시 옛 모습으로 돌아간 부분은 없는지 돌아보자.',ARRAY['성인']::text[],'v1','/s/195'),
(196,'의인은 믿음으로 말미암아 살리라','구약','하박국',35,'합 1:1-2:4',ARRAY['하박국','하나님']::text[],'악인이 형통한 현실에 질문하던 하박국에게 하나님은 정한 때에 반드시 이루어질 계시를 기다리라 하시며 의인은 그 믿음으로 말미암아 살리라 답하셨다.','이해되지 않는 현실 속에서도 하나님의 때를 신뢰하며 믿음으로 사는 것이 참된 의인의 삶이다.',ARRAY['순종과 믿음','고난과 인내']::text[],'답을 알 수 없는 상황에서도 나는 믿음으로 기다릴 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/196'),
(197,'비록 무화과나무가 무성치 못하며','구약','하박국',35,'합 3:1-19',ARRAY['하박국','하나님']::text[],'하박국은 모든 소출이 끊어지는 최악의 상황을 가정하면서도 여전히 구원의 하나님으로 말미암아 기뻐하며 즐거워하겠다는 신앙의 결단을 노래했다.','상황이 아무리 나빠져도 구원의 하나님 그 자체를 기뻐하는 것이 성숙한 신앙이다.',ARRAY['고난과 인내','예배와 경배']::text[],'상황과 상관없이 하나님을 기뻐할 수 있는 믿음이 내게 있는가?',ARRAY['성인']::text[],'v1','/s/197'),
(198,'여호와의 크고 두려운 날','구약','스바냐',36,'습 1:1-3:20',ARRAY['스바냐','유다 백성']::text[],'스바냐는 임박한 여호와의 날의 심판을 경고하면서도 마지막에는 하나님이 딸 시온 가운데서 구원을 베풀며 기쁨으로 노래하실 것을 약속했다.','심판의 경고 뒤에는 언제나 회복과 기쁨의 약속이 함께한다.',ARRAY['하나님의 심판','종말과 소망']::text[],'심판의 경고 앞에서 나는 회개와 소망 중 무엇으로 반응하는가?',ARRAY['성인']::text[],'v1','/s/198'),
(199,'성전 재건을 촉구함','구약','학개',37,'학 1:1-2:9',ARRAY['학개','스룹바벨','여호수아']::text[],'포로 귀환 후 자기 집만 짓고 성전 건축을 미루던 백성에게 학개는 하나님의 집이 황폐한데 너희만 잘 살려 하느냐 책망하며 성전 재건을 독려했다.','자신의 안락함을 앞세우고 하나님의 일을 뒤로 미루는 우선순위를 점검해야 한다.',ARRAY['순종과 믿음','예배와 경배']::text[],'나는 내 일과 하나님의 일 중 무엇을 먼저 챙기고 있는가?',ARRAY['성인']::text[],'v1','/s/199'),
(200,'스가랴의 환상들과 겸손한 왕 예언','구약','스가랴',38,'슥 1:1-14:21',ARRAY['스가랴','여호수아','스룹바벨']::text[],'스가랴는 여러 상징적 환상을 통해 성전 재건과 회복을 격려했고, 장차 나귀를 타고 겸손히 오실 왕에 대해서도 예언했다.','하나님의 회복 계획은 화려함이 아닌 겸손함으로 임하는 왕을 통해 이루어진다.',ARRAY['예수 그리스도의 정체성','겸손과 교만']::text[],'겸손히 오시는 왕의 모습이 내게 주는 도전은 무엇인가?',ARRAY['성인']::text[],'v1','/s/200'),
(201,'십일조와 축복의 약속','구약','말라기',39,'말 3:6-12',ARRAY['말라기','이스라엘 백성']::text[],'말라기는 백성이 십일조와 헌물로 하나님의 것을 도둑질했다 책망하며, 온전한 십일조를 드리면 하늘 문을 열어 복을 쌓을 곳이 없도록 부어주시겠다 약속했다.','드림의 신실함은 하나님을 향한 신뢰의 표현이며, 그 신뢰에 하나님은 넘치는 복으로 응답하신다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나는 재정과 소유에 있어 하나님을 얼마나 신뢰하며 드리고 있는가?',ARRAY['성인']::text[],'v1','/s/201'),
(202,'여호와의 날과 엘리야의 재림 예언','구약','말라기',39,'말 4:1-6',ARRAY['말라기']::text[],'말라기는 구약의 마지막 선지자로서 공의의 해가 떠오를 심판의 날을 예고하며, 그 날 전에 엘리야 같은 선지자를 보내 아버지의 마음을 자녀에게로 돌이키게 하실 것을 예언하며 구약을 마무리한다.','구약은 심판의 경고와 함께 화목케 하시는 하나님의 마음으로 마무리되며 신약의 소망으로 이어진다.',ARRAY['하나님의 심판','종말과 소망']::text[],'구약 전체가 가리키는 소망이 신약에서 어떻게 성취되는지 기대해보자.',ARRAY['성인']::text[],'v1','/s/202'),
(203,'세례요한의 출생을 예고받음','신약','누가복음',42,'눅 1:5-25',ARRAY['사가랴','엘리사벳','천사 가브리엘']::text[],'늙도록 자녀가 없던 제사장 사가랴에게 천사 가브리엘이 나타나 아들을 주실 것과 그가 주의 길을 예비할 것을 예고했으나, 사가랴는 의심하다 말을 하지 못하게 되었다.','하나님의 놀라운 계획은 종종 사람이 불가능하다 여기는 상황 속에서 시작된다.',ARRAY['하나님의 섭리','순종과 믿음']::text[],'불가능해 보이는 기도 제목을 나는 여전히 하나님께 맡기고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/203'),
(204,'마리아에게 수태고지','신약','누가복음',42,'눅 1:26-38',ARRAY['마리아','천사 가브리엘']::text[],'천사 가브리엘이 나사렛 처녀 마리아에게 나타나 성령으로 잉태하여 지극히 높으신 이의 아들을 낳을 것을 전하자, 마리아는 ''주의 여종이오니 말씀대로 내게 이루어지이다'' 순종했다.','불가능해 보이는 하나님의 계획 앞에서도 순전한 순종은 구원의 통로가 된다.',ARRAY['순종과 믿음','예수 그리스도의 정체성']::text[],'나는 이해되지 않는 하나님의 계획 앞에서도 순종할 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/204'),
(205,'마리아가 엘리사벳을 방문함(마리아의 찬가)','신약','누가복음',42,'눅 1:39-56',ARRAY['마리아','엘리사벳']::text[],'마리아가 엘리사벳을 방문하자 태중의 아기가 뛰놀았고, 마리아는 ''내 영혼이 주를 찬양하며''로 시작하는 찬가를 통해 낮은 자를 높이시는 하나님을 노래했다.','하나님은 낮고 작은 자를 들어 크신 일을 이루시니, 겸손한 자의 찬양이 마땅하다.',ARRAY['겸손과 교만','예배와 경배']::text[],'나는 낮아짐 가운데서도 하나님을 찬양할 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/205'),
(206,'요셉에게 나타난 천사','신약','마태복음',40,'마 1:18-25',ARRAY['요셉','마리아','천사']::text[],'마리아의 잉태를 알고 조용히 파혼하려던 요셉에게 천사가 꿈에 나타나 성령으로 된 일임을 알리며 아기 이름을 예수라 하라 명하니 요셉이 순종하여 마리아를 아내로 맞았다.','의로운 요셉의 순종은 하나님의 계획을 이루는 데 없어서는 안 될 신실한 순종이었다.',ARRAY['순종과 믿음','가정과 관계']::text[],'가정 안에서 이해되지 않는 상황에도 순종해야 했던 경험이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/206'),
(207,'예수님의 탄생과 목자들','신약','누가복음',42,'눅 2:1-20',ARRAY['마리아','요셉','아기 예수','목자들','천사들']::text[],'호적 등록으로 베들레헴에 간 마리아와 요셉이 마구간에서 예수님을 낳았고, 들에서 양을 치던 목자들에게 천사들이 나타나 구주의 탄생을 알렸다.','가장 낮고 소외된 목자들에게 먼저 알려진 구주의 탄생은 하나님 나라의 가치가 세상과 다름을 보여준다.',ARRAY['예수 그리스도의 정체성','겸손과 교만']::text[],'가장 낮은 자리에서 시작된 구원의 소식이 내게 주는 의미는 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/207'),
(208,'동방박사의 방문','신약','마태복음',40,'마 2:1-12',ARRAY['동방박사들','헤롯 왕','아기 예수']::text[],'동방에서 별을 보고 온 박사들이 예루살렘을 거쳐 베들레헴에서 아기 예수를 찾아 경배하며 황금과 유향과 몰약을 예물로 드렸다.','이방인들도 별의 인도를 따라 참된 왕을 찾아 경배했으니, 구원은 모든 민족에게 열려 있다.',ARRAY['예배와 경배','전도와 선교']::text[],'나는 세상 끝까지 열려 있는 구원의 소식을 어떻게 전하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/208'),
(209,'애굽으로의 피난과 헤롯의 유아 학살','신약','마태복음',40,'마 2:13-23',ARRAY['요셉','마리아','아기 예수','헤롯 왕']::text[],'꿈에 경고받은 요셉이 가족을 데리고 애굽으로 피신했고, 분노한 헤롯은 베들레헴 부근의 두 살 이하 사내아이들을 모두 죽였다.','하나님의 구원 계획은 세상 권력의 폭력적 위협 속에서도 신실하게 보호되고 이어진다.',ARRAY['인도하심과 보호','하나님의 섭리']::text[],'무고한 아이들의 희생 앞에서 우리는 어떤 기도와 반응을 해야 할까?',ARRAY['청소년','성인']::text[],'v1','/s/209'),
(210,'열두 살 예수님이 성전에서','신약','누가복음',42,'눅 2:41-52',ARRAY['예수님','마리아','요셉','성전의 선생들']::text[],'유월절에 예루살렘에 갔던 열두 살 예수님이 돌아가는 길에 없어진 것을 알고 찾아보니 성전에서 선생들과 문답하고 계셨고, 예수님은 ''내 아버지 집에 있어야 할 줄을 알지 못하셨나이까'' 답하셨다.','어린 시절부터 예수님은 아버지 하나님의 뜻을 자신의 정체성의 중심에 두셨다.',ARRAY['예수 그리스도의 정체성','예배와 경배']::text[],'나는 어릴 때부터 하나님을 내 삶의 중심에 두는 훈련을 받고 있는가(혹은 자녀에게 가르치고 있는가)?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/210'),
(211,'세례요한의 사역','신약','마태복음',40,'마 3:1-12',ARRAY['세례요한','바리새인들','사두개인들']::text[],'광야에서 낙타털 옷을 입고 메뚜기와 석청을 먹으며 지내던 세례요한이 회개의 세례를 전파하며 회개에 합당한 열매를 맺으라 외치고 자기보다 능력 많으신 이가 오실 것을 예고했다.','진정한 회개는 말뿐 아니라 삶의 변화된 열매로 나타나야 한다.',ARRAY['회개와 용서','전도와 선교']::text[],'내 회개는 삶의 구체적인 열매로 나타나고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/211'),
(212,'예수님의 세례','신약','마태복음',40,'마 3:13-17',ARRAY['예수님','세례요한','성령','하나님']::text[],'예수님이 요한에게 세례를 받으시니 하늘이 열리고 성령이 비둘기같이 임하며 하늘에서 ''이는 내 사랑하는 아들이라 내가 기뻐하는 자''라는 음성이 들렸다.','예수님의 공생애는 삼위 하나님의 확증 가운데 시작되었으며, 이는 우리의 정체성도 하나님의 사랑 안에 있음을 보여준다.',ARRAY['예수 그리스도의 정체성','성령의 역사']::text[],'나는 하나님이 나를 사랑하는 자녀로 기뻐하신다는 사실을 얼마나 확신하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/212'),
(213,'광야에서의 시험','신약','마태복음',40,'마 4:1-11',ARRAY['예수님','사탄']::text[],'성령에 이끌려 광야에서 사십 일을 금식하신 예수님이 돌을 떡으로 만들라는 시험, 성전에서 뛰어내리라는 시험, 자신에게 절하면 천하를 주겠다는 시험을 모두 말씀으로 물리치셨다.','유혹을 이기는 힘은 자신의 의지가 아니라 하나님의 말씀을 붙드는 데서 나온다.',ARRAY['순종과 믿음','고난과 인내']::text[],'유혹의 순간, 나는 말씀으로 그것을 물리치는 훈련이 되어 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/213'),
(214,'첫 제자들을 부르심','신약','요한복음',43,'요 1:35-51',ARRAY['안드레','베드로','빌립','나다나엘','예수님']::text[],'세례요한의 제자였던 안드레가 예수님을 만난 후 형제 베드로를 데려왔고, 빌립과 나다나엘도 차례로 예수님을 만나 ''랍비여 당신은 하나님의 아들이시요 이스라엘의 임금이로소이다'' 고백했다.','한 사람의 만남과 초청이 또 다른 사람을 예수님께로 인도하는 전도의 시작이 된다.',ARRAY['전도와 선교','순종과 믿음']::text[],'나는 예수님을 만난 기쁨을 누군가에게 전한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/214'),
(215,'가나의 혼인잔치(첫 표적)','신약','요한복음',43,'요 2:1-11',ARRAY['예수님','마리아','제자들']::text[],'가나의 혼인잔치에서 포도주가 떨어지자 예수님이 물 항아리의 물을 좋은 포도주로 변화시켜 첫 표적을 행하시니 제자들이 그를 믿었다.','예수님은 일상의 필요와 기쁨의 자리에도 함께하시며 부족함을 넘치는 은혜로 채우신다.',ARRAY['예수님의 기적','하나님의 섭리']::text[],'일상의 기쁜 자리에서 예수님과 함께한 경험을 나눠보자.',ARRAY['어린이','청소년','성인']::text[],'v1','/s/215'),
(216,'니고데모와의 대화(거듭남)','신약','요한복음',43,'요 3:1-21',ARRAY['니고데모','예수님']::text[],'밤에 찾아온 바리새인 니고데모에게 예수님은 사람이 물과 성령으로 거듭나지 않으면 하나님 나라를 볼 수 없다 말씀하시며 하나님이 세상을 이처럼 사랑하사 독생자를 주셨다 선포하셨다.','구원은 종교적 지식이나 혈통이 아니라 성령으로 인한 전적으로 새로운 출생이다.',ARRAY['하나님의 사랑','성령의 역사']::text[],'나는 거듭남을 통해 새로운 정체성으로 살아가고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/216'),
(217,'사마리아 여인과의 대화','신약','요한복음',43,'요 4:1-42',ARRAY['사마리아 여인','예수님','제자들']::text[],'우물가에서 만난 사마리아 여인에게 예수님은 생수에 대해 말씀하시며 그의 감춰진 삶까지 아셨고, 여인은 마을로 돌아가 그리스도를 전하니 많은 사마리아인이 믿게 되었다.','예수님은 사회적 편견을 넘어 소외된 이에게 먼저 다가가시며 그를 전도자로 세우신다.',ARRAY['전도와 선교','하나님의 사랑']::text[],'나는 사회적 편견 때문에 다가가지 못하는 누군가가 있지는 않은가?',ARRAY['청소년','성인']::text[],'v1','/s/217'),
(218,'베드로를 부르심(고기잡이 기적)','신약','누가복음',42,'눅 5:1-11',ARRAY['베드로','야고보','요한','예수님']::text[],'밤새 헛수고한 베드로에게 예수님이 다시 그물을 내리라 하시니 그물이 찢어질 정도로 많은 고기가 잡혔고, 베드로는 두려워하며 엎드렸으나 예수님은 그를 사람 낚는 어부로 부르셨다.','순종함으로 얻은 은혜는 자신의 부족함을 깨닫게 하며 새로운 사명으로 이끈다.',ARRAY['순종과 믿음','전도와 선교']::text[],'순종했을 때 예상보다 큰 은혜를 경험한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/218'),
(219,'마태(레위)를 부르심','신약','마태복음',40,'마 9:9-13',ARRAY['마태','예수님','바리새인들']::text[],'세리로 멸시받던 마태를 예수님이 ''나를 따르라'' 부르시니 그는 즉시 일어나 따랐고, 예수님은 죄인들과 함께 식사하시며 건강한 자에게는 의원이 쓸데없다 말씀하셨다.','예수님은 사회에서 멸시받던 사람도 부르시고 함께하시는 구원자이시다.',ARRAY['하나님의 사랑','순종과 믿음']::text[],'나는 소외되고 멸시받는 이들에게 예수님처럼 다가가고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/219'),
(220,'나병환자를 고치심','신약','마태복음',40,'마 8:1-4',ARRAY['예수님','나병환자']::text[],'부정하다 여겨져 소외되었던 나병환자가 예수님께 나아와 ''원하시면 저를 깨끗하게 하실 수 있나이다'' 하자 예수님이 손을 대어 즉시 고치셨다.','예수님은 사회적으로 접촉이 금기시된 사람에게도 직접 손을 대시는 사랑의 주님이시다.',ARRAY['예수님의 기적','사랑과 섬김']::text[],'나는 소외된 이에게 다가가 직접 손 내미는 사랑을 실천하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/220'),
(221,'백부장의 종을 고치심','신약','마태복음',40,'마 8:5-13',ARRAY['백부장','예수님']::text[],'이방인 백부장이 예수님께 말씀만 하시면 종이 나으리라는 믿음을 고백하니 예수님이 그 믿음에 놀라시며 말씀만으로 멀리 있는 종을 고쳐주셨다.','말씀의 권세를 신뢰하는 믿음은 혈통이나 배경을 넘어 예수님을 놀라게 할 만큼 귀하다.',ARRAY['순종과 믿음','예수님의 기적']::text[],'나는 눈에 보이는 증거 없이도 예수님의 말씀만으로 신뢰하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/221'),
(222,'중풍병자를 지붕으로 달아내림','신약','마가복음',41,'막 2:1-12',ARRAY['중풍병자','네 친구','예수님','서기관들']::text[],'사람이 너무 많아 들어갈 수 없자 네 친구가 지붕을 뜯어 중풍병자를 예수님 앞에 달아내렸고, 예수님은 그 믿음을 보시고 죄 사함과 함께 몸을 고쳐주셨다.','친구를 예수님께 데려오려는 간절한 헌신과 창의적인 노력은 놀라운 은혜의 통로가 된다.',ARRAY['사랑과 섬김','순종과 믿음']::text[],'나는 누군가를 예수님께 데려가기 위해 어떤 수고를 감당하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/222'),
(223,'베데스다 못의 병자를 고치심','신약','요한복음',43,'요 5:1-15',ARRAY['병자','예수님']::text[],'삼십팔 년 된 병자에게 예수님이 ''네가 낫고자 하느냐'' 물으시고 안식일임에도 그를 일으켜 걷게 하시니 유대인들이 이를 문제 삼았다.','예수님의 긍휼은 종교적 관습보다 사람을 살리는 일을 우선하신다.',ARRAY['예수님의 기적','사랑과 섬김']::text[],'나는 형식적 규례와 사람을 살리는 사랑 중 무엇을 앞세우는가?',ARRAY['청소년','성인']::text[],'v1','/s/223'),
(224,'풍랑을 잠잠케 하심','신약','마가복음',41,'막 4:35-41',ARRAY['예수님','제자들']::text[],'갈릴리 바다에서 큰 풍랑을 만나 두려워하는 제자들 앞에서 예수님이 ''잠잠하라 고요하라'' 명하시니 바람과 바다가 순종하여 잔잔해졌다.','인생의 풍랑 가운데서도 예수님이 함께 계시면 두려워할 필요가 없다.',ARRAY['인도하심과 보호','순종과 믿음']::text[],'내 삶의 풍랑 속에서 나는 예수님을 향해 어떻게 부르짖고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/224'),
(225,'거라사 광인을 고치심','신약','마가복음',41,'막 5:1-20',ARRAY['거라사인','군대귀신','예수님']::text[],'무덤 사이에 살며 스스로를 해치던 귀신 들린 사람에게서 예수님이 군대라 하는 많은 귀신을 쫓아내 돼지 떼에게 들어가게 하시니 그 사람이 온전한 정신으로 옷을 입고 앉아 있었다.','예수님의 능력은 가장 파괴적이고 절망적인 속박에서도 사람을 온전히 회복시키신다.',ARRAY['하나님의 구원','인도하심과 보호']::text[],'내 삶이나 주변에서 회복이 절실한 속박은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/225'),
(226,'야이로의 딸과 혈루증 여인','신약','마가복음',41,'막 5:21-43',ARRAY['야이로','혈루증 여인','예수님']::text[],'회당장 야이로의 죽어가는 딸을 향해 가시던 중 열두 해 혈루증을 앓던 여인이 예수님의 옷자락을 만져 나았고, 이미 죽은 야이로의 딸도 ''달리다굼'' 말씀으로 살아났다.','작은 만짐의 믿음과 절망적인 죽음의 자리 모두에서 예수님의 능력은 동일하게 역사하신다.',ARRAY['순종과 믿음','예수님의 기적']::text[],'죽음처럼 절망적인 상황에서도 나는 예수님을 향해 나아갈 믿음이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/226'),
(227,'오병이어(오천 명을 먹이심)','신약','마태복음',40,'마 14:13-21',ARRAY['예수님','제자들','한 아이','무리']::text[],'외딴 곳에 모인 오천 명이 넘는 무리를 향해 제자들이 흩어보내자 했으나, 예수님은 한 아이의 보리떡 다섯 개와 물고기 두 마리로 그들 모두를 먹이시고 열두 바구니가 남았다.','작은 것이라도 예수님의 손에 드려지면 넘치는 은혜가 된다.',ARRAY['예수님의 기적','순종과 믿음']::text[],'내가 가진 작은 것 중에 하나님께 드릴 수 있는 것은 무엇일까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/227'),
(228,'물 위를 걸으심','신약','마태복음',40,'마 14:22-33',ARRAY['예수님','베드로','제자들']::text[],'밤에 바다 위로 걸어오신 예수님을 보고 놀란 제자들 중 베드로가 물 위를 걷다가 바람을 보고 두려워 빠지려 하자 예수님이 손을 잡아 건지셨다.','시선을 예수님께 고정할 때 불가능한 일도 가능해지지만, 상황에 시선을 빼앗기면 두려움에 빠진다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 지금 상황과 예수님 중 어디에 시선을 두고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/228'),
(229,'가나안 여인의 믿음','신약','마태복음',40,'마 15:21-28',ARRAY['가나안 여인','예수님','제자들']::text[],'이방 여인이 귀신 들린 딸을 위해 간청하자 예수님이 그 믿음을 시험하듯 답하셨으나, 여인이 겸손하고 끈질기게 구하니 ''네 믿음이 크도다'' 칭찬하시며 딸을 고쳐주셨다.','겸손하고 끈질긴 믿음의 간구는 인종과 경계를 넘어 예수님의 마음을 움직인다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 응답이 늦어질 때도 겸손히 끈질기게 구하는 믿음이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/229'),
(230,'사천 명을 먹이심','신약','마가복음',41,'막 8:1-10',ARRAY['예수님','제자들','무리']::text[],'떡 일곱 개와 작은 물고기 두어 마리로 예수님이 사천 명이 넘는 무리를 먹이시니 일곱 광주리가 남았다.','반복되는 공급의 기적은 예수님이 언제나 부족함을 채우시는 신실한 분이심을 보여준다.',ARRAY['예수님의 기적','인도하심과 보호']::text[],'반복해서 채워주신 하나님의 공급을 기억하며 감사할 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/230'),
(231,'날 때부터 맹인된 자를 고치심','신약','요한복음',43,'요 9:1-41',ARRAY['맹인','예수님','바리새인들']::text[],'날 때부터 맹인된 사람을 진흙과 실로암 못의 물로 고치신 예수님은 이 일이 누구의 죄 때문이 아니라 하나님의 하시는 일을 나타내기 위함이라 하셨고, 고침받은 자는 담대히 예수님을 증언했다.','고난은 언제나 죄의 결과가 아니며, 하나님은 그것을 통해서도 자신의 영광을 나타내실 수 있다.',ARRAY['고난과 인내','예수님의 기적']::text[],'이유를 알 수 없는 고난 속에서 하나님의 영광을 기대할 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/231'),
(232,'맹인 바디매오를 고치심','신약','마태복음',40,'마 20:29-34',ARRAY['바디매오','예수님','무리']::text[],'여리고 성 밖에서 구걸하던 맹인 바디매오가 무리의 만류에도 ''다윗의 자손이여 나를 불쌍히 여기소서'' 외쳐 예수님을 만났고 즉시 눈을 뜨게 되었다.','포기하지 않고 간절히 부르짖는 믿음은 무리의 만류에도 굴하지 않고 응답을 이끌어낸다.',ARRAY['기도와 응답','순종과 믿음']::text[],'응답을 얻을 때까지 포기하지 않는 간절함이 내게 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/232'),
(233,'열 나병환자를 고치심','신약','누가복음',42,'눅 17:11-19',ARRAY['열 명의 나병환자','예수님','사마리아인']::text[],'열 명의 나병환자가 예수님께 고침을 받았으나 그 중 사마리아인 한 사람만 돌아와 감사하니 예수님은 ''그 아홉은 어디 있느냐''며 안타까워하셨다.','받은 은혜를 잊지 않고 돌아와 감사하는 태도는 은혜 자체만큼이나 소중하다.',ARRAY['사랑과 섬김','예배와 경배']::text[],'나는 받은 은혜에 얼마나 신실하게 감사로 반응하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/233'),
(234,'나사로를 살리심','신약','요한복음',43,'요 11:1-44',ARRAY['나사로','마르다','마리아','예수님']::text[],'이미 나흘이나 무덤에 있던 나사로를 향해 예수님이 ''나사로야 나오라'' 외치시니 죽은 자가 살아 나왔고, 이를 통해 예수님은 자신이 부활이요 생명임을 나타내셨다.','예수님은 죽음조차도 뒤집으시는 부활과 생명의 주님이시다.',ARRAY['예수 그리스도의 정체성','종말과 소망']::text[],'죽음처럼 소망 없어 보이는 상황에서도 나는 부활의 능력을 신뢰하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/234'),
(235,'산상수훈: 팔복','신약','마태복음',40,'마 5:1-12',ARRAY['예수님','제자들','무리']::text[],'예수님이 산에 올라 심령이 가난한 자, 애통하는 자, 온유한 자 등 여덟 가지 복 있는 사람의 모습을 가르치셨다.','하나님 나라의 복은 세상의 기준과 달리 낮아짐과 의를 향한 갈망 속에 있다.',ARRAY['예수님의 가르침','하나님 나라']::text[],'팔복 중 지금 내게 가장 필요한 복은 무엇이라고 생각하는가?',ARRAY['청소년','성인']::text[],'v1','/s/235'),
(236,'산상수훈: 소금과 빛','신약','마태복음',40,'마 5:13-16',ARRAY['예수님','제자들']::text[],'예수님은 제자들에게 너희는 세상의 소금이요 빛이니 그 빛을 사람 앞에 비추어 착한 행실로 하나님께 영광을 돌리라 말씀하셨다.','그리스도인의 삶은 세상 속에서 맛과 방향을 보여주는 소금과 빛의 역할을 감당해야 한다.',ARRAY['예수님의 가르침','전도와 선교']::text[],'나는 내가 속한 곳에서 소금과 빛의 역할을 어떻게 감당하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/236'),
(237,'주기도문','신약','마태복음',40,'마 6:5-15',ARRAY['예수님','제자들']::text[],'은밀한 중에 보시는 아버지께 기도하라 가르치신 예수님은 하늘에 계신 아버지를 부르며 그 이름과 나라와 뜻을 구하고 일용할 양식과 용서를 구하는 주기도문을 알려주셨다.','기도는 화려한 말이 아니라 하나님의 뜻을 구하고 일상의 필요와 용서를 간구하는 진솔한 대화이다.',ARRAY['기도와 응답','예수님의 가르침']::text[],'주기도문의 각 구절 중 오늘 내게 가장 절실한 간구는 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/237'),
(238,'반석 위에 지은 집 비유','신약','마태복음',40,'마 7:24-27',ARRAY['예수님','제자들']::text[],'예수님은 자신의 말을 듣고 행하는 자는 반석 위에 집을 지은 지혜로운 사람과 같고, 듣고 행하지 않는 자는 모래 위에 지은 어리석은 사람과 같다 말씀하셨다.','말씀을 듣는 것에 그치지 않고 삶으로 실천하는 것이 인생의 견고한 기초가 된다.',ARRAY['순종과 믿음','지혜와 분별']::text[],'나는 들은 말씀을 삶으로 실천하는 반석 위의 삶을 살고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/238'),
(239,'씨 뿌리는 자의 비유','신약','마태복음',40,'마 13:1-23',ARRAY['예수님','무리']::text[],'길가, 돌밭, 가시떨기, 좋은 땅에 떨어진 씨앗의 비유를 통해 예수님은 말씀을 받는 사람의 마음 상태에 따라 열매 맺는 결과가 달라짐을 가르치셨다.','같은 말씀을 들어도 내 마음의 밭이 어떠한가에 따라 열매의 크기가 달라진다.',ARRAY['예수님의 가르침','순종과 믿음']::text[],'내 마음은 지금 어떤 밭의 상태에 가까운가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/239'),
(240,'가라지 비유','신약','마태복음',40,'마 13:24-30,36-43',ARRAY['예수님','제자들']::text[],'좋은 씨를 심은 밭에 원수가 몰래 가라지를 심었으나 주인은 추수 때까지 함께 자라게 두라 하니, 예수님은 이를 세상 끝날 알곡과 가라지가 나뉠 심판에 비유하셨다.','선과 악이 공존하는 세상에서도 하나님은 때가 되면 반드시 공의로운 심판을 이루신다.',ARRAY['하나님의 심판','고난과 인내']::text[],'악이 함께 존재하는 현실 속에서 나는 하나님의 때를 신뢰하며 인내하는가?',ARRAY['청소년','성인']::text[],'v1','/s/240'),
(241,'겨자씨와 누룩 비유','신약','마태복음',40,'마 13:31-33',ARRAY['예수님','무리']::text[],'예수님은 하나님 나라를 아주 작은 겨자씨가 자라 큰 나무가 되는 것과 적은 누룩이 온 반죽을 부풀게 하는 것에 비유하셨다.','하나님 나라는 작고 미미해 보여도 결국 크고 온전하게 확장되어 가는 능력을 지녔다.',ARRAY['하나님 나라','순종과 믿음']::text[],'작아 보이는 나의 순종이 하나님 나라를 확장하는 데 쓰임받을 수 있음을 믿는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/241'),
(242,'감추인 보화와 값진 진주 비유','신약','마태복음',40,'마 13:44-46',ARRAY['예수님','무리']::text[],'예수님은 하나님 나라를 밭에 감추인 보화와 값진 진주에 비유하며 그것을 발견한 사람이 자기의 모든 소유를 팔아서라도 그것을 사는 것과 같다 말씀하셨다.','하나님 나라의 가치를 발견한 사람은 세상의 모든 것을 내려놓을 만큼의 기쁨으로 반응하게 된다.',ARRAY['하나님 나라','순종과 믿음']::text[],'나는 하나님 나라를 위해 무엇을 기쁨으로 내려놓을 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/242'),
(243,'용서하지 않은 종의 비유','신약','마태복음',40,'마 18:21-35',ARRAY['예수님','베드로','악한 종']::text[],'베드로가 몇 번 용서해야 하는지 묻자 예수님은 만 달란트 빚을 탕감받고도 백 데나리온 빚진 동료를 용서하지 않은 종의 비유로 끝없는 용서의 중요성을 가르치셨다.','하나님께 받은 헤아릴 수 없는 용서를 기억한다면 우리도 이웃을 향해 용서에 인색할 수 없다.',ARRAY['회개와 용서','사랑과 섬김']::text[],'나는 받은 용서에 비추어 이웃을 얼마나 관대하게 용서하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/243'),
(244,'선한 사마리아인의 비유','신약','누가복음',42,'눅 10:25-37',ARRAY['예수님','율법교사','사마리아인','제사장','레위인']::text[],'누가 내 이웃이냐 묻는 율법교사에게 예수님은 강도 만난 사람을 제사장과 레위인은 지나쳤으나 멸시받던 사마리아인이 자비를 베푼 비유로 참된 이웃 사랑을 가르치셨다.','참된 이웃 사랑은 종교적 지위가 아니라 실제적인 자비의 행동으로 나타난다.',ARRAY['사랑과 섬김','예수님의 가르침']::text[],'나는 지나치기 쉬운 누군가에게 사마리아인처럼 자비를 베푼 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/244'),
(245,'어리석은 부자의 비유','신약','누가복음',42,'눅 12:13-21',ARRAY['예수님','어리석은 부자']::text[],'풍성한 수확을 얻고 더 큰 곳간을 지으려던 부자에게 하나님은 ''오늘 밤 네 영혼을 도로 찾으리니''라 말씀하시며 하나님께 대하여 부요하지 못한 삶을 경고하셨다.','이 땅의 재물을 쌓는 데만 몰두하고 영원한 것을 준비하지 못하면 참으로 어리석은 삶이다.',ARRAY['지혜와 분별','시기와 갈등']::text[],'나는 하나님께 대하여 부요한 삶을 살고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/245'),
(246,'잃은 양과 잃은 드라크마 비유','신약','누가복음',42,'눅 15:1-10',ARRAY['예수님','바리새인들','세리와 죄인들']::text[],'죄인들과 함께하시는 예수님을 비난하는 바리새인들에게 예수님은 한 마리 잃은 양과 한 드라크마를 찾는 기쁨의 비유로 회개하는 죄인 한 명을 향한 하늘의 기쁨을 말씀하셨다.','하나님은 아흔아홉보다 잃어버린 한 영혼을 찾는 일에 더 큰 기쁨을 두신다.',ARRAY['하나님의 사랑','회개와 용서']::text[],'나는 하나님이 나를 찾으신 기쁨을 얼마나 실감하며 살고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/246'),
(247,'탕자의 비유','신약','누가복음',42,'눅 15:11-32',ARRAY['아버지','둘째 아들','맏아들']::text[],'재산을 미리 받아 떠난 둘째 아들이 모든 것을 탕진하고 돌아오자, 아버지는 멀리서부터 달려나와 그를 맞이하고 잔치를 베풀었다.','하나님 아버지는 돌아오는 죄인을 조건 없이 기쁘게 맞아주시는 분이다.',ARRAY['회개와 용서','하나님의 사랑']::text[],'나는 돌아온 아들과 맏아들 중 누구의 마음에 더 가까운가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/247'),
(248,'부자와 나사로 비유','신약','누가복음',42,'눅 16:19-31',ARRAY['부자','나사로','아브라함']::text[],'날마다 호화롭게 살던 부자는 문 앞의 거지 나사로를 외면했으나, 죽은 후 부자는 음부에서 고통받고 나사로는 아브라함의 품에서 위로받는 처지가 뒤바뀌었다.','이 땅에서의 부와 지위는 영원한 심판 앞에서 아무 의미가 없으니 가난한 이웃을 외면하지 말아야 한다.',ARRAY['사랑과 섬김','하나님의 심판']::text[],'내 문 앞의 ''나사로''를 나는 지금 외면하고 있지 않은가?',ARRAY['청소년','성인']::text[],'v1','/s/248'),
(249,'불의한 재판관 비유(끈질긴 기도)','신약','누가복음',42,'눅 18:1-8',ARRAY['예수님','과부','불의한 재판관']::text[],'불의한 재판관도 끈질긴 과부의 간청에 결국 응답하듯, 하물며 하나님은 밤낮 부르짖는 택하신 자들의 기도에 반드시 응답하신다며 예수님은 낙심하지 말고 기도하라 가르치셨다.','응답이 더뎌 보여도 낙심하지 않고 끈질기게 기도하는 것이 필요하다.',ARRAY['기도와 응답','고난과 인내']::text[],'나는 응답이 늦어질 때 기도를 포기하지 않고 계속할 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/249'),
(250,'바리새인과 세리의 기도','신약','누가복음',42,'눅 18:9-14',ARRAY['예수님','바리새인','세리']::text[],'자신을 의롭다 여기며 기도한 바리새인과 가슴을 치며 ''죄인인 나에게 자비를 베푸소서'' 기도한 세리 중, 예수님은 세리가 의롭다 하심을 받고 집으로 내려갔다 말씀하셨다.','자신을 높이는 기도가 아니라 낮추고 긍휼을 구하는 기도가 하나님 앞에 온전하다.',ARRAY['겸손과 교만','기도와 응답']::text[],'내 기도는 자기 의를 드러내는가, 겸손히 긍휼을 구하는가?',ARRAY['청소년','성인']::text[],'v1','/s/250'),
(251,'포도원 품꾼 비유','신약','마태복음',40,'마 20:1-16',ARRAY['예수님','포도원 주인','품꾼들']::text[],'아침부터 일한 일꾼과 저녁 늦게 온 일꾼 모두에게 동일한 품삯을 주는 포도원 주인의 비유를 통해 예수님은 하나님 나라의 은혜가 사람의 계산과 다름을 가르치셨다.','하나님의 은혜는 우리의 공로 계산이 아니라 그분의 선하신 뜻과 관대함에 근거한다.',ARRAY['하나님의 사랑','겸손과 교만']::text[],'나는 다른 이가 받는 은혜를 내 기준으로 시기하지는 않는가?',ARRAY['청소년','성인']::text[],'v1','/s/251'),
(252,'달란트 비유','신약','마태복음',40,'마 25:14-30',ARRAY['예수님','주인','세 종']::text[],'주인이 세 종에게 각각 다섯, 두, 한 달란트를 맡기고 떠났다가 돌아와 계산할 때, 부지런히 남긴 두 종은 칭찬받았으나 땅에 묻어두기만 한 종은 책망받았다.','하나님이 각자에게 맡기신 재능과 자원은 두려움으로 묻어둘 것이 아니라 신실하게 활용해야 할 책임이다.',ARRAY['충성과 신실함','지혜와 분별']::text[],'나는 내게 맡겨진 재능과 자원을 얼마나 신실하게 사용하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/252'),
(253,'열 처녀 비유','신약','마태복음',40,'마 25:1-13',ARRAY['예수님','열 처녀']::text[],'기름을 준비한 다섯 처녀와 준비하지 못한 다섯 처녀의 비유를 통해 예수님은 신랑이 언제 올지 알지 못하니 항상 깨어 준비하고 있으라 가르치셨다.','주님의 재림은 언제일지 알 수 없으니 늘 영적으로 깨어 준비된 삶을 살아야 한다.',ARRAY['종말과 소망','순종과 믿음']::text[],'나는 언제 주님을 만나도 준비된 삶을 살고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/253'),
(254,'악한 농부 비유','신약','마태복음',40,'마 21:33-46',ARRAY['예수님','대제사장들','바리새인들']::text[],'포도원 주인이 세를 준 농부들에게 종들과 마지막에는 아들까지 보냈으나 농부들이 그들을 죽인 비유를 통해 예수님은 자신을 거절하는 종교 지도자들의 죄를 지적하셨다.','반복된 은혜의 초청을 거절하고 거부하는 완악함은 결국 심판을 자초한다.',ARRAY['죄와 타락','하나님의 심판']::text[],'나는 반복된 하나님의 초청 앞에서 어떻게 반응하고 있는가?',ARRAY['성인']::text[],'v1','/s/254'),
(255,'혼인잔치 비유','신약','마태복음',40,'마 22:1-14',ARRAY['예수님','임금','초청받은 사람들']::text[],'왕이 아들의 혼인잔치에 초청했으나 사람들이 거절하자 길거리의 아무나 청하게 했다는 비유로, 예수님은 하나님 나라의 초청에 합당하게 예복을 갖추고 응해야 함을 가르치셨다.','하나님 나라의 초청은 모두에게 열려 있으나 그 은혜에 합당하게 반응하는 삶이 필요하다.',ARRAY['하나님 나라','순종과 믿음']::text[],'나는 하나님 나라의 초청에 합당한 삶의 옷을 입고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/255'),
(256,'선한 목자 비유','신약','요한복음',43,'요 10:1-21',ARRAY['예수님','양들']::text[],'예수님은 자신을 선한 목자로 소개하시며 양들을 위해 목숨을 버리는 목자와 삯꾼의 차이를 대조하시고 자신의 양은 그 음성을 안다고 말씀하셨다.','선한 목자이신 예수님은 자신의 생명을 희생하면서까지 양 떼를 책임지고 보호하신다.',ARRAY['예수 그리스도의 정체성','인도하심과 보호']::text[],'나는 선한 목자이신 예수님의 음성을 분별하며 따르고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/256'),
(257,'베드로의 신앙고백','신약','마태복음',40,'마 16:13-20',ARRAY['베드로','예수님','제자들']::text[],'가이사랴 빌립보에서 예수님이 사람들이 자신을 누구라 하는지 물으시자 베드로는 ''주는 그리스도시요 살아계신 하나님의 아들이시니이다'' 고백했고, 예수님은 그 고백 위에 교회를 세우겠다 하셨다.','교회의 참된 기초는 건물이나 제도가 아니라 예수님이 그리스도이심을 고백하는 믿음이다.',ARRAY['예수 그리스도의 정체성','교회와 공동체']::text[],'나는 예수님이 그리스도이심을 내 삶으로 분명히 고백하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/257'),
(258,'변화산 사건','신약','마태복음',40,'마 17:1-13',ARRAY['예수님','베드로','야고보','요한','모세','엘리야']::text[],'베드로와 야고보, 요한을 데리고 높은 산에 오르신 예수님의 얼굴이 해같이 빛나고 옷이 희어지며 모세와 엘리야가 나타났고, 하늘에서 ''이는 내 사랑하는 아들이니 너희는 그의 말을 들으라''는 음성이 들렸다.','예수님의 영광을 잠시 맛본 제자들처럼, 우리도 그 영광의 소망을 붙들고 그분의 말씀에 귀 기울여야 한다.',ARRAY['예수 그리스도의 정체성','순종과 믿음']::text[],'나는 일상 속에서 예수님의 말씀에 얼마나 귀 기울이고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/258'),
(259,'어린아이들을 축복하심','신약','마태복음',40,'마 19:13-15',ARRAY['예수님','어린아이들','제자들']::text[],'제자들이 어린아이들을 데려오는 것을 막으려 하자 예수님은 ''어린아이들이 내게 오는 것을 용납하고 금하지 말라 천국이 이런 자의 것이니라'' 하시며 그들을 안고 축복하셨다.','하나님 나라는 어린아이와 같이 순전하고 겸손하게 나아오는 자들에게 열려 있다.',ARRAY['하나님 나라','가정과 관계']::text[],'나는 어린아이 같은 순전함으로 예수님께 나아가고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/259'),
(260,'부자 청년(부자 관원)','신약','마태복음',40,'마 19:16-30',ARRAY['부자 청년','예수님']::text[],'영생을 얻는 법을 물은 부자 청년에게 예수님이 가진 것을 팔아 가난한 자를 주라 하시니 그는 재물이 많으므로 근심하며 돌아갔고, 예수님은 부자가 천국에 들어가기 어렵다 말씀하셨다.','재물에 대한 집착은 하나님 나라를 향한 전적인 헌신을 방해하는 가장 큰 장애물이 될 수 있다.',ARRAY['시기와 갈등','순종과 믿음']::text[],'내 삶에서 예수님을 온전히 따르는 데 걸림돌이 되는 것은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/260'),
(261,'삭개오','신약','누가복음',42,'눅 19:1-10',ARRAY['삭개오','예수님','무리']::text[],'키가 작아 뽕나무에 올라간 세리장 삭개오를 예수님이 부르시어 그 집에 머무시니, 삭개오는 재산의 절반을 가난한 자에게 나누고 토색한 것을 네 배로 갚겠다 결단했다.','진정으로 예수님을 만난 삶은 구체적인 회개와 나눔의 열매로 드러난다.',ARRAY['회개와 용서','사랑과 섬김']::text[],'예수님을 만난 후 내 삶에는 어떤 구체적인 변화의 열매가 있었는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/261'),
(262,'마르다와 마리아','신약','누가복음',42,'눅 10:38-42',ARRAY['마르다','마리아','예수님']::text[],'손님 접대에 분주했던 마르다가 말씀을 듣고 있던 동생 마리아를 나무라자 예수님은 ''마리아는 좋은 편을 택하였다''며 그의 곁에 앉아 말씀 듣는 것이 우선임을 말씀하셨다.','분주한 섬김도 중요하지만, 예수님의 말씀을 듣는 것이 가장 좋은 것을 택하는 길이다.',ARRAY['예배와 경배','사랑과 섬김']::text[],'나는 분주함과 예수님과의 조용한 시간 중 무엇에 더 많은 시간을 쓰는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/262'),
(263,'간음한 여인','신약','요한복음',43,'요 8:1-11',ARRAY['간음한 여인','예수님','서기관들','바리새인들']::text[],'서기관과 바리새인들이 간음하다 잡힌 여인을 돌로 치려 하자 예수님은 ''너희 중에 죄 없는 자가 먼저 돌로 치라'' 하시니 모두 물러갔고, 예수님은 여인에게 ''나도 너를 정죄하지 아니하노니 가서 다시는 죄를 범하지 말라'' 하셨다.','예수님의 은혜는 정죄 대신 용서와 새로운 삶의 기회를 주신다.',ARRAY['회개와 용서','하나님의 사랑']::text[],'나는 타인을 정죄하기보다 예수님처럼 은혜로 대하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/263'),
(264,'예루살렘 입성(종려주일)','신약','마태복음',40,'마 21:1-11',ARRAY['예수님','제자들','무리']::text[],'예수님이 나귀 새끼를 타고 예루살렘에 입성하시니 무리가 겉옷과 종려나무 가지를 길에 펴며 ''호산나 다윗의 자손이여'' 외쳤다.','겸손히 나귀를 타고 오신 왕의 모습은 세상 권력과는 다른 하나님 나라의 방식을 보여준다.',ARRAY['예수 그리스도의 정체성','겸손과 교만']::text[],'나는 겸손하게 임하시는 왕이신 예수님을 진심으로 환영하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/264'),
(265,'성전 청결','신약','마태복음',40,'마 21:12-17',ARRAY['예수님','장사꾼들','제사장들']::text[],'예수님이 성전에서 장사하는 자들의 상을 둘러엎으시며 ''내 집은 기도하는 집이라 하리라 하였거늘 너희는 강도의 소굴을 만들었도다'' 책망하셨다.','거룩해야 할 예배의 자리가 세속적 이익의 자리로 변질되지 않도록 늘 살펴야 한다.',ARRAY['예배와 경배','죄와 타락']::text[],'내 신앙생활에서 본질을 흐리는 세속적 요소는 없는지 점검해보자.',ARRAY['청소년','성인']::text[],'v1','/s/265'),
(266,'가이사에게 세금 바치는 문제','신약','마태복음',40,'마 22:15-22',ARRAY['예수님','바리새인들','헤롯당']::text[],'예수님을 함정에 빠뜨리려 세금 문제를 물은 이들에게 예수님은 ''가이사의 것은 가이사에게, 하나님의 것은 하나님께 바치라'' 하시며 지혜롭게 답하셨다.','세상 권위에 대한 책임과 하나님께 대한 온전한 헌신은 함께 지켜져야 할 균형이다.',ARRAY['지혜와 분별','순종과 믿음']::text[],'나는 세상의 책임과 하나님께 대한 헌신 사이에서 지혜롭게 균형을 잡고 있는가?',ARRAY['성인']::text[],'v1','/s/266'),
(267,'가장 큰 계명','신약','마태복음',40,'마 22:34-40',ARRAY['예수님','율법교사']::text[],'가장 큰 계명이 무엇이냐는 질문에 예수님은 마음과 목숨과 뜻을 다해 하나님을 사랑하고 네 이웃을 네 몸과 같이 사랑하라는 두 계명에 온 율법과 선지자의 강령이 있다 하셨다.','모든 신앙과 윤리의 핵심은 결국 하나님 사랑과 이웃 사랑이라는 두 축으로 귀결된다.',ARRAY['사랑과 섬김','율법과 계명']::text[],'나는 하나님 사랑과 이웃 사랑, 두 계명을 균형 있게 실천하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/267'),
(268,'과부의 두 렙돈','신약','마가복음',41,'막 12:41-44',ARRAY['가난한 과부','예수님','제자들']::text[],'부자들이 많은 돈을 헌금함에 넣는 중 가난한 과부가 두 렙돈을 넣자 예수님은 그가 생활비 전부를 드렸으니 누구보다 많이 넣었다 칭찬하셨다.','헌금의 가치는 액수가 아니라 드리는 이의 마음과 헌신의 정도로 평가된다.',ARRAY['사랑과 섬김','순종과 믿음']::text[],'나는 형편에 맞게, 그러나 진심을 다해 드리고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/268'),
(269,'감람산 강화(종말의 징조)','신약','마태복음',40,'마 24:1-51',ARRAY['예수님','제자들']::text[],'제자들이 세상 끝의 징조를 묻자 예수님은 전쟁과 기근, 거짓 선지자들의 출현 등을 말씀하시며 그 날과 그 때는 아버지만 아시니 항상 깨어 준비하라 당부하셨다.','종말의 때를 알려는 호기심보다 언제라도 주님을 맞을 준비된 삶이 더 중요하다.',ARRAY['종말과 소망','순종과 믿음']::text[],'나는 날짜를 궁금해하기보다 준비된 삶에 집중하고 있는가?',ARRAY['성인']::text[],'v1','/s/269'),
(270,'베다니에서 향유를 부음','신약','요한복음',43,'요 12:1-8',ARRAY['마리아','예수님','유다']::text[],'베다니에서 마리아가 매우 값진 향유를 예수님의 발에 붓고 자기 머리털로 닦으니 유다는 낭비라 비난했으나 예수님은 이것이 자신의 장례를 위한 것이라 말씀하셨다.','예수님을 향한 전적인 사랑의 헌신은 세상의 계산으로는 이해되지 않을 만큼 아낌없다.',ARRAY['사랑과 섬김','예배와 경배']::text[],'나는 예수님을 향해 계산하지 않는 헌신을 드린 적이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/270'),
(271,'최후의 만찬','신약','마태복음',40,'마 26:17-30',ARRAY['예수님','열두 제자']::text[],'유월절 만찬에서 예수님은 떡을 떼며 ''이것은 내 몸이니라'', 잔을 나누며 ''이것은 죄 사함을 얻게 하려고 많은 사람을 위하여 흘리는 바 나의 피 곧 언약의 피니라'' 말씀하시며 성찬을 제정하셨다.','성찬은 예수님의 희생을 기억하고 그 은혜에 참여하는 신앙 공동체의 거룩한 나눔이다.',ARRAY['하나님의 구원','예배와 경배']::text[],'나는 성찬에 참여할 때 예수님의 희생을 얼마나 깊이 기억하는가?',ARRAY['청소년','성인']::text[],'v1','/s/271'),
(272,'제자들의 발을 씻기심','신약','요한복음',43,'요 13:1-17',ARRAY['예수님','제자들','베드로']::text[],'만찬 중 예수님이 겉옷을 벗고 수건을 허리에 두르신 후 제자들의 발을 직접 씻기시며 서로 발을 씻어주라는 겸손한 섬김의 본을 보이셨다.','참된 리더십은 가장 낮은 자리에서 섬기는 겸손한 모습으로 나타난다.',ARRAY['겸손과 교만','사랑과 섬김']::text[],'나는 낮아짐으로 섬기는 예수님의 본을 삶에서 실천하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/272'),
(273,'겟세마네의 기도','신약','마태복음',40,'마 26:36-46',ARRAY['예수님','베드로','야고보','요한','하나님']::text[],'겟세마네 동산에서 예수님은 ''내 아버지여 만일 할 만하시거든 이 잔을 내게서 지나가게 하옵소서 그러나 나의 원대로 마시옵고 아버지의 원대로 하옵소서'' 땀이 핏방울같이 되도록 간절히 기도하셨다.','가장 힘든 순간에도 자신의 뜻보다 하나님의 뜻을 구하는 기도가 참된 순종의 모습이다.',ARRAY['기도와 응답','순종과 믿음']::text[],'나는 힘든 결정 앞에서 내 뜻과 하나님의 뜻 중 무엇을 먼저 구하는가?',ARRAY['청소년','성인']::text[],'v1','/s/273'),
(274,'배반과 체포','신약','마태복음',40,'마 26:47-56',ARRAY['예수님','유다','제자들','대제사장의 무리']::text[],'가룟 유다가 입맞춤으로 예수님을 표시하여 넘기고 무리가 예수님을 체포하려 하자, 베드로가 칼을 들었으나 예수님은 이를 막으시며 자신을 순순히 내어주셨다.','예수님은 힘으로 저항할 수 있었음에도 아버지의 뜻을 이루기 위해 스스로 고난을 받아들이셨다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 억울한 상황에서도 하나님의 큰 뜻을 신뢰하며 반응할 수 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/274'),
(275,'베드로의 부인','신약','마태복음',40,'마 26:69-75',ARRAY['베드로','예수님']::text[],'예수님이 잡히시자 세 번이나 예수님을 모른다고 부인했던 베드로는 닭이 울자 예수님의 말씀이 생각나 밖에 나가서 심히 통곡했다.','연약함으로 인한 실패 앞에서 통렬한 회개의 눈물은 새로운 회복의 시작이 된다.',ARRAY['회개와 용서','고난과 인내']::text[],'나는 나의 연약한 실패 앞에서 베드로처럼 정직하게 통곡하며 회개하는가?',ARRAY['청소년','성인']::text[],'v1','/s/275'),
(276,'산헤드린과 빌라도 앞에서의 재판','신약','마태복음',40,'마 26:57-27:26',ARRAY['예수님','대제사장','빌라도','무리']::text[],'대제사장 앞에서 신성모독으로 정죄된 예수님은 빌라도 앞에서도 아무 죄를 찾지 못했으나, 무리의 요구에 못 이긴 빌라도는 살인자 바라바를 놓아주고 예수님을 십자가에 넘겼다.','불의한 권력과 군중의 압박 앞에서도 진리이신 예수님은 침묵과 순종으로 그 길을 걸으셨다.',ARRAY['고난과 인내','순종과 믿음']::text[],'불의 앞에서 침묵하시던 예수님의 모습이 내게 주는 도전은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/276'),
(277,'십자가에 못박히심','신약','마태복음',40,'마 27:27-44',ARRAY['예수님','군인들','강도 둘','지나가는 자들']::text[],'군인들에게 희롱과 채찍질을 당하신 예수님은 골고다로 끌려가 두 강도 사이에서 십자가에 못박히셨고, 지나가는 자들은 그를 조롱했다.','가장 처참한 수치와 고통 속에서도 예수님은 우리를 위한 구원의 길을 묵묵히 걸어가셨다.',ARRAY['하나님의 구원','고난과 인내']::text[],'십자가의 고통이 나를 위한 것이었음을 어떻게 깊이 묵상할 수 있을까?',ARRAY['청소년','성인']::text[],'v1','/s/277'),
(278,'십자가 위의 강도','신약','누가복음',42,'눅 23:39-43',ARRAY['예수님','두 강도']::text[],'함께 못박힌 두 강도 중 한 사람은 예수님을 조롱했으나 다른 한 사람은 자신의 죄를 인정하며 ''당신의 나라에 임하실 때에 나를 기억하소서'' 구하니 예수님은 오늘 낙원에 함께 있으리라 약속하셨다.','죽음 직전의 마지막 순간에라도 진실한 믿음은 구원의 은혜를 얻는다.',ARRAY['하나님의 구원','회개와 용서']::text[],'구원은 언제라도 진실한 믿음으로 얻을 수 있다는 사실이 내게 주는 위로는 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/278'),
(279,'예수님의 죽으심','신약','마태복음',40,'마 27:45-56',ARRAY['예수님','백부장','구경하는 무리']::text[],'정오부터 어둠이 임한 후 예수님이 ''엘리 엘리 라마 사박다니'' 외치시고 큰 소리로 운명하시니 성소 휘장이 위로부터 아래까지 찢어지고 백부장은 ''이는 진실로 하나님의 아들이었도다'' 고백했다.','예수님의 죽으심으로 하나님과 사람 사이를 가로막던 휘장이 찢어지고 나아갈 길이 열렸다.',ARRAY['하나님의 구원','예수 그리스도의 정체성']::text[],'휘장이 찢어짐으로 열린 하나님께 나아가는 길을 나는 얼마나 자유롭게 누리고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/279'),
(280,'장사되심','신약','마태복음',40,'마 27:57-66',ARRAY['아리마대 요셉','예수님','경비병들']::text[],'부자 요셉이 자신의 새 무덤에 예수님의 시신을 모시고 큰 돌로 입구를 막았으며, 대제사장들은 경비병을 세워 무덤을 지키게 했다.','십자가 이후의 침묵의 시간에도 하나님의 계획은 한 치의 오차 없이 진행되고 있었다.',ARRAY['하나님의 섭리','고난과 인내']::text[],'응답이 보이지 않는 침묵의 시간에도 나는 하나님의 일하심을 신뢰하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/280'),
(281,'부활','신약','마태복음',40,'마 28:1-10',ARRAY['마리아','막달라 마리아','천사','예수님']::text[],'안식 후 첫날 무덤을 찾은 여인들에게 천사가 예수님이 살아나셨음을 알렸고, 부활하신 예수님이 친히 그들에게 나타나셨다.','십자가의 죽음은 끝이 아니라 죽음을 이기신 부활의 승리로 완성되었다.',ARRAY['예수 그리스도의 정체성','하나님의 구원']::text[],'부활의 소망이 오늘 내 삶에 어떤 힘을 주고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/281'),
(282,'엠마오로 가는 두 제자','신약','누가복음',42,'눅 24:13-35',ARRAY['글로바','다른 제자','부활하신 예수님']::text[],'엠마오로 가던 두 제자가 부활하신 예수님과 동행하면서도 알아보지 못하다가, 떡을 떼실 때 눈이 밝아져 그분을 알아보고 마음이 뜨거웠음을 고백했다.','낙심한 마음 가운데서도 말씀을 풀어주시는 예수님과의 동행은 뜨거운 확신과 회복을 가져온다.',ARRAY['순종과 믿음','인도하심과 보호']::text[],'실망과 낙심 속에서 나는 예수님의 동행을 어떻게 알아차릴 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/282'),
(283,'도마의 의심과 확신','신약','요한복음',43,'요 20:19-29',ARRAY['도마','부활하신 예수님','제자들']::text[],'부활하신 예수님을 처음에 보지 못해 의심했던 도마가 다시 나타나신 예수님의 못자국을 보고 ''나의 주님이시요 나의 하나님이시니이다'' 고백하니, 예수님은 보지 않고 믿는 자가 복되다 하셨다.','의심하는 마음도 정직하게 주님 앞에 가져올 때 더 깊은 확신의 믿음으로 자라날 수 있다.',ARRAY['순종과 믿음','예수 그리스도의 정체성']::text[],'나는 신앙의 의심을 정직하게 주님 앞에 가져와 본 적이 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/283'),
(284,'디베랴 바닷가에서 베드로가 회복됨','신약','요한복음',43,'요 21:1-19',ARRAY['베드로','예수님','제자들']::text[],'고기잡이를 나갔던 제자들에게 부활하신 예수님이 나타나 조반을 주시고, 세 번 부인했던 베드로에게 세 번 ''네가 나를 사랑하느냐'' 물으시며 ''내 양을 먹이라''는 사명을 다시 맡기셨다.','실패한 자리라도 예수님은 다시 찾아오셔서 사랑을 확인하고 새로운 사명으로 회복시키신다.',ARRAY['회개와 용서','사랑과 섬김']::text[],'나는 실패 이후에도 예수님이 다시 부르시는 사명을 신뢰하는가?',ARRAY['청소년','성인']::text[],'v1','/s/284'),
(285,'지상명령(대사명)','신약','마태복음',40,'마 28:16-20',ARRAY['예수님','열한 제자']::text[],'부활하신 예수님이 갈릴리 산에서 제자들에게 모든 민족을 제자로 삼아 세례를 주고 자신이 분부한 모든 것을 가르쳐 지키게 하라 명하시며 세상 끝날까지 함께하겠다 약속하셨다.','교회의 사명은 모든 민족에게 복음을 전하는 것이며, 그 사명의 자리에 예수님이 늘 함께하신다.',ARRAY['전도와 선교','하나님의 언약']::text[],'나는 지상명령을 내 삶의 구체적인 사명으로 받아들이고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/285'),
(286,'승천','신약','누가복음',42,'눅 24:50-53',ARRAY['예수님','제자들']::text[],'예수님이 제자들을 데리고 베다니 앞까지 나가 손을 들어 축복하시며 하늘로 올려지시니 제자들은 큰 기쁨으로 예루살렘에 돌아가 하나님을 찬송하였다.','예수님의 승천은 이별이 아니라 하늘 보좌에서 우리를 위해 일하시며 다시 오실 것을 준비하시는 소망이다.',ARRAY['종말과 소망','예배와 경배']::text[],'예수님의 재림을 기다리며 나는 오늘 어떤 소망으로 살아가는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/286'),
(287,'다락방에서의 기도와 맛디아 선택','신약','사도행전',44,'행 1:12-26',ARRAY['제자들','맛디아','맛디아','유다']::text[],'승천하신 예수님의 명령대로 예루살렘에 모인 제자들이 마음을 같이하여 오로지 기도에 힘썼고, 유다를 대신할 사도로 맛디아를 세웠다.','성령을 기다리는 시간은 조급함이 아니라 한마음으로 기도하는 준비의 시간이어야 한다.',ARRAY['기도와 응답','교회와 공동체']::text[],'나는 응답을 기다리는 시간을 어떤 태도로 채우고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/287'),
(288,'오순절 성령강림','신약','사도행전',44,'행 2:1-13',ARRAY['제자들','성령','예루살렘의 여러 민족']::text[],'오순절 날 다락방에 모인 제자들에게 성령이 불의 혀같이 임하시고, 각 나라 방언으로 하나님의 큰 일을 말하기 시작했다.','성령은 교회를 세우시고 복음이 모든 민족에게 전해지게 하시는 능력의 근원이다.',ARRAY['성령의 역사','전도와 선교']::text[],'성령께서 내 삶과 공동체 가운데 일하고 계심을 어디에서 발견하는가?',ARRAY['청소년','성인']::text[],'v1','/s/288'),
(289,'베드로의 설교와 초대교회의 시작','신약','사도행전',44,'행 2:14-41',ARRAY['베드로','무리']::text[],'베드로가 예수 그리스도의 십자가와 부활을 담대히 증언하니 많은 사람들이 마음에 찔려 회개했고, 그 날에 세례받은 사람이 삼천 명이나 더해졌다.','성령의 능력으로 전해진 복음은 마음을 찔러 회개와 놀라운 부흥으로 이어진다.',ARRAY['전도와 선교','성령의 역사']::text[],'나는 성령의 능력을 의지하며 복음을 담대히 전하고 있는가?',ARRAY['청소년','성인']::text[],'v1','/s/289'),
(290,'초대교회의 공동체 생활','신약','사도행전',44,'행 2:42-47',ARRAY['초대교회 성도들']::text[],'초대교회 성도들은 사도의 가르침과 서로 교제하며 떡을 떼고 기도하기를 힘썼고, 재산과 소유를 통용하며 날마다 기쁨과 순전한 마음으로 함께했다.','말씀과 교제, 나눔이 살아있는 공동체는 세상에 큰 감동과 매력을 준다.',ARRAY['교회와 공동체','사랑과 섬김']::text[],'우리 신앙공동체는 말씀과 교제, 나눔이 얼마나 살아있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/290'),
(291,'성전 미문의 앉은뱅이를 고침','신약','사도행전',44,'행 3:1-10',ARRAY['베드로','요한','앉은뱅이']::text[],'성전 미문에서 구걸하던 나면서부터 앉은뱅이 된 사람에게 베드로가 ''은과 금은 내게 없으나 내게 있는 것으로 네게 주노니 나사렛 예수 그리스도의 이름으로 걸으라'' 하니 즉시 일어나 걸었다.','우리가 가진 것이 세상의 부요함이 아니어도, 예수님의 이름에는 참된 회복의 능력이 있다.',ARRAY['예수님의 기적','전도와 선교']::text[],'나는 내게 있는 것, 곧 예수 그리스도의 이름을 담대히 나누고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/291'),
(292,'아나니아와 삽비라','신약','사도행전',44,'행 5:1-11',ARRAY['아나니아','삽비라','베드로']::text[],'자원한 것처럼 보이려 재산의 일부를 감추고 전부인 것처럼 속인 아나니아와 삽비라 부부가 성령을 속인 죄로 그 자리에서 죽으니 온 교회가 크게 두려워했다.','하나님과 공동체 앞에서의 정직함은 신앙생활의 근본이며, 형식적 신앙의 위선은 엄중히 다뤄진다.',ARRAY['죄와 타락','충성과 신실함']::text[],'나는 신앙공동체 안에서 실제보다 더 좋게 보이려 꾸민 적은 없는가?',ARRAY['성인']::text[],'v1','/s/292'),
(293,'일곱 집사를 세움','신약','사도행전',44,'행 6:1-7',ARRAY['스데반','빌립','열두 사도','성도들']::text[],'구제 분배 과정에서 불만이 생기자 사도들은 말씀과 기도에 전념하고 성령과 지혜가 충만한 일곱 사람을 세워 구제의 일을 맡기니 교회가 더욱 부흥했다.','은사와 역할을 지혜롭게 나누어 섬길 때 공동체는 갈등을 넘어 더 건강하게 성장한다.',ARRAY['교회와 공동체','지도자의 리더십']::text[],'우리 공동체는 각자의 은사를 따라 역할을 잘 나누어 섬기고 있는가?',ARRAY['성인']::text[],'v1','/s/293'),
(294,'스데반의 순교','신약','사도행전',44,'행 6:8-7:60',ARRAY['스데반','공회','사울']::text[],'지혜와 성령이 충만했던 스데반이 공회 앞에서 담대히 복음을 증언하다 돌에 맞아 죽으며 ''이 죄를 그들에게 돌리지 마옵소서'' 기도했고, 그 자리에 사울이 있었다.','순교의 자리에서도 원수를 용서하는 사랑은 복음의 능력을 가장 생생하게 증언한다.',ARRAY['고난과 인내','회개와 용서']::text[],'박해나 어려움 속에서도 용서를 실천한 스데반의 모습이 내게 주는 도전은 무엇인가?',ARRAY['청소년','성인']::text[],'v1','/s/294'),
(295,'빌립과 에디오피아 내시','신약','사도행전',44,'행 8:26-40',ARRAY['빌립','에디오피아 내시']::text[],'성령의 인도로 광야 길에서 이사야서를 읽던 에디오피아 내시를 만난 빌립이 복음을 전하니 내시가 즉시 세례를 받고 기쁘게 길을 갔다.','성령의 인도하심을 따라 순종하면 한 사람의 인생을 변화시키는 만남으로 이어질 수 있다.',ARRAY['전도와 선교','성령의 역사']::text[],'나는 성령의 인도하심에 즉각 순종하여 누군가에게 복음을 전한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/295'),
(296,'사울의 다메섹 도상 회심','신약','사도행전',44,'행 9:1-19',ARRAY['사울','아나니아','예수님']::text[],'그리스도인들을 핍박하러 다메섹으로 가던 사울이 빛 가운데 부활하신 예수님을 만나 눈이 멀었다가, 아나니아의 안수로 다시 보게 되며 복음 전파자로 완전히 변화되었다.','가장 강력하게 복음을 대적하던 사람도 예수님을 만나면 가장 열정적인 전도자로 변화될 수 있다.',ARRAY['전도와 선교','하나님의 섭리']::text[],'나는 변화될 수 없다고 여겼던 사람의 회심 가능성을 믿고 기도하는가?',ARRAY['청소년','성인']::text[],'v1','/s/296'),
(297,'베드로와 고넬료','신약','사도행전',44,'행 10:1-48',ARRAY['베드로','고넬료','성령']::text[],'이방인 백부장 고넬료의 환상과 베드로의 환상이 맞닿아 베드로가 그의 집에 가서 복음을 전하니 성령이 이방인들에게도 임하시어 복음이 유대인을 넘어 확장되었다.','복음은 어떤 민족이나 배경의 제한도 없이 모든 사람에게 열려 있는 하나님의 은혜이다.',ARRAY['전도와 선교','하나님의 사랑']::text[],'나는 복음을 전할 때 어떤 편견이나 제한을 두고 있지는 않은가?',ARRAY['청소년','성인']::text[],'v1','/s/297'),
(298,'안디옥 교회의 시작','신약','사도행전',44,'행 11:19-30',ARRAY['바나바','사울','안디옥 성도들']::text[],'박해로 흩어진 성도들이 안디옥에서 이방인들에게도 복음을 전하니 큰 무리가 믿었고, 바나바가 사울을 데려와 함께 가르치며 그리스도인이라는 이름이 여기서 처음 생겼다.','박해와 흩어짐도 하나님의 손 안에서는 오히려 복음이 더 넓게 확장되는 통로가 된다.',ARRAY['전도와 선교','교회와 공동체']::text[],'내 삶의 어려움이 오히려 복음의 확장으로 쓰임받을 수 있음을 믿는가?',ARRAY['청소년','성인']::text[],'v1','/s/298'),
(299,'베드로가 옥에서 기적적으로 풀려남','신약','사도행전',44,'행 12:1-19',ARRAY['베드로','천사','교회 성도들']::text[],'헤롯에게 갇혀 처형을 기다리던 베드로를 위해 교회가 간절히 기도하니 천사가 나타나 쇠사슬을 풀고 옥문을 열어 그를 구출했다.','간절한 중보기도는 인간의 힘으로 불가능한 상황도 뒤집는 하나님의 능력을 이끌어낸다.',ARRAY['기도와 응답','인도하심과 보호']::text[],'나는 어려움에 처한 누군가를 위해 얼마나 간절히 중보기도 하는가?',ARRAY['어린이','청소년','성인']::text[],'v1','/s/299'),
(300,'바울의 첫 선교여행 시작','신약','사도행전',44,'행 13:1-52',ARRAY['바울','바나바','서기오 바울','비시디아 안디옥 사람들']::text[],'안디옥 교회의 파송을 받은 바울과 바나바가 구브로를 거쳐 비시디아 안디옥에서 복음을 전하니 많은 이방인이 기뻐하며 믿었으나 유대인들의 반대도 거세졌다.','교회의 파송과 선교는 기쁨의 열매와 함께 반대와 어려움도 동반하는 여정이다.',ARRAY['전도와 선교','고난과 인내']::text[],'나는 복음을 전할 때 따르는 반대와 어려움도 감수할 각오가 있는가?',ARRAY['성인']::text[],'v2','/s/300'),
(301,'루스드라에서 돌에 맞음','신약','사도행전',44,'행 14:8-20',ARRAY['바울','바나바','루스드라 사람들']::text[],'루스드라에서 앉은뱅이를 고친 바울과 바나바를 신으로 여기던 무리가 선동에 의해 돌변하여 바울을 돌로 쳐 죽은 줄 알고 버렸으나, 바울은 다시 일어나 사역을 계속했다.','극심한 박해와 고난 속에서도 사명을 향한 신실함은 결코 꺾이지 않는다.',ARRAY['고난과 인내','충성과 신실함']::text[],'나는 극심한 어려움 속에서도 맡겨진 사명을 포기하지 않을 수 있는가?',ARRAY['성인']::text[],'v2','/s/301'),
(302,'예루살렘 공의회','신약','사도행전',44,'행 15:1-35',ARRAY['바울','바나바','베드로','야고보','예루살렘 교회']::text[],'이방인 신자에게 할례가 필요한지를 두고 논쟁이 일자 예루살렘에 모인 지도자들은 믿음으로 구원받음을 확인하고 이방인에게 불필요한 짐을 지우지 않기로 결정했다.','교회는 갈등이 생길 때 함께 모여 말씀과 성령 안에서 지혜로운 결론을 찾아가야 한다.',ARRAY['교회와 공동체','지혜와 분별']::text[],'우리 공동체는 의견 차이가 있을 때 어떻게 함께 지혜를 모으는가?',ARRAY['성인']::text[],'v2','/s/302'),
(303,'마게도냐 환상과 루디아의 회심','신약','사도행전',44,'행 16:6-15',ARRAY['바울','루디아','실라']::text[],'아시아 전도를 막으신 성령의 인도로 바울이 마게도냐 사람의 환상을 보고 빌립보로 건너가 자주 장사 루디아를 만나 전도하니 그와 온 집이 세례를 받았다.','때로 하나님은 계획한 길을 막으시고 예상치 못한 방향으로 우리를 인도하신다.',ARRAY['인도하심과 보호','전도와 선교']::text[],'계획이 막혔을 때 나는 하나님의 새로운 인도하심을 신뢰하는가?',ARRAY['청소년','성인']::text[],'v2','/s/303'),
(304,'빌립보 감옥의 바울과 실라','신약','사도행전',44,'행 16:16-40',ARRAY['바울','실라','빌립보 간수']::text[],'매를 맞고 갇힌 바울과 실라가 한밤중 감옥에서 기도하며 찬송하니 갑자기 큰 지진이 나 옥문이 열렸고, 자결하려던 간수는 회심하여 온 가족이 세례를 받았다.','가장 어두운 고난의 자리에서 드리는 찬양은 뜻밖의 사람을 구원으로 이끄는 통로가 된다.',ARRAY['예배와 경배','전도와 선교']::text[],'고난 중에도 찬양할 수 있는 믿음이 내게 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/304'),
(305,'아덴에서 아레오바고 설교','신약','사도행전',44,'행 17:16-34',ARRAY['바울','아덴 사람들']::text[],'우상이 가득한 아덴에서 바울은 ''알지 못하는 신에게''라는 제단을 언급하며 참되신 하나님을 아레오바고 철학자들에게 지혜롭게 소개했다.','복음을 전할 때 상대방의 문화와 상황을 이해하고 접촉점을 찾는 지혜가 필요하다.',ARRAY['전도와 선교','지혜와 분별']::text[],'나는 상대방의 상황에 맞게 지혜롭게 복음을 전하고 있는가?',ARRAY['성인']::text[],'v2','/s/305'),
(306,'에베소에서의 사역과 소요','신약','사도행전',44,'행 19:1-20,23-41',ARRAY['바울','아데미 여신 숭배자들','데메드리오']::text[],'에베소에서 바울의 사역으로 많은 사람이 회심하고 마술책을 불태우는 등 큰 부흥이 일어나자, 은장색 데메드리오는 우상 장사가 위협받는다며 소요를 일으켰다.','참된 복음의 부흥은 때로 기존 질서와 이익 구조에 불편함을 주며 저항을 불러올 수 있다.',ARRAY['전도와 선교','고난과 인내']::text[],'복음으로 인한 삶의 변화가 주변에 불편함을 줄 때 나는 어떻게 반응하는가?',ARRAY['성인']::text[],'v2','/s/306'),
(307,'에베소 장로들과의 고별설교','신약','사도행전',44,'행 20:17-38',ARRAY['바울','에베소 장로들']::text[],'예루살렘으로 향하던 바울이 밀레도에서 에베소 장로들을 불러 자신이 달려갈 길과 복음 전하는 직무를 마치기까지 생명을 조금도 귀히 여기지 않겠다는 각오를 전하며 눈물로 작별했다.','사명을 향한 순전한 헌신은 죽음의 위협 앞에서도 물러서지 않는 담대함으로 나타난다.',ARRAY['충성과 신실함','고난과 인내']::text[],'나는 내게 맡겨진 사명을 ''달려갈 길''로 여기며 끝까지 완주할 각오가 있는가?',ARRAY['성인']::text[],'v2','/s/307'),
(308,'바울이 예루살렘에서 체포됨','신약','사도행전',44,'행 21:27-36',ARRAY['바울','유대인들','로마 군대']::text[],'예루살렘 성전에서 유대인들이 바울을 죽이려 소동을 일으키자 로마 천부장이 그를 구출하여 체포하니 이후 여러 재판 과정이 시작되었다.','복음을 위한 헌신의 길에는 예상치 못한 박해와 억울한 고난이 따를 수 있다.',ARRAY['고난과 인내','충성과 신실함']::text[],'억울한 고난 속에서도 나는 하나님의 더 큰 계획을 신뢰할 수 있는가?',ARRAY['성인']::text[],'v2','/s/308'),
(309,'벨릭스, 베스도, 아그립바 앞에서의 변론','신약','사도행전',44,'행 24:1-26:32',ARRAY['바울','벨릭스','베스도','아그립바 왕']::text[],'여러 총독과 왕 앞에서 재판받던 바울은 두려워하지 않고 자신의 회심과 복음을 담대히 증언하니 아그립바 왕조차 ''네가 나를 권하여 그리스도인이 되게 하려 하는도다'' 반응했다.','권력자 앞에서도 두려워하지 않고 복음을 증언하는 담대함은 진리를 향한 확신에서 나온다.',ARRAY['용기와 결단','전도와 선교']::text[],'나는 권위 있는 사람 앞에서도 신앙을 담대히 증언할 수 있는가?',ARRAY['성인']::text[],'v2','/s/309'),
(310,'로마로 가는 항해 중 풍랑과 파선','신약','사도행전',44,'행 27:1-44',ARRAY['바울','백부장 율리오','선원들']::text[],'로마로 압송되던 중 큰 풍랑을 만나 배가 파선될 위기에서 바울은 천사의 말을 전하며 한 사람도 생명을 잃지 않을 것이라 담대히 선포했고 그대로 이루어졌다.','극한의 위기 속에서도 하나님을 향한 믿음의 사람은 주변 사람들에게 평안과 소망을 전할 수 있다.',ARRAY['순종과 믿음','인도하심과 보호']::text[],'위기 상황에서 나는 주변 사람들에게 평안과 소망을 전하는 존재인가?',ARRAY['청소년','성인']::text[],'v2','/s/310'),
(311,'바울이 로마에서 담대히 복음을 전함','신약','사도행전',44,'행 28:16-31',ARRAY['바울','로마의 유대인들']::text[],'가택연금 중에도 바울은 찾아오는 이들에게 거리낌없이 하나님 나라를 전파하고 예수 그리스도에 관한 것을 가르치며 사도행전은 마무리된다.','제한된 환경 속에서도 복음을 전하려는 열정은 결코 갇히지 않는다.',ARRAY['전도와 선교','고난과 인내']::text[],'나는 제한된 상황 속에서도 복음을 전할 방법을 찾고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/311'),
(312,'복음은 하나님의 능력, 믿음으로 말미암은 의','신약','로마서',45,'롬 1:16-17',ARRAY['바울']::text[],'바울은 복음을 부끄러워하지 않는다 선언하며 이는 모든 믿는 자에게 구원을 주시는 하나님의 능력이요 그 안에 하나님의 의가 나타나 오직 믿음으로 살리라 선포했다.','복음은 사람의 지혜가 아니라 믿는 모든 자를 구원하는 하나님의 실제적인 능력이다.',ARRAY['하나님의 구원','순종과 믿음']::text[],'나는 복음을 부끄러워하지 않고 담대히 여기고 있는가?',ARRAY['성인']::text[],'v2','/s/312'),
(313,'믿음으로 의롭다 하심(이신칭의)','신약','로마서',45,'롬 3:21-26',ARRAY['바울']::text[],'바울은 율법과 상관없이 예수 그리스도를 믿음으로 말미암아 모든 믿는 자에게 차별 없이 하나님의 의가 나타났다고 설명하며 이는 값없이 은혜로 주어지는 선물이라 가르쳤다.','구원은 우리의 행위나 자격이 아니라 오직 그리스도를 믿는 믿음을 통해 값없이 주어지는 은혜이다.',ARRAY['하나님의 구원','순종과 믿음']::text[],'나는 구원을 내 행위가 아닌 은혜로 받아들이고 있는가?',ARRAY['성인']::text[],'v2','/s/313'),
(314,'하나님과의 화평, 그리스도의 사랑','신약','로마서',45,'롬 5:1-11',ARRAY['바울']::text[],'바울은 믿음으로 의롭다 하심을 받은 우리가 하나님과 화평을 누리며, 우리가 아직 죄인 되었을 때 그리스도께서 우리를 위해 죽으심으로 하나님의 사랑이 확증되었다고 선포했다.','우리가 가장 연약하고 죄 많을 때조차 그리스도는 우리를 위해 희생하셨으니 그 사랑은 조건 없는 사랑이다.',ARRAY['하나님의 사랑','하나님의 구원']::text[],'조건 없는 그리스도의 사랑이 내 삶에 어떤 확신을 주는가?',ARRAY['성인']::text[],'v2','/s/314'),
(315,'성령 안의 생명과 승리(정죄함이 없나니)','신약','로마서',45,'롬 8:1-39',ARRAY['바울']::text[],'바울은 그리스도 예수 안에 있는 자에게는 결코 정죄함이 없으며, 어떤 환난이나 능력도 그리스도 안에 있는 하나님의 사랑에서 우리를 끊을 수 없다고 선언했다.','성령 안에 있는 그리스도인은 어떤 상황 속에서도 하나님의 사랑에서 끊어지지 않는다는 확고한 안전함을 누린다.',ARRAY['성령의 역사','하나님의 사랑']::text[],'환난 속에서도 나는 하나님의 사랑에서 끊어지지 않는다는 확신이 있는가?',ARRAY['성인']::text[],'v2','/s/315'),
(316,'산 제물로 드리는 신앙','신약','로마서',45,'롬 12:1-2',ARRAY['바울']::text[],'바울은 형제들에게 하나님의 자비하심으로 그 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리고 마음을 새롭게 함으로 변화를 받아 하나님의 뜻을 분별하라 권면했다.','참된 예배는 특정 시간과 장소를 넘어 삶 전체를 하나님께 드리는 헌신으로 나타난다.',ARRAY['예배와 경배','순종과 믿음']::text[],'나는 내 삶 전체를 하나님께 드리는 산 제물로 여기고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/316'),
(317,'그리스도의 몸(지체의 비유)','신약','고린도전서',46,'고전 12:12-31',ARRAY['바울','고린도 교회']::text[],'바울은 몸이 여러 지체로 이루어져 있으나 하나 인 것처럼 교회도 각기 다른 은사를 가진 지체들이 하나의 몸을 이루며 서로를 필요로 한다고 가르쳤다.','교회 공동체는 서로 다른 은사와 역할이 존중되며 함께 어우러질 때 온전한 그리스도의 몸을 이룬다.',ARRAY['교회와 공동체','사랑과 섬김']::text[],'나는 공동체 안에서 나와 다른 은사를 가진 지체를 얼마나 존중하는가?',ARRAY['성인']::text[],'v2','/s/317'),
(318,'사랑장','신약','고린도전서',46,'고전 13:1-13',ARRAY['바울']::text[],'바울은 사람의 방언과 천사의 말을 할지라도 사랑이 없으면 소용없다며, 사랑은 오래 참고 온유하며 자랑하지 않고 모든 것을 견디는 것이라 노래하며 그중 제일은 사랑이라 결론지었다.','아무리 뛰어난 은사와 지식이 있어도 사랑이 없다면 아무 유익이 없으니, 사랑이야말로 신앙의 본질이다.',ARRAY['사랑과 섬김']::text[],'사랑장의 특징들 중 내게 가장 부족한 부분은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/318'),
(319,'부활장','신약','고린도전서',46,'고전 15:1-58',ARRAY['바울']::text[],'바울은 그리스도의 부활이 복음의 핵심임을 강조하며 그리스도 안에서 모든 사람이 삶을 얻고 마지막 나팔에 죽은 자들이 썩지 않을 것으로 다시 살아날 것이라 선포하며 ''사망아 너의 승리가 어디 있느냐'' 외쳤다.','그리스도의 부활은 우리 믿음의 근거이며, 우리에게도 죽음을 이기는 부활의 소망을 준다.',ARRAY['종말과 소망','예수 그리스도의 정체성']::text[],'부활의 소망이 오늘 나의 죽음에 대한 두려움을 어떻게 바꾸는가?',ARRAY['청소년','성인']::text[],'v2','/s/319'),
(320,'새로운 피조물과 화목하게 하는 직분','신약','고린도후서',47,'고후 5:17-21',ARRAY['바울']::text[],'바울은 누구든지 그리스도 안에 있으면 새로운 피조물이라 선언하며, 하나님이 그리스도를 통해 우리를 자신과 화목하게 하시고 우리에게도 화목하게 하는 직분을 맡기셨다고 가르쳤다.','그리스도 안에서 새로워진 우리는 이제 세상과 하나님을 화목하게 하는 사명을 감당해야 한다.',ARRAY['하나님의 구원','전도와 선교']::text[],'나는 그리스도 안에서 새로운 피조물 된 것을 삶으로 나타내고 있는가?',ARRAY['성인']::text[],'v2','/s/320'),
(321,'바울의 약함 속의 강함','신약','고린도후서',47,'고후 12:1-10',ARRAY['바울','하나님']::text[],'육체의 가시를 없애달라 세 번 간구한 바울에게 하나님은 ''내 은혜가 네게 족하도다 이는 내 능력이 약한 데서 온전하여짐이라'' 답하시니 바울은 오히려 약한 것들을 자랑하겠다 고백했다.','우리의 약함은 감추어야 할 것이 아니라 하나님의 능력이 온전히 드러나는 통로가 될 수 있다.',ARRAY['고난과 인내','겸손과 교만']::text[],'나는 내 약함을 통해 드러나는 하나님의 능력을 경험한 적이 있는가?',ARRAY['성인']::text[],'v2','/s/321'),
(322,'바울이 베드로를 책망함','신약','갈라디아서',48,'갈 2:11-21',ARRAY['바울','베드로']::text[],'이방인과 함께 식사하던 베드로가 할례파 사람들을 두려워하여 물러나자 바울은 그의 행위가 복음의 진리를 따르지 않는다며 공개적으로 책망하고 이신칭의의 진리를 분명히 했다.','지도자라도 복음의 진리에서 벗어나면 담대히 바로잡아야 하며, 사람을 두려워해 진리를 타협해서는 안 된다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 사람의 눈치 때문에 복음의 진리를 타협한 적이 없는가?',ARRAY['성인']::text[],'v2','/s/322'),
(323,'성령의 열매','신약','갈라디아서',48,'갈 5:16-26',ARRAY['바울']::text[],'바울은 육체의 소욕과 성령의 소욕이 서로 대적한다 말하며 성령을 따라 행하면 사랑과 희락, 화평, 오래 참음, 자비, 양선, 충성, 온유, 절제의 열매를 맺는다고 가르쳤다.','성령을 따라 사는 삶은 억지로 애쓰는 것이 아니라 자연스럽게 아름다운 인격의 열매로 나타난다.',ARRAY['성령의 역사','지혜와 분별']::text[],'성령의 아홉 가지 열매 중 오늘 내게 가장 필요한 것은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/323'),
(324,'은혜로 구원받음','신약','에베소서',49,'엡 2:1-10',ARRAY['바울']::text[],'바울은 허물과 죄로 죽었던 우리를 하나님이 긍휼이 풍성하심으로 살리셨으니 이는 행위에서 난 것이 아니요 하나님의 선물인 은혜로 구원받은 것이라 가르쳤다.','구원은 우리의 노력이나 자격에서 시작된 것이 아니라 전적으로 하나님의 선물인 은혜에서 비롯된다.',ARRAY['하나님의 구원','겸손과 교만']::text[],'나는 구원을 나의 자랑이 아닌 하나님의 선물로 겸손히 받아들이고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/324'),
(325,'그리스도의 몸을 세우는 은사들','신약','에베소서',49,'엡 4:1-16',ARRAY['바울']::text[],'바울은 성도들에게 부르심에 합당하게 겸손과 온유로 서로를 대하며 하나 됨을 힘쓰라 권면하고, 그리스도께서 주신 다양한 은사로 성도를 온전하게 하여 그리스도의 몸을 세우게 하셨다고 가르쳤다.','교회는 다양한 은사가 조화를 이루어 함께 성숙해가며 그리스도의 몸으로 세워지는 공동체이다.',ARRAY['교회와 공동체','사랑과 섬김']::text[],'나는 공동체의 하나 됨과 성숙을 위해 어떤 은사로 기여하고 있는가?',ARRAY['성인']::text[],'v2','/s/325'),
(326,'하나님의 전신갑주','신약','에베소서',49,'엡 6:10-20',ARRAY['바울']::text[],'바울은 성도들에게 마귀의 간계를 대적하기 위해 진리의 허리띠, 의의 흉배, 평안의 복음의 신, 믿음의 방패, 구원의 투구, 성령의 검인 하나님의 말씀으로 전신갑주를 입으라 권면했다.','영적 싸움에서 승리하려면 세상의 무기가 아니라 하나님이 주신 영적 무장이 필요하다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 영적 싸움을 위해 하나님의 전신갑주를 매일 갖추고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/326'),
(327,'그리스도의 겸손(케노시스 찬가)','신약','빌립보서',50,'빌 2:1-11',ARRAY['바울','예수 그리스도']::text[],'바울은 그리스도께서 하나님과 동등됨을 취하지 않으시고 오히려 자기를 비워 종의 형체를 가지사 십자가에 죽기까지 복종하셨다며 이 마음을 품으라 권면했다.','참된 겸손은 자신의 권리와 지위를 내려놓고 낮아짐을 선택하는 그리스도의 마음을 본받는 것이다.',ARRAY['겸손과 교만','예수 그리스도의 정체성']::text[],'나는 그리스도처럼 나 자신을 비우고 낮아지는 마음을 품고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/327'),
(328,'항상 기뻐하라, 자족하는 비결','신약','빌립보서',50,'빌 4:4-13',ARRAY['바울']::text[],'옥에 갇힌 중에도 바울은 주 안에서 항상 기뻐하라 권면하며 아무 것도 염려하지 말고 기도와 간구로 감사함으로 구하라 하고, 자신은 어떤 형편에든지 자족하기를 배웠다고 고백했다.','환경에 좌우되지 않는 기쁨과 자족은 그리스도 안에서 배우고 훈련되는 신앙의 성숙이다.',ARRAY['고난과 인내','예배와 경배']::text[],'나는 환경과 상관없이 자족하며 기뻐하는 법을 배워가고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/328'),
(329,'그리스도의 우월하심','신약','골로새서',51,'골 1:15-20',ARRAY['바울','예수 그리스도']::text[],'바울은 그리스도가 보이지 아니하는 하나님의 형상이시요 모든 피조물보다 먼저 나신 이로서 만물이 그로 말미암고 그를 위하여 창조되었으며 그 안에서 통일된다고 선포했다.','그리스도는 창조와 구속의 중심이시며 만물보다 뛰어나신 온 우주의 주권자이시다.',ARRAY['예수 그리스도의 정체성','창조와 섭리']::text[],'그리스도의 우주적 주권이 오늘 내 삶의 작은 부분에까지 미친다는 것을 믿는가?',ARRAY['성인']::text[],'v2','/s/329'),
(330,'위엣 것을 찾으라(새 사람을 입으라)','신약','골로새서',51,'골 3:1-17',ARRAY['바울']::text[],'바울은 그리스도와 함께 다시 살리심을 받았으니 위엣 것을 찾고 땅의 것을 생각하지 말라 권면하며 옛 사람을 벗어버리고 긍휼과 자비, 겸손, 온유, 인내로 새 사람을 입으라 가르쳤다.','그리스도 안에서 새로워진 정체성은 구체적인 성품의 변화로 옷 입듯 나타나야 한다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나는 옛 사람의 습관을 벗고 새 사람의 성품을 얼마나 입어가고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/330'),
(331,'주님의 재림과 부활의 소망','신약','데살로니가전서',52,'살전 4:13-18',ARRAY['바울','데살로니가 교회']::text[],'세상을 떠난 성도들을 두고 슬퍼하는 이들에게 바울은 주 안에서 자는 자들도 주께서 강림하실 때 먼저 일어나고 살아남은 자들도 함께 끌어올려 주를 영접할 것이라며 서로 위로하라 권면했다.','죽음은 신앙 안에서 끝이 아니라 부활과 재회의 소망으로 이어지는 희망의 이유이다.',ARRAY['종말과 소망','고난과 인내']::text[],'사랑하는 이의 죽음 앞에서 나는 이 부활의 소망으로 위로받고 있는가?',ARRAY['성인']::text[],'v2','/s/331'),
(332,'게으르지 않고 일하라','신약','데살로니가후서',53,'살후 3:6-13',ARRAY['바울','데살로니가 교회']::text[],'재림이 임박했다는 생각에 무질서하게 지내던 일부 성도들에게 바울은 일하기 싫어하거든 먹지도 말라 하며 선을 행하다가 낙심하지 말라 권면했다.','재림을 기다리는 신앙은 무책임한 나태함이 아니라 오히려 성실한 일상으로 나타나야 한다.',ARRAY['순종과 믿음','충성과 신실함']::text[],'나는 소망을 기다리면서도 오늘의 일상에 성실한가?',ARRAY['성인']::text[],'v2','/s/332'),
(333,'젊음을 업신여기지 못하게 하라','신약','디모데전서',54,'딤전 4:12-16',ARRAY['바울','디모데']::text[],'바울은 젊은 디모데에게 누구든지 그의 연소함을 업신여기지 못하게 말과 행실과 사랑과 믿음과 정절에 있어 믿는 자에게 본이 되라 권면하며 자신과 가르침을 살펴 항상 힘쓰라 당부했다.','나이나 경력이 적더라도 삶의 본이 되는 성숙함으로 얼마든지 신뢰받는 지도자가 될 수 있다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 나이와 상관없이 삶으로 본이 되는 신앙을 살고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/333'),
(334,'자족하는 경건, 돈을 사랑함이 뿌리','신약','디모데전서',54,'딤전 6:6-12',ARRAY['바울','디모데']::text[],'바울은 자족하는 마음이 있으면 경건이 큰 유익이 되나 돈을 사랑함이 일만 악의 뿌리가 되어 어떤 이들은 미혹되어 믿음에서 떠난다고 경고했다.','물질에 대한 욕심은 신앙의 근본을 흔들 수 있으니 자족하는 마음을 훈련해야 한다.',ARRAY['시기와 갈등','지혜와 분별']::text[],'나는 물질에 대해 자족하는 마음을 얼마나 훈련하고 있는가?',ARRAY['성인']::text[],'v2','/s/334'),
(335,'모든 성경은 하나님의 감동으로 됨','신약','디모데후서',55,'딤후 3:14-4:5',ARRAY['바울','디모데']::text[],'바울은 디모데에게 어려서부터 알던 성경이 능히 구원에 이르는 지혜가 있게 하며, 모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하다고 가르치며 말씀을 전파하라 명했다.','성경 말씀은 삶의 모든 영역에서 우리를 바르게 세우고 온전케 하는 하나님의 도구이다.',ARRAY['율법과 계명','순종과 믿음']::text[],'나는 말씀을 삶의 교훈과 훈련의 기준으로 얼마나 의지하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/335'),
(336,'선한 싸움을 싸우고(바울의 고별 고백)','신약','디모데후서',55,'딤후 4:6-8',ARRAY['바울']::text[],'죽음을 앞둔 바울은 자신이 선한 싸움을 싸우고 달려갈 길을 마치고 믿음을 지켰으니 이제 의의 면류관이 예비되었다고 담대히 고백했다.','신실하게 완주한 인생의 마지막은 후회가 아니라 담대한 확신과 소망으로 채워질 수 있다.',ARRAY['충성과 신실함','종말과 소망']::text[],'나는 인생의 끝에서 바울처럼 담대히 고백할 수 있는 삶을 살고 있는가?',ARRAY['성인']::text[],'v2','/s/336'),
(337,'우리를 구원하시는 하나님의 은혜','신약','디도서',56,'딛 2:11-14',ARRAY['바울','디도']::text[],'바울은 모든 사람에게 구원을 주시는 하나님의 은혜가 나타나 경건하지 않은 것과 세상 정욕을 다 버리고 신중함과 의로움과 경건함으로 이 세상에 살라 교훈했다고 가르쳤다.','구원의 은혜는 우리를 죄에서 건질 뿐 아니라 경건한 삶으로 적극적으로 훈련시킨다.',ARRAY['하나님의 구원','순종과 믿음']::text[],'은혜를 받은 자로서 나는 경건한 삶을 향해 적극적으로 훈련하고 있는가?',ARRAY['성인']::text[],'v2','/s/337'),
(338,'바울이 오네시모를 위해 중재함','신약','빌레몬서',57,'몬 1:8-21',ARRAY['바울','빌레몬','오네시모']::text[],'도망쳤던 종 오네시모가 옥중에서 바울을 통해 회심하자, 바울은 주인 빌레몬에게 그를 종이 아니라 사랑받는 형제로 받아달라 간곡히 중재하는 편지를 썼다.','그리스도 안에서는 신분의 차이를 넘어 서로를 형제로 받아들이는 새로운 관계가 시작된다.',ARRAY['가정과 관계','사랑과 섬김']::text[],'나는 신분이나 지위를 넘어 누군가를 그리스도 안의 형제로 받아들이고 있는가?',ARRAY['성인']::text[],'v2','/s/338'),
(339,'하나님이 아들을 통해 말씀하심','신약','히브리서',58,'히 1:1-4',ARRAY['저자','예수 그리스도']::text[],'히브리서 저자는 옛적에 선지자들을 통해 여러 부분과 여러 모양으로 말씀하신 하나님이 이 모든 날 마지막에는 아들을 통해 말씀하셨으니 그 아들은 하나님의 영광의 광채시라 선포했다.','예수 그리스도는 하나님의 계시의 완성이며, 그분을 통해 우리는 하나님을 온전히 알 수 있다.',ARRAY['예수 그리스도의 정체성']::text[],'나는 예수님을 하나님의 최종적이고 완전한 말씀으로 받아들이고 있는가?',ARRAY['성인']::text[],'v2','/s/339'),
(340,'큰 대제사장이신 예수님','신약','히브리서',58,'히 4:14-16',ARRAY['저자','예수 그리스도']::text[],'히브리서 저자는 우리에게 큰 대제사장이신 예수님이 우리의 연약함을 동정하실 수 있는 분이니 은혜의 보좌 앞에 담대히 나아가 긍휼과 은혜를 받으라 권면했다.','우리의 연약함을 이해하시는 예수님 덕분에 우리는 두려움 없이 하나님께 담대히 나아갈 수 있다.',ARRAY['예수 그리스도의 정체성','기도와 응답']::text[],'나는 은혜의 보좌 앞에 담대히 나아가는 기도를 드리고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/340'),
(341,'믿음장','신약','히브리서',58,'히 11:1-40',ARRAY['저자','아벨','에녹','노아','아브라함','모세']::text[],'히브리서 저자는 믿음은 바라는 것들의 실상이요 보지 못하는 것들의 증거라 정의하며 아벨부터 여러 믿음의 선진들이 보이지 않는 약속을 붙들고 살았던 삶을 나열했다.','믿음의 선진들처럼 우리도 눈에 보이지 않는 하나님의 약속을 붙들고 살아가야 한다.',ARRAY['순종과 믿음']::text[],'나는 눈에 보이지 않는 하나님의 약속을 얼마나 붙들며 살고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/341'),
(342,'인내로 경주하라','신약','히브리서',58,'히 12:1-3',ARRAY['저자','예수 그리스도']::text[],'히브리서 저자는 구름 같이 둘러싼 허다한 증인들을 생각하며 모든 무거운 것과 얽매이는 죄를 벗어버리고 믿음의 주요 온전케 하시는 예수를 바라보며 인내로 경주하라 권면했다.','신앙의 여정은 단거리가 아니라 예수님을 바라보며 끝까지 인내하는 장거리 경주와 같다.',ARRAY['고난과 인내','순종과 믿음']::text[],'나는 신앙의 경주에서 무엇을 벗어버리고 무엇을 바라보아야 하는가?',ARRAY['청소년','성인']::text[],'v2','/s/342'),
(343,'시험을 당할 때 온전히 기쁘게 여기라','신약','야고보서',59,'약 1:2-8',ARRAY['야고보']::text[],'야고보는 여러 시험을 당하거든 온전히 기쁘게 여기라며 믿음의 시련이 인내를 만들어내고 그 인내가 온전한 것을 이루게 한다고 가르쳤다.','시험과 시련은 피해야 할 것이 아니라 믿음을 성숙시키는 하나님의 훈련 과정으로 받아들일 수 있다.',ARRAY['고난과 인내','순종과 믿음']::text[],'나는 시련을 어떻게 신앙 성장의 기회로 바라볼 수 있을까?',ARRAY['청소년','성인']::text[],'v2','/s/343'),
(344,'행함이 없는 믿음은 죽은 것','신약','야고보서',59,'약 2:14-26',ARRAY['야고보']::text[],'야고보는 행함이 없는 믿음은 그 자체가 죽은 것이라며 영혼 없는 몸이 죽은 것 같이 행함이 없는 믿음도 죽은 것이라 강하게 가르쳤다.','참된 믿음은 반드시 구체적인 행동과 삶의 열매로 드러나야 한다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'내 믿음은 삶의 구체적인 행함으로 나타나고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/344'),
(345,'혀를 길들임','신약','야고보서',59,'약 3:1-12',ARRAY['야고보']::text[],'야고보는 혀가 작은 지체이나 큰 것을 자랑하며 작은 불이 큰 숲을 태우듯 사람이 능히 혀를 길들일 수 없다고 경고하며 말의 신중함을 권면했다.','말은 작지만 그 영향력은 매우 커서 축복과 저주를 동시에 낼 수 있으므로 신중히 다스려야 한다.',ARRAY['분노 다스림','지혜와 분별']::text[],'나는 내 말이 누군가에게 상처가 아닌 축복이 되도록 다스리고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/345'),
(346,'산 소망, 시험 중의 기쁨','신약','베드로전서',60,'벧전 1:3-9',ARRAY['베드로']::text[],'베드로는 예수 그리스도의 부활로 우리가 산 소망을 가지게 되었다 말하며 여러 시험으로 근심할지라도 그로 인해 믿음이 순금보다 더 귀하게 되어 결국 찬송과 영광에 이른다고 위로했다.','시련 속에서도 그리스도의 부활에 근거한 산 소망은 우리를 흔들리지 않게 붙들어준다.',ARRAY['종말과 소망','고난과 인내']::text[],'시련 중에 나를 붙드는 부활의 산 소망은 무엇인가?',ARRAY['청소년','성인']::text[],'v2','/s/346'),
(347,'그리스도의 고난을 본받음','신약','베드로전서',60,'벧전 2:21-25',ARRAY['베드로','예수 그리스도']::text[],'베드로는 그리스도께서 우리를 위해 고난을 받으사 본을 남기셨으니 욕을 당하시되 맞대어 욕하지 아니하시고 오직 공의로 심판하시는 이에게 부탁하셨다며 그 발자취를 따르라 권면했다.','억울한 고난 앞에서 보복하지 않고 하나님께 맡기는 것이 그리스도를 본받는 삶이다.',ARRAY['고난과 인내','회개와 용서']::text[],'억울함을 당할 때 나는 하나님께 맡기는 그리스도의 본을 따르고 있는가?',ARRAY['성인']::text[],'v2','/s/347'),
(348,'근심을 주께 맡기라','신약','베드로전서',60,'벧전 5:6-11',ARRAY['베드로']::text[],'베드로는 성도들에게 하나님의 능하신 손 아래에서 겸손하고 모든 염려를 그에게 맡기라 하며 마귀가 우는 사자같이 삼킬 자를 찾아다니니 근신하고 깨어 믿음을 굳건히 하라 권면했다.','겸손히 염려를 하나님께 맡기는 동시에 영적으로 깨어 있는 것이 균형 잡힌 신앙이다.',ARRAY['기도와 응답','겸손과 교만']::text[],'나는 염려를 하나님께 맡기면서도 영적으로 깨어 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/348'),
(349,'신성한 성품에 참여하는 자','신약','베드로후서',61,'벧후 1:3-11',ARRAY['베드로']::text[],'베드로는 하나님의 능력이 생명과 경건에 속한 모든 것을 우리에게 주셨으니 믿음에 덕을, 덕에 지식을 더하며 성장해 신성한 성품에 참여하는 자가 되라 권면했다.','신앙은 처음 믿음에 머무는 것이 아니라 여러 성품을 더해가며 계속 성숙해가는 여정이다.',ARRAY['순종과 믿음','지혜와 분별']::text[],'나는 믿음 위에 어떤 성품들을 더해가며 성장하고 있는가?',ARRAY['성인']::text[],'v2','/s/349'),
(350,'주의 날이 더디지 않음','신약','베드로후서',61,'벧후 3:8-13',ARRAY['베드로']::text[],'베드로는 주께서 약속을 더디게 하시는 것이 아니라 아무도 멸망하지 않고 다 회개하기에 이르기를 원하사 오래 참으시는 것이라 설명하며 새 하늘과 새 땅을 바라보며 거룩한 삶을 살라 권면했다.','심판이 지연되는 것처럼 보이는 시간은 회개의 기회를 주시는 하나님의 인내와 사랑이다.',ARRAY['하나님의 심판','종말과 소망']::text[],'응답이 더디게 느껴질 때 나는 하나님의 인내하심을 신뢰하는가?',ARRAY['성인']::text[],'v2','/s/350'),
(351,'빛 가운데 행함, 죄를 자백함','신약','요한일서',62,'요일 1:5-10',ARRAY['요한']::text[],'요한은 하나님은 빛이시라 그 안에 어둠이 조금도 없으시니 우리가 죄를 자백하면 그가 미쁘시고 의로우사 우리 죄를 사하시고 모든 불의에서 깨끗하게 하신다 가르쳤다.','정직하게 죄를 자백하는 것이 하나님의 용서와 정결하게 하심을 경험하는 길이다.',ARRAY['회개와 용서','죄와 타락']::text[],'나는 죄를 숨기기보다 정직하게 하나님께 자백하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/351'),
(352,'하나님은 사랑이시라','신약','요한일서',62,'요일 4:7-21',ARRAY['요한']::text[],'요한은 사랑하는 자들아 우리가 서로 사랑하자 사랑은 하나님께 속한 것이니 하나님은 사랑이시라 하며, 먼저 사랑하신 그 사랑에 근거해 우리도 서로 사랑해야 한다고 가르쳤다.','우리의 사랑은 먼저 우리를 사랑하신 하나님의 사랑에 대한 반응이자 그 사랑의 증거이다.',ARRAY['하나님의 사랑','사랑과 섬김']::text[],'나는 먼저 받은 하나님의 사랑에 반응하여 이웃을 사랑하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/352'),
(353,'진리와 사랑 안에서 행하라','신약','요한이서',63,'요이 1:4-11',ARRAY['요한','택하심을 받은 부녀']::text[],'요한은 자녀들이 진리 안에서 행함을 크게 기뻐한다 말하며 서로 사랑하되 그리스도의 교훈 안에 거하여 거짓 가르침에 미혹되지 말라 권면했다.','진리 위에 굳게 선 사랑이야말로 그리스도인 공동체를 건강하게 지키는 힘이다.',ARRAY['사랑과 섬김','지혜와 분별']::text[],'나는 진리와 사랑, 두 가지를 함께 굳게 붙들고 있는가?',ARRAY['성인']::text[],'v2','/s/353'),
(354,'가이오의 선행을 칭찬함','신약','요한삼서',64,'요삼 1:1-8',ARRAY['요한','가이오','디오드레베']::text[],'요한은 나그네 된 형제들을 신실하게 대접한 가이오를 칭찬하며 이런 사람들을 도와 진리를 위하여 함께 일하는 자가 되라 권면했다.','나그네와 사역자를 향한 신실한 대접과 후원은 복음 사역에 동참하는 귀한 섬김이다.',ARRAY['사랑과 섬김','충성과 신실함']::text[],'나는 사역자나 나그네를 대접하고 후원하는 일에 얼마나 신실한가?',ARRAY['성인']::text[],'v2','/s/354'),
(355,'믿음의 도를 위해 힘써 싸우라','신약','유다서',65,'유 1:3-4,20-25',ARRAY['유다']::text[],'유다는 성도에게 단번에 주신 믿음의 도를 위하여 힘써 싸우라 권면하며 거짓 교사들을 경계하고, 마지막에는 능히 너희를 보호하사 흠 없이 서게 하실 하나님께 영광의 송영을 올렸다.','혼탁한 가르침이 넘치는 시대에도 성도는 참된 믿음의 도를 굳게 지키며 살아야 한다.',ARRAY['순종과 믿음','충성과 신실함']::text[],'나는 거짓된 가르침 속에서 참된 믿음의 도를 분별하며 지키고 있는가?',ARRAY['성인']::text[],'v2','/s/355'),
(356,'부활하신 그리스도의 환상','신약','요한계시록',66,'계 1:9-20',ARRAY['요한','예수 그리스도']::text[],'밧모섬에 유배된 요한이 주의 날에 성령에 감동되어 촛대 사이를 거니시며 해같이 빛나는 얼굴을 가지신 부활하신 그리스도를 보고 엎드러지니 그가 손을 얹으며 ''두려워하지 말라 나는 처음이요 마지막이라'' 말씀하셨다.','가장 고립된 유배지에서도 부활하신 그리스도는 그의 백성에게 친히 나타나 위로하신다.',ARRAY['예수 그리스도의 정체성','인도하심과 보호']::text[],'가장 외로운 순간에도 나는 그리스도의 임재를 기대할 수 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/356'),
(357,'일곱 교회에게 보내는 편지','신약','요한계시록',66,'계 2:1-3:22',ARRAY['요한','일곱 교회']::text[],'그리스도는 에베소, 서머나, 버가모, 두아디라, 사데, 빌라델비아, 라오디게아 일곱 교회 각각에게 칭찬과 책망, 권면의 말씀을 보내시며 이기는 자에게 주실 약속을 전하셨다.','주님은 각 공동체의 형편을 정확히 아시며 회개와 인내를 통해 이기는 자가 되기를 원하신다.',ARRAY['교회와 공동체','회개와 용서']::text[],'일곱 교회 중 내 신앙과 가장 닮은 교회는 어디이며 어떤 회개가 필요한가?',ARRAY['성인']::text[],'v2','/s/357'),
(358,'하늘 보좌의 환상','신약','요한계시록',66,'계 4:1-11',ARRAY['요한','이십사 장로','네 생물','하나님']::text[],'하늘 문이 열려 하늘에 보좌가 있고 그 위에 앉으신 이의 영광 가운데, 이십사 장로와 네 생물이 밤낮 쉬지 않고 ''거룩하다 거룩하다 거룩하다'' 찬양하며 경배하는 모습을 요한이 보았다.','하늘의 예배는 쉬지 않고 하나님의 거룩하심과 영광을 찬양하는 영원한 경배의 자리이다.',ARRAY['예배와 경배','예수 그리스도의 정체성']::text[],'나는 하늘의 예배를 소망하며 이 땅에서 어떻게 경배하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/358'),
(359,'일곱 인으로 봉한 두루마리와 어린 양','신약','요한계시록',66,'계 5:1-14',ARRAY['요한','어린 양','이십사 장로']::text[],'아무도 열 수 없던 두루마리를 오직 죽임을 당하신 어린 양만이 합당하다 하여 취하시니 모든 피조물이 ''죽임을 당하신 어린 양은 능력과 부와 지혜와 힘과 존귀와 영광과 찬송을 받으시기에 합당하도다'' 노래했다.','오직 십자가에서 죽임당하신 어린 양만이 역사와 구원의 두루마리를 여실 자격이 있으시다.',ARRAY['예수 그리스도의 정체성','예배와 경배']::text[],'어린 양 되신 예수님이 내 인생의 두루마리도 열어가고 계심을 믿는가?',ARRAY['청소년','성인']::text[],'v2','/s/359'),
(360,'네 말 탄 자(인봉 심판)','신약','요한계시록',66,'계 6:1-17',ARRAY['요한','어린 양','네 말 탄 자']::text[],'어린 양이 인을 하나씩 떼실 때마다 흰 말, 붉은 말, 검은 말, 청황색 말을 탄 자들이 나타나 전쟁과 기근, 죽음의 심판이 땅에 임하는 것을 요한이 보았다.','역사 속의 고통과 혼란도 결국 하나님의 주권적인 심판 계획 안에 있다.',ARRAY['하나님의 심판','종말과 소망']::text[],'세상의 혼란과 고통을 바라볼 때 나는 하나님의 주권을 신뢰하는가?',ARRAY['성인']::text[],'v2','/s/360'),
(361,'십사만 사천을 인침','신약','요한계시록',66,'계 7:1-17',ARRAY['요한','인침받은 자들','흰 옷 입은 큰 무리']::text[],'땅과 바다를 해하는 것이 잠시 보류된 가운데 이스라엘 각 지파에서 인침받은 십사만 사천과, 각 나라와 족속과 백성과 방언에서 나온 셀 수 없는 큰 무리가 흰 옷을 입고 하나님 보좌 앞에서 찬양했다.','하나님은 심판 중에도 자기 백성을 인쳐 보호하시며, 구원받은 무리는 셀 수 없이 많다.',ARRAY['인도하심과 보호','종말과 소망']::text[],'나는 하나님이 내게 두신 인침과 보호하심을 신뢰하는가?',ARRAY['청소년','성인']::text[],'v2','/s/361'),
(362,'일곱째 인과 일곱 나팔','신약','요한계시록',66,'계 8:1-9:21',ARRAY['요한','일곱 천사']::text[],'일곱째 인이 떼어지고 일곱 나팔이 차례로 울릴 때마다 우박과 불, 바다의 변화, 별의 재앙 등 땅에 임하는 심판이 점점 심화되었으나 사람들은 여전히 회개하지 않았다.','반복되는 경고와 심판 앞에서도 회개하지 않는 완악한 마음은 심판을 더욱 무겁게 한다.',ARRAY['하나님의 심판','회개와 용서']::text[],'나는 반복된 경고 앞에서 어떻게 반응하는 사람인가?',ARRAY['성인']::text[],'v2','/s/362'),
(363,'힘센 천사와 작은 두루마리','신약','요한계시록',66,'계 10:1-11',ARRAY['요한','힘센 천사']::text[],'힘센 천사가 펴놓인 작은 두루마리를 요한에게 주며 먹으라 하니 입에는 꿀같이 달았으나 배에서는 쓰게 되었고, 요한은 많은 백성과 나라와 방언과 임금에게 다시 예언하라는 사명을 받았다.','하나님의 말씀은 은혜로 달콤하지만 그것을 전하는 사명에는 쓰라린 대가도 따를 수 있다.',ARRAY['순종과 믿음','전도와 선교']::text[],'하나님의 말씀을 전하는 일이 달콤함과 쓴맛을 함께 지닌다는 것을 경험한 적이 있는가?',ARRAY['성인']::text[],'v2','/s/363'),
(364,'두 증인','신약','요한계시록',66,'계 11:1-14',ARRAY['요한','두 증인']::text[],'베옷을 입은 두 증인이 권세로 예언하다가 짐승에게 죽임을 당하지만 사흘 반 후 하나님의 생기가 들어가 다시 살아나 하늘로 올라가는 것을 사람들이 보고 두려워했다.','하나님의 증인들은 죽음의 위협 속에서도 결국 부활의 능력으로 승리를 확증받는다.',ARRAY['고난과 인내','하나님의 구원']::text[],'죽음을 무릅쓴 증인의 삶이 오늘 내게 주는 도전은 무엇인가?',ARRAY['성인']::text[],'v2','/s/364'),
(365,'여자와 용','신약','요한계시록',66,'계 12:1-17',ARRAY['요한','해를 입은 여자','붉은 용','미가엘']::text[],'해를 옷 입은 여자가 아이를 낳으려 할 때 붉은 용이 삼키려 했으나 아이는 하나님 보좌로 올려졌고, 미가엘과 천사들이 용과 싸워 이겨 하늘에서 쫓아내니 땅에 내려온 용은 여자의 남은 자손과 싸우려 했다.','사탄의 집요한 공격에도 하나님은 자기 백성과 메시아를 지키시고 궁극적인 승리를 보장하신다.',ARRAY['인도하심과 보호','하나님의 구원']::text[],'영적 전쟁의 실재 앞에서 나는 하나님의 보호하심을 신뢰하는가?',ARRAY['성인']::text[],'v2','/s/365'),
(366,'두 짐승(바다의 짐승과 땅의 짐승)','신약','요한계시록',66,'계 13:1-18',ARRAY['요한','바다에서 나온 짐승','땅에서 나온 짐승']::text[],'바다에서 나온 짐승이 온 땅의 경배를 받고 땅에서 나온 짐승이 그를 위해 표를 강요하니, 그 수는 사람의 수로 육백육십육이라 요한은 지혜 있는 자들에게 분별하라 권면했다.','거짓 권세는 그럴듯한 모습으로 경배를 강요하지만 성도는 끝까지 분별하며 참된 신앙을 지켜야 한다.',ARRAY['우상숭배 경계','지혜와 분별']::text[],'나는 세상의 거짓된 권세와 유혹을 분별하는 지혜가 있는가?',ARRAY['성인']::text[],'v2','/s/366'),
(367,'어린 양과 십사만 사천, 세 천사의 메시지','신약','요한계시록',66,'계 14:1-13',ARRAY['요한','어린 양','십사만 사천','세 천사']::text[],'시온산에 어린 양과 함께 선 십사만 사천이 새 노래를 부르는 가운데, 세 천사가 차례로 영원한 복음과 바벨론의 멸망, 짐승에게 경배하는 자에 대한 경고를 선포했다.','마지막 때에도 하나님은 영원한 복음을 선포하시며 사람들에게 돌이킬 기회를 주신다.',ARRAY['전도와 선교','종말과 소망']::text[],'나는 마지막 때에도 계속되는 복음 전파의 사명을 붙들고 있는가?',ARRAY['성인']::text[],'v2','/s/367'),
(368,'일곱 대접 재앙','신약','요한계시록',66,'계 15:1-16:21',ARRAY['요한','일곱 천사']::text[],'마지막 재앙인 일곱 대접이 땅과 바다, 강과 해, 그리고 아마겟돈에 차례로 쏟아지며 하나님의 진노가 완성되었으나 사람들은 여전히 회개하지 않고 하나님을 비방했다.','심판이 극에 달해도 회개하지 않는 완악함은 스스로 더 깊은 멸망을 자초할 뿐이다.',ARRAY['하나님의 심판','회개와 용서']::text[],'나는 크고 작은 경고 앞에서 즉시 돌이키는 민감함이 있는가?',ARRAY['성인']::text[],'v2','/s/368'),
(369,'큰 음녀 바벨론의 멸망','신약','요한계시록',66,'계 17:1-18:24',ARRAY['요한','큰 음녀','바벨론']::text[],'사치와 우상숭배로 가득했던 큰 성 바벨론이 하나님의 심판으로 하루아침에 무너지니, 그와 함께 부를 누리던 땅의 왕들과 상인들이 통곡하며 애곡했다.','세상 권세와 물질의 화려함도 하나님의 때가 이르면 한순간에 무너질 수 있다.',ARRAY['하나님의 심판','우상숭배 경계']::text[],'나는 세상의 화려함이 아닌 영원한 것에 마음을 두고 있는가?',ARRAY['성인']::text[],'v2','/s/369'),
(370,'어린 양의 혼인 잔치','신약','요한계시록',66,'계 19:1-10',ARRAY['요한','어린 양','신부(교회)']::text[],'하늘의 허다한 무리가 ''할렐루야 주 우리 하나님 곧 전능하신 이가 통치하시도다'' 찬양하는 가운데, 어린 양의 혼인 기약이 이르러 그 아내가 예비되어 신부처럼 단장한 잔치가 예고되었다.','성도의 최종적 소망은 어린 양이신 그리스도와 영원히 함께하는 혼인 잔치의 기쁨이다.',ARRAY['종말과 소망','예배와 경배']::text[],'어린 양의 혼인 잔치를 향한 소망이 오늘 내 삶에 어떤 힘을 주는가?',ARRAY['청소년','성인']::text[],'v2','/s/370'),
(371,'백마 탄 자의 재림','신약','요한계시록',66,'계 19:11-21',ARRAY['요한','백마 탄 자(그리스도)','짐승','땅의 왕들']::text[],'하늘이 열리고 충신과 진실이라 불리는 백마 탄 자가 만왕의 왕 만주의 주라는 이름을 가지고 공의로 심판하고 싸우시니 짐승과 그 군대가 완전히 패배했다.','역사의 마지막은 혼돈이 아니라 공의로우신 왕이신 그리스도의 확실한 승리로 완성된다.',ARRAY['예수 그리스도의 정체성','종말과 소망']::text[],'역사의 결말이 그리스도의 승리라는 확신이 오늘의 나를 어떻게 붙드는가?',ARRAY['청소년','성인']::text[],'v2','/s/371'),
(372,'천 년 왕국과 최후의 심판','신약','요한계시록',66,'계 20:1-15',ARRAY['요한','사탄','죽은 자들','하나님']::text[],'사탄이 천 년 동안 결박되었다가 잠시 놓였다 다시 심판받고, 마지막에는 크고 흰 보좌 앞에서 죽은 자들이 자기 행위대로 심판받으며 생명책에 기록되지 못한 자는 불못에 던져졌다.','모든 사람은 결국 하나님 앞에서 자기 삶에 대한 정확한 심판을 받게 될 것이다.',ARRAY['하나님의 심판','종말과 소망']::text[],'마지막 심판 앞에서 나는 오늘을 어떻게 살아야 할지 생각해보자.',ARRAY['성인']::text[],'v2','/s/372'),
(373,'새 하늘과 새 땅','신약','요한계시록',66,'계 21:1-8',ARRAY['하나님','어린 양','요한']::text[],'요한이 새 하늘과 새 땅, 하늘에서 내려오는 새 예루살렘을 보았고, 하나님이 친히 백성과 함께 거하시며 모든 눈물을 닦아주실 것을 약속하셨다.','성도의 소망은 고통이 끝나고 하나님과 온전히 함께하는 영원한 나라에 있다.',ARRAY['종말과 소망']::text[],'지금의 고난 중에 새 하늘과 새 땅에 대한 소망이 내게 어떤 힘이 되는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/373'),
(374,'새 예루살렘성','신약','요한계시록',66,'계 21:9-27',ARRAY['요한','천사','새 예루살렘']::text[],'천사가 요한을 데리고 하나님의 영광이 충만하고 열두 진주 문과 보석으로 꾸며진 새 예루살렘성을 보여주었는데 그 성에는 해와 달이 쓸데없이 하나님과 어린 양이 그 등불이 되었다.','영원한 하나님의 나라는 상상을 초월하는 영광과 아름다움으로 예비되어 있다.',ARRAY['종말과 소망','예수 그리스도의 정체성']::text[],'영원한 나라에 대한 소망이 오늘 내 삶의 우선순위를 어떻게 바꾸는가?',ARRAY['청소년','성인']::text[],'v2','/s/374'),
(375,'생명수 강과 마지막 초청','신약','요한계시록',66,'계 22:1-21',ARRAY['요한','예수 그리스도']::text[],'수정같이 맑은 생명수의 강이 보좌로부터 흘러나오는 것을 본 요한에게 예수님은 ''내가 속히 오리라'' 약속하셨고, 성령과 신부가 ''오라'' 하며 목마른 자는 값없이 생명수를 받으라는 마지막 초청으로 성경 전체가 마무리된다.','성경 전체는 결국 목마른 모든 이를 향한 값없는 생명수의 초청으로 끝맺는다.',ARRAY['하나님의 구원','종말과 소망']::text[],'나는 오늘 이 생명수의 초청에 목마름으로 나아가고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/375'),
(376,'이삭과 아비멜렉의 우물 다툼','구약','창세기',1,'창 26:1-33',ARRAY['이삭','아비멜렉','하나님']::text[],'흉년에 그랄에 거하던 이삭이 아버지처럼 아내를 누이라 속였다가 들켰으나, 이후 우물을 두고 다투던 아비멜렉과 결국 화친 언약을 맺고 브엘세바라 이름했다.','분쟁이 있을 때 다투기보다 양보하며 평화를 구하는 태도에 하나님은 풍성함으로 복을 주신다.',ARRAY['가정과 관계','순종과 믿음']::text[],'나는 갈등의 자리에서 다투기보다 평화를 구하는 편인가?',ARRAY['청소년','성인']::text[],'v2','/s/376'),
(377,'야곱이 에서를 만나기 전 예물을 보냄','구약','창세기',1,'창 32:1-21',ARRAY['야곱','에서']::text[],'이십 년 만에 에서를 만나기 두려웠던 야곱이 많은 예물을 앞서 보내고 가족을 나누어 배치하며 지혜롭게 준비한 후 하나님께 간절히 기도했다.','두려운 상황 앞에서 지혜로운 준비와 간절한 기도를 함께 드리는 것이 성숙한 신앙의 태도이다.',ARRAY['기도와 응답','지혜와 분별']::text[],'나는 두려운 상황 앞에서 준비와 기도를 함께 하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/377'),
(378,'언약서: 삶의 구체적 법규','구약','출애굽기',2,'출 21:1-23:19',ARRAY['모세','이스라엘 백성','하나님']::text[],'십계명 이후 하나님은 종에 대한 대우, 상해에 대한 배상, 가난한 자와 나그네를 위한 배려 등 일상生활 속에서 지켜야 할 구체적인 법규들을 이스라엘에게 주셨다.','하나님의 법은 예배의 영역을 넘어 이웃과의 일상적 관계와 공동체 정의에까지 구체적으로 적용된다.',ARRAY['율법과 계명','사랑과 섬김']::text[],'나는 신앙을 예배의 자리뿐 아니라 일상의 관계 속에서도 구체적으로 실천하는가?',ARRAY['성인']::text[],'v2','/s/378'),
(379,'성막 기구와 브살렐의 지혜','구약','출애굽기',2,'출 25:1-9,31:1-11',ARRAY['모세','브살렐','오홀리압','하나님']::text[],'하나님이 성막과 언약궤, 등잔대 등 거룩한 기구의 양식을 자세히 알려주시고, 브살렐과 오홀리압에게 하나님의 영과 지혜와 총명을 채워 정교한 손기술로 그것을 만들게 하셨다.','예술적 재능과 손의 기술도 하나님이 주신 은사이며 거룩한 목적으로 아름답게 쓰임받을 수 있다.',ARRAY['창조와 섭리','사랑과 섬김']::text[],'나의 재능과 기술을 하나님의 일을 위해 어떻게 드릴 수 있을까?',ARRAY['성인']::text[],'v2','/s/379'),
(380,'네 이웃을 네 몸과 같이 사랑하라','구약','레위기',3,'레 19:1-18',ARRAY['모세','이스라엘 백성','하나님']::text[],'하나님은 거룩한 삶을 위해 가난한 자를 위한 추수의 배려, 정직한 저울, 원한을 품지 않음 등을 명하시며 ''네 이웃 사랑하기를 네 몸과 같이 하라'' 말씀하셨다.','거룩함은 예배의 형식뿐 아니라 이웃을 향한 구체적인 정직과 사랑의 실천으로 완성된다.',ARRAY['사랑과 섬김','율법과 계명']::text[],'나는 일상 속 작은 정직함과 배려로 이웃 사랑을 실천하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/380'),
(381,'므리바 물: 모세가 반석을 침','구약','민수기',4,'민 20:1-13',ARRAY['모세','아론','이스라엘 백성','하나님']::text[],'목마른 백성이 다시 원망하자 하나님은 반석에게 명령하라 하셨으나 모세는 분노하여 반석을 두 번 쳤고, 이로 인해 모세와 아론은 약속의 땅에 들어가지 못하는 벌을 받았다.','지도자의 순간적인 분노와 불순종은 하나님의 영광을 가리며 무거운 책임을 남긴다.',ARRAY['분노 다스림','순종과 믿음']::text[],'나는 지쳤을 때 하나님의 명령을 정확히 따르기보다 내 감정대로 행동한 적이 없는가?',ARRAY['청소년','성인']::text[],'v2','/s/381'),
(382,'아론의 죽음','구약','민수기',4,'민 20:22-29',ARRAY['아론','모세','엘르아살']::text[],'호르산에서 하나님의 명대로 모세가 아론의 제사장 옷을 아들 엘르아살에게 입히니 아론이 그곳에서 죽고 온 회중이 그를 위해 삼십 일을 애곡했다.','한 세대의 직분은 다음 세대로 이어지며, 신실했던 삶은 공동체의 깊은 애도로 기억된다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 내가 맡은 직분을 다음 세대에 신실하게 물려줄 준비를 하고 있는가?',ARRAY['성인']::text[],'v2','/s/382'),
(383,'르우벤과 갓 지파의 요단 동편 정착','구약','민수기',4,'민 32:1-42',ARRAY['르우벤 지파','갓 지파','모세']::text[],'목축에 유리한 요단 동편 땅을 원한 르우벤과 갓 지파에게 모세는 먼저 형제들과 함께 가나안 정복 전쟁에 앞장선 후에 정착하라는 조건으로 허락했다.','자신의 유익을 구하면서도 공동체의 책임을 함께 감당하는 것이 균형 잡힌 신앙의 자세이다.',ARRAY['가정과 관계','충성과 신실함']::text[],'나는 내 유익을 구하면서도 공동체의 책임을 함께 지고 있는가?',ARRAY['성인']::text[],'v2','/s/383'),
(384,'광야 사십 년을 기억하라','구약','신명기',5,'신 8:1-20',ARRAY['모세','이스라엘 백성']::text[],'모세는 광야 사십 년 동안 하나님이 만나로 먹이시고 옷이 해어지지 않게 하신 것을 기억하라 하며, 풍족해진 후에도 그 능력이 자신에게서 났다 교만하지 말라 경고했다.','풍요로운 시절일수록 광야에서 베푸신 하나님의 은혜를 더욱 기억하며 겸손해야 한다.',ARRAY['겸손과 교만','인도하심과 보호']::text[],'나는 풍족할 때도 지난날 하나님의 은혜를 잊지 않고 기억하는가?',ARRAY['청소년','성인']::text[],'v2','/s/384'),
(385,'축복과 저주','구약','신명기',5,'신 28:1-68',ARRAY['모세','이스라엘 백성']::text[],'모세는 하나님의 말씀에 순종하면 임할 풍성한 축복과, 불순종하면 임할 무서운 저주를 구체적으로 나열하며 백성에게 언약의 길을 선택하라 촉구했다.','순종과 불순종에는 각각 분명한 결과가 따르니 언약 백성은 그 무게를 진지하게 받아들여야 한다.',ARRAY['순종과 믿음','하나님의 언약']::text[],'나는 순종과 불순종의 결과를 얼마나 진지하게 여기며 살고 있는가?',ARRAY['성인']::text[],'v2','/s/385'),
(386,'갈렙이 헤브론을 구함','구약','여호수아',6,'수 14:6-15',ARRAY['갈렙','여호수아']::text[],'여든다섯 살이 된 갈렙이 사십오 년 전 하나님을 온전히 좇았던 그 믿음 그대로 아직도 강건하다며 거인족이 있는 헤브론 산지를 기업으로 구하여 얻었다.','나이가 들어서도 젊은 날의 믿음과 열정을 그대로 간직하는 삶은 하나님이 기뻐하시는 신실함이다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 나이가 들어도 처음 믿음의 열정을 그대로 간직하고 있는가?',ARRAY['성인']::text[],'v2','/s/386'),
(387,'도피성 제정','구약','여호수아',6,'수 20:1-9',ARRAY['여호수아','이스라엘 백성']::text[],'하나님의 명대로 여호수아는 부지중에 살인한 자가 피신하여 공정한 재판을 받을 수 있도록 여섯 개의 도피성을 이스라엘 땅 곳곳에 세웠다.','하나님의 공의는 억울한 자를 보호하는 구체적인 제도적 장치로도 나타난다.',ARRAY['율법과 계명','인도하심과 보호']::text[],'우리 공동체에는 억울한 이를 보호하는 안전한 장치가 마련되어 있는가?',ARRAY['성인']::text[],'v2','/s/387'),
(388,'옷니엘과 에훗','구약','사사기',7,'삿 3:7-30',ARRAY['옷니엘','에훗','에글론 왕']::text[],'이스라엘이 우상을 섬겨 압제받자 하나님은 첫 사사 옷니엘을 세워 평안을 주셨고, 이후 왼손잡이 사사 에훗은 지혜롭게 모압 왕 에글론을 처단하여 백성을 구원했다.','하나님은 다양한 배경과 특징을 가진 사람을 통해서도 자기 백성을 구원하는 방법을 예비하신다.',ARRAY['하나님의 구원','인도하심과 보호']::text[],'나의 남과 다른 특징도 하나님이 사용하실 도구가 될 수 있음을 믿는가?',ARRAY['청소년','성인']::text[],'v2','/s/388'),
(389,'한나의 감사 기도','구약','사무엘상',9,'삼상 2:1-10',ARRAY['한나','하나님']::text[],'사무엘을 하나님께 드린 한나는 ''내 마음이 여호와로 말미암아 즐거워하며'' 시작되는 찬양으로 낮은 자를 높이시고 교만한 자를 낮추시는 하나님을 노래했다.','응답받은 기도 이후 드리는 진심 어린 감사와 찬양은 하나님의 주권을 인정하는 신앙의 고백이다.',ARRAY['기도와 응답','예배와 경배']::text[],'나는 응답받은 기도 이후 얼마나 진심으로 감사와 찬양을 드리는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/389'),
(390,'사무엘의 고별 설교','구약','사무엘상',9,'삼상 12:1-25',ARRAY['사무엘','이스라엘 백성']::text[],'왕을 세운 후 늙은 사무엘은 자신이 백성에게 해를 끼친 일이 없음을 증언하며, 백성에게 여호와만을 온전히 섬기고 마음을 다하여 그를 따르라 당부했다.','오랜 세월 신실하게 섬긴 지도자는 떠나는 순간까지도 정직함과 진심 어린 권면을 남긴다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 내가 맡은 자리를 정직하고 신실하게 감당하고 있는가?',ARRAY['성인']::text[],'v2','/s/390'),
(391,'다윗이 므비보셋에게 은총을 베풂','구약','사무엘하',10,'삼하 9:1-13',ARRAY['다윗','므비보셋','요나단']::text[],'다리를 저는 요나단의 아들 므비보셋을 찾아낸 다윗이 요나단과의 언약을 기억하며 그에게 사울의 모든 토지를 돌려주고 왕의 상에서 함께 먹게 했다.','언약의 신실함은 세월이 흘러도 잊지 않고 약속한 이의 후손에게까지 은혜로 이어진다.',ARRAY['충성과 신실함','사랑과 섬김']::text[],'나는 오래전 맺은 신의와 약속을 여전히 신실하게 지키고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/391'),
(392,'다윗의 용사들','구약','사무엘하',10,'삼하 23:8-39',ARRAY['다윗','요셉밧세벳','엘르아살','다윗의 세 용사']::text[],'다윗을 위해 목숨을 걸고 블레셋 진영을 뚫어 베들레헴의 물을 떠온 세 용사의 충성 이야기와 함께, 다윗을 섬긴 여러 용사들의 이름이 기록되었다.','한 사람의 위대한 업적 뒤에는 언제나 이름 없이 헌신한 신실한 동역자들이 있다.',ARRAY['충성과 신실함','사랑과 섬김']::text[],'나는 누군가의 성취 뒤에서 이름 없이 헌신한 적이 있는가?',ARRAY['성인']::text[],'v2','/s/392'),
(393,'엘리야가 엘리사를 부르심','구약','열왕기상',11,'왕상 19:19-21',ARRAY['엘리야','엘리사']::text[],'호렙산에서 새 사명을 받은 엘리야가 밭을 갈고 있던 엘리사에게 겉옷을 던지니 엘리사는 소를 잡아 잔치를 베풀고 모든 것을 버려둔 채 엘리야를 따랐다.','하나님의 부르심에 응답하는 것은 지금까지의 삶을 미련 없이 내려놓는 결단을 요구할 수 있다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 하나님의 부르심 앞에서 지금의 삶을 내려놓을 결단을 할 수 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/393'),
(394,'미가야 선지자와 아합의 죽음','구약','열왕기상',11,'왕상 22:1-40',ARRAY['아합','미가야','여호사밧']::text[],'사백 명의 거짓 선지자들이 승리를 예언할 때 홀로 미가야는 아합의 패배와 죽음을 예언했고, 미가야를 옥에 가둔 아합은 결국 전쟁터에서 화살에 맞아 죽었다.','다수의 목소리보다 진실을 말하는 한 사람의 예언이 하나님 앞에서 더 무겁고 정확하다.',ARRAY['지혜와 분별','하나님의 심판']::text[],'나는 다수의 의견과 다르더라도 진실을 말할 용기가 있는가?',ARRAY['성인']::text[],'v2','/s/394'),
(395,'엘리사의 마지막과 사후의 기적','구약','열왕기하',12,'왕하 13:14-21',ARRAY['엘리사','요아스 왕','죽은 시신']::text[],'죽음을 앞둔 엘리사가 요아스 왕에게 화살로 승리를 예언했고, 훗날 엘리사의 무덤에 급히 던져진 시신이 그 뼈에 닿자 다시 살아났다.','하나님의 능력은 한 사람의 생애가 끝난 후에도 그 신실했던 삶을 통해 계속 역사할 수 있다.',ARRAY['하나님의 구원','충성과 신실함']::text[],'나는 내 생애 이후에도 남을 신앙의 영향력을 어떻게 준비하고 있는가?',ARRAY['성인']::text[],'v2','/s/395'),
(396,'언약궤가 예루살렘으로 입성함(다윗의 찬양)','구약','역대상',13,'대상 15:1-16:43',ARRAY['다윗','레위 사람들','언약궤']::text[],'다윗이 레위 사람들에게 규례대로 언약궤를 메게 하고 예루살렘으로 옮긴 후 아삽에게 감사 찬양을 맡기니 온 백성이 크게 기뻐하며 하나님께 찬송했다.','하나님이 정하신 질서를 따라 드리는 예배와 찬양은 공동체 전체에 참된 기쁨을 가져온다.',ARRAY['예배와 경배','순종과 믿음']::text[],'우리 공동체의 예배는 질서와 기쁨이 함께 조화를 이루고 있는가?',ARRAY['성인']::text[],'v2','/s/396'),
(397,'성전 봉헌에 대한 하나님의 응답','구약','역대하',14,'대하 7:1-22',ARRAY['솔로몬','하나님']::text[],'성전 봉헌 기도 후 하늘에서 불이 내려와 제물을 사르고 여호와의 영광이 성전에 가득하니, 하나님은 ''내 이름으로 일컫는 내 백성이 스스로 낮추고 기도하면 내가 하늘에서 듣고 그 땅을 고치리라'' 약속하셨다.','겸손히 자신을 낮추고 하나님께 돌이켜 기도하는 백성에게 하나님은 반드시 응답하시고 회복시키신다.',ARRAY['기도와 응답','회개와 용서']::text[],'우리 공동체는 스스로를 낮추고 기도로 돌이키는 것을 얼마나 실천하고 있는가?',ARRAY['성인']::text[],'v2','/s/397'),
(398,'네 짐승 환상','구약','다니엘',27,'단 7:1-28',ARRAY['다니엘','네 짐승','옛적부터 항상 계신 이']::text[],'다니엘이 환상 중에 바다에서 올라오는 네 짐승을 보았는데 이는 장차 있을 나라들을 상징했으며, 마지막에는 인자 같은 이가 옛적부터 항상 계신 이에게 나아가 영원한 나라와 권세를 받았다.','세상 나라들은 흥망을 거듭하지만 하나님이 세우실 영원한 나라만이 결국 온전히 서게 될 것이다.',ARRAY['하나님 나라','종말과 소망']::text[],'세상 권세의 흥망 속에서 나는 영원한 하나님 나라를 얼마나 바라보고 있는가?',ARRAY['성인']::text[],'v2','/s/398'),
(399,'숫양과 숫염소 환상','구약','다니엘',27,'단 8:1-27',ARRAY['다니엘','숫양','숫염소','가브리엘']::text[],'다니엘이 두 뿔 가진 숫양을 이기는 숫염소의 환상을 보았고, 가브리엘 천사가 이는 장차 있을 나라들의 흥망을 상징하며 정한 때에 반드시 이루어질 것을 해석해주었다.','이해하기 어려운 환상과 예언 앞에서도 하나님의 계획은 정한 때에 한 치 오차 없이 성취된다.',ARRAY['하나님의 섭리','순종과 믿음']::text[],'당장 이해되지 않는 하나님의 계획 앞에서 나는 그 성취를 신뢰하며 기다릴 수 있는가?',ARRAY['성인']::text[],'v2','/s/399'),
(400,'대제사장 여호수아가 정결케 됨','구약','스가랴',38,'슥 3:1-10',ARRAY['여호수아','사탄','여호와의 사자']::text[],'더러운 옷을 입은 대제사장 여호수아를 사탄이 고발했으나 여호와의 천사는 그를 책망하며 더러운 옷을 벗기고 아름다운 옷을 입혀 정결케 하셨다.','하나님은 우리의 허물을 지적하는 고발자의 참소로부터 우리를 변호하시고 정결하게 입혀주신다.',ARRAY['회개와 용서','하나님의 구원']::text[],'죄와 허물로 인한 참소 앞에서 나는 하나님의 변호하심을 신뢰하는가?',ARRAY['성인']::text[],'v2','/s/400'),
(401,'겸손한 왕이 나귀를 타고 오실 예언','구약','스가랴',38,'슥 9:9-10',ARRAY['스가랴']::text[],'스가랴는 시온의 딸에게 ''너의 왕이 네게 임하시나니 그는 공의로우시며 구원을 베풀며 겸손하여 나귀를 타셨다'' 예언하며 장차 임할 평화의 왕을 노래했다.','참된 왕의 다스림은 군사력이 아니라 겸손과 평화로 특징지어진다.',ARRAY['예수 그리스도의 정체성','겸손과 교만']::text[],'겸손히 오시는 왕의 모습을 나는 삶에서 어떻게 본받을 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/401'),
(402,'시편 1편: 복 있는 사람','구약','시편',19,'시 1:1-6',ARRAY['시인']::text[],'시인은 악인의 꾀를 따르지 않고 여호와의 율법을 즐거워하며 묵상하는 자는 시냇가에 심은 나무처럼 무엇을 하든지 형통하다고 노래하며 시편 전체의 서문을 연다.','말씀을 가까이하고 즐거워하는 삶은 흔들리지 않는 뿌리 깊은 인생을 만든다.',ARRAY['순종과 믿음','지혜와 분별']::text[],'나는 하나님의 말씀을 즐거워하며 묵상하는 삶의 뿌리를 얼마나 깊이 내리고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/402'),
(403,'시편 8편: 사람이 무엇이관대','구약','시편',19,'시 8:1-9',ARRAY['다윗']::text[],'다윗은 하늘의 광대함을 보며 주를 생각하시는 사람이 무엇이관대 하나님이 그를 천사보다 조금 못하게 하시고 영화와 존귀로 관을 씌우셨는지 감탄하며 노래했다.','광활한 우주 앞에서도 사람은 하나님께 특별한 존귀함과 사명을 부여받은 존재이다.',ARRAY['창조와 섭리','예배와 경배']::text[],'나는 하나님이 나에게 주신 존귀함을 얼마나 깊이 인식하며 살고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/403'),
(404,'시편 19편: 하늘이 하나님의 영광을 선포함','구약','시편',19,'시 19:1-14',ARRAY['다윗']::text[],'다윗은 하늘이 하나님의 영광을 선포하고 궁창이 그의 손으로 하신 일을 나타낸다 노래하며, 여호와의 율법은 완전하여 영혼을 소성시킨다고 고백했다.','창조 세계와 말씀은 함께 하나님의 영광과 성품을 우리에게 증거해준다.',ARRAY['창조와 섭리','율법과 계명']::text[],'나는 자연과 말씀을 통해 하나님의 영광을 얼마나 발견하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/404'),
(405,'시편 27편: 여호와는 나의 빛','구약','시편',19,'시 27:1-14',ARRAY['다윗']::text[],'다윗은 여호와는 나의 빛이요 나의 구원이시니 누구를 두려워하리요 고백하며 환난 날에 주의 장막에 숨겨주실 것을 신뢰하고 강하고 담대하라 자신에게 권면했다.','여호와를 빛과 구원으로 삼는 사람은 어떤 두려운 상황 속에서도 담대할 수 있다.',ARRAY['고난과 인내','용기와 결단']::text[],'지금 나를 두렵게 하는 것 앞에서 나는 여호와를 나의 빛으로 삼고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/405'),
(406,'시편 32편: 죄를 자백함의 복','구약','시편',19,'시 32:1-11',ARRAY['다윗']::text[],'다윗은 자신의 죄를 숨겼을 때 뼈가 쇠하였으나 여호와께 자백하니 죄악을 사하셨다며, 허물의 사함을 받은 자가 복이 있다고 고백했다.','죄를 숨기는 것은 영혼을 병들게 하지만 정직한 자백은 참된 회복과 평안을 가져온다.',ARRAY['회개와 용서','죄와 타락']::text[],'나는 죄를 숨겨 마음이 무거웠던 경험과 자백 후의 자유함을 경험한 적이 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/406'),
(407,'시편 34편: 여호와를 항상 송축함','구약','시편',19,'시 34:1-22',ARRAY['다윗']::text[],'다윗은 어려운 상황 속에서도 여호와를 항상 송축하겠다 고백하며 이 곤고한 자가 부르짖으매 여호와께서 들으시고 그의 모든 환난에서 구원하셨다고 간증했다.','고난 중에도 하나님을 찬양하는 습관은 그 부르짖음에 응답하시는 하나님을 경험하게 한다.',ARRAY['고난과 인내','예배와 경배']::text[],'나는 어려운 상황 속에서도 하나님을 찬양하는 습관을 지니고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/407'),
(408,'시편 42편: 사슴이 시냇물을 찾기에 갈급함같이','구약','시편',19,'시 42:1-11',ARRAY['고라 자손']::text[],'시인은 사슴이 시냇물을 갈급하게 찾듯 내 영혼이 하나님을 갈급하게 찾는다 고백하며 낙심될 때마다 ''내 영혼아 어찌하여 낙심하며 어찌하여 불안해하는가 너는 하나님께 소망을 두라'' 자신을 격려했다.','영적 갈급함과 낙심 속에서도 스스로에게 소망을 두라 권면하는 것이 신앙의 성숙한 자기대화이다.',ARRAY['고난과 인내','예배와 경배']::text[],'나는 낙심될 때 내 영혼에게 소망의 말을 건네고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/408'),
(409,'시편 46편: 하나님은 우리의 피난처','구약','시편',19,'시 46:1-11',ARRAY['고라 자손']::text[],'시인은 하나님은 우리의 피난처시요 힘이시니 환난 중에 만날 큰 도움이시라 노래하며 땅이 변하고 산이 흔들려도 두려워하지 않겠다 고백하고 ''너희는 가만히 있어 내가 하나님 됨을 알지어다'' 하나님의 음성을 전했다.','극심한 혼란과 변화의 시대에도 하나님은 흔들리지 않는 견고한 피난처가 되신다.',ARRAY['인도하심과 보호','고난과 인내']::text[],'세상이 흔들리는 것 같은 시기에 나는 하나님을 피난처로 삼고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/409'),
(410,'시편 90편: 우리 날 계수함을 가르치소서','구약','시편',19,'시 90:1-17',ARRAY['모세']::text[],'모세는 하나님이 영원부터 영원까지 우리의 처소가 되셨음을 고백하며 우리 날 계수함을 가르쳐 지혜로운 마음을 얻게 해달라고 기도했다.','유한한 인생의 날들을 지혜롭게 계수하며 사는 것이 영원하신 하나님 앞에서의 참된 지혜이다.',ARRAY['지혜와 분별','창조와 섭리']::text[],'나는 유한한 내 인생의 날들을 얼마나 지혜롭게 계수하며 살고 있는가?',ARRAY['성인']::text[],'v2','/s/410'),
(411,'시편 91편: 지존자의 은밀한 곳','구약','시편',19,'시 91:1-16',ARRAY['시인']::text[],'시인은 지존자의 은밀한 곳에 거주하는 자는 전능자의 그늘 아래 사니 여호와는 나의 피난처요 요새라 고백하며 하나님을 사랑하는 자를 건지시고 높이시는 보호를 노래했다.','하나님의 날개 아래 거하는 자는 어떤 위험 속에서도 깊은 안전함을 누릴 수 있다.',ARRAY['인도하심과 보호','순종과 믿음']::text[],'나는 하나님의 보호하심 아래 거하는 안전함을 일상에서 실감하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/411'),
(412,'시편 100편: 감사함으로 그 문에 들어가며','구약','시편',19,'시 100:1-5',ARRAY['시인']::text[],'시인은 온 땅이여 여호와께 즐거이 부르라 기쁨으로 여호와를 섬기며 노래하며 그 앞에 나아갈지어다 하고 감사함으로 그 문에 들어가라 권면했다.','예배는 의무가 아니라 기쁨과 감사로 하나님께 나아가는 즐거운 축제이다.',ARRAY['예배와 경배']::text[],'나는 예배에 기쁨과 감사로 나아가고 있는가, 의무감으로 나아가고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/412'),
(413,'시편 103편: 내 영혼아 여호와를 송축하라','구약','시편',19,'시 103:1-22',ARRAY['다윗']::text[],'다윗은 내 영혼아 여호와를 송축하라 그의 모든 은택을 잊지 말라 하며 죄악을 사하시고 병을 고치시며 노하기를 더디하시는 하나님의 자비하심을 노래했다.','하나님의 크신 은혜를 하나하나 기억하며 감사하는 것은 영혼을 새롭게 하는 예배가 된다.',ARRAY['예배와 경배','하나님의 사랑']::text[],'나는 하나님이 내게 베푸신 구체적인 은택들을 얼마나 기억하며 감사하는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/413'),
(414,'시편 119편(발췌): 주의 말씀을 사랑함','구약','시편',19,'시 119:97-105',ARRAY['시인']::text[],'시편 중 가장 긴 시 119편에서 시인은 주의 법을 어찌 그리 사랑하는지 그것이 종일 나의 묵상이라 고백하며 주의 말씀은 내 발에 등이요 내 길에 빛이라 노래했다.','말씀을 향한 깊은 사랑과 묵상은 인생의 길을 밝히는 든든한 빛이 된다.',ARRAY['율법과 계명','순종과 믿음']::text[],'말씀이 내 삶의 등과 빛이 되고 있다는 것을 구체적으로 경험한 적이 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/414'),
(415,'시편 126편: 눈물을 흘리며 씨를 뿌리는 자','구약','시편',19,'시 126:1-6',ARRAY['시인']::text[],'포로에서 돌아온 기쁨을 노래하는 시인은 눈물을 흘리며 씨를 뿌리러 나가는 자는 반드시 기쁨으로 그 단을 가지고 돌아오리라 노래했다.','고난과 수고의 눈물은 결국 하나님이 예비하신 기쁨의 열매로 돌아온다.',ARRAY['고난과 인내','종말과 소망']::text[],'지금 눈물로 씨를 뿌리고 있는 영역이 있다면 어떤 기쁨의 추수를 소망할 수 있을까?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/415'),
(416,'시편 133편: 형제가 연합하여 동거함이','구약','시편',19,'시 133:1-3',ARRAY['다윗']::text[],'다윗은 형제가 연합하여 동거함이 어찌 그리 선하고 아름다운지 머리에 부은 보배로운 기름과 헐몬의 이슬이 시온의 산들에 내림 같다 노래하며 그곳에 하나님이 복을 명령하셨다 했다.','공동체 안의 연합과 화목은 하나님이 특별한 복을 명령하시는 아름다운 자리이다.',ARRAY['가정과 관계','교회와 공동체']::text[],'우리 공동체는 연합과 화목의 아름다움을 얼마나 누리고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/416'),
(417,'네 마음을 다하여 여호와를 신뢰하라','구약','잠언',20,'잠 3:1-12',ARRAY['솔로몬']::text[],'솔로몬은 아들에게 네 마음을 다하여 여호와를 신뢰하고 네 명철을 의지하지 말라, 범사에 그를 인정하라 그리하면 네 길을 지도하시리라 권면했다.','자신의 판단보다 하나님을 전적으로 신뢰하며 범사에 인정하는 것이 지혜로운 삶의 길이다.',ARRAY['순종과 믿음','지혜와 분별']::text[],'나는 내 명철보다 하나님을 더 신뢰하며 살고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/417'),
(418,'사람의 마음의 경영과 여호와의 인도','구약','잠언',20,'잠 16:1-9',ARRAY['솔로몬']::text[],'솔로몬은 마음의 경영은 사람에게 있어도 말의 응답은 여호와께로부터 나오며 사람이 마음으로 자기의 길을 계획할지라도 그의 걸음을 인도하시는 이는 여호와시라 가르쳤다.','우리가 계획을 세우더라도 결국 그 길을 인도하시는 분은 하나님이심을 겸손히 인정해야 한다.',ARRAY['지혜와 분별','인도하심과 보호']::text[],'나는 계획을 세울 때 하나님의 인도하심을 얼마나 겸손히 구하는가?',ARRAY['성인']::text[],'v2','/s/418'),
(419,'마땅히 행할 길을 아이에게 가르치라','구약','잠언',20,'잠 22:1-6',ARRAY['솔로몬']::text[],'솔로몬은 많은 재물보다 명예를 택할 것이며, 마땅히 행할 길을 아이에게 가르치라 그리하면 늙어도 그것을 떠나지 아니하리라 권면했다.','어릴 때부터 바른 길을 가르치는 훈련은 평생을 좌우하는 귀한 유산이 된다.',ARRAY['가정과 관계','지혜와 분별']::text[],'나는 다음 세대에게 마땅히 행할 길을 얼마나 의도적으로 가르치고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/419'),
(420,'나인성 과부의 아들을 살리심','신약','누가복음',42,'눅 7:11-17',ARRAY['예수님','나인성 과부']::text[],'나인성 성문에서 죽은 외아들을 메고 나오는 과부의 행렬을 만난 예수님이 그 어머니를 불쌍히 여겨 관에 손을 대시고 ''청년아 일어나라'' 명하시니 죽었던 아들이 살아나 어머니에게 돌려주셨다.','예수님은 가장 깊은 슬픔과 절망의 자리에도 찾아오셔서 긍휼로 생명을 회복시키신다.',ARRAY['예수님의 기적','하나님의 사랑']::text[],'가장 깊은 슬픔의 자리에서 나는 예수님의 긍휼을 경험한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/420'),
(421,'죄 많은 여자가 향유를 부음','신약','누가복음',42,'눅 7:36-50',ARRAY['예수님','죄 많은 여자','바리새인 시몬']::text[],'바리새인 시몬의 집에서 죄 많은 한 여자가 눈물로 예수님의 발을 적시고 향유를 부으며 입 맞추니, 예수님은 그의 많은 죄가 사함받았음을 그 큰 사랑으로 알 수 있다 말씀하셨다.','많이 용서받은 자는 그만큼 더 크고 진실한 사랑으로 반응하게 된다.',ARRAY['회개와 용서','사랑과 섬김']::text[],'나는 용서받은 은혜의 크기만큼 사랑으로 반응하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/421'),
(422,'안식일에 손 마른 사람을 고치심','신약','마가복음',41,'막 3:1-6',ARRAY['예수님','손 마른 사람','바리새인들']::text[],'안식일에 회당에서 손 마른 사람을 본 예수님이 ''선을 행하는 것과 악을 행하는 것, 생명을 구하는 것과 죽이는 것 중 어느 것이 옳으냐'' 물으시고 그의 손을 고쳐주시니 바리새인들은 오히려 그를 죽이려 의논했다.','형식적인 규례에 갇혀 생명을 살리는 선한 일조차 반대하는 완악함을 경계해야 한다.',ARRAY['율법과 계명','사랑과 섬김']::text[],'나는 형식과 생명을 살리는 사랑 중 무엇을 더 중요하게 여기는가?',ARRAY['청소년','성인']::text[],'v2','/s/422'),
(423,'안식일에 꼽추 여인을 고치심','신약','누가복음',42,'눅 13:10-17',ARRAY['예수님','꼽추 여인','회당장']::text[],'열여덟 해 동안 꼬부라져 펴지 못하던 여인을 안식일에 고치신 예수님은 짐승도 안식일에 물을 먹이면서 어찌 아브라함의 딸을 매임에서 풀어주지 못하겠느냐며 회당장의 위선을 지적하셨다.','오랜 세월 묶여 있던 고통에서 자유케 하는 것이야말로 안식일의 참된 정신이다.',ARRAY['예수님의 기적','인도하심과 보호']::text[],'나는 오랫동안 나를 묶고 있던 것으로부터 자유케 하시는 예수님을 경험한 적이 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/423'),
(424,'세례요한의 질문과 예수님의 응답','신약','마태복음',40,'마 11:1-19',ARRAY['세례요한','예수님','요한의 제자들']::text[],'옥에 갇힌 세례요한이 제자들을 보내 ''오실 그이가 당신이오니이까'' 묻자 예수님은 맹인이 보고 못 걷는 자가 걸으며 복음이 가난한 자에게 전파됨을 전하며 자신이 나로 말미암아 실족하지 않는 자가 복되다 하셨다.','의심과 혼란의 순간에도 예수님은 우리의 질문을 외면하지 않으시고 명확한 증거로 응답하신다.',ARRAY['순종과 믿음','예수 그리스도의 정체성']::text[],'의심이 들 때 나는 예수님께 정직하게 질문하고 응답을 구하는가?',ARRAY['청소년','성인']::text[],'v2','/s/424'),
(425,'생명의 떡 강화','신약','요한복음',43,'요 6:22-59',ARRAY['예수님','무리']::text[],'오병이어의 기적 후 예수님을 다시 찾아온 무리에게 예수님은 자신이 하늘에서 내려온 생명의 떡이니 이 떡을 먹는 자는 영원히 살리라 말씀하시며 육신의 양식이 아닌 영원한 생명을 구하라 가르치셨다.','세상의 필요를 채워주시는 예수님은 그보다 더 근본적인 영원한 생명의 양식이 되신다.',ARRAY['예수 그리스도의 정체성','순종과 믿음']::text[],'나는 육신의 필요와 영원한 생명의 양식 중 무엇을 더 갈급해 하는가?',ARRAY['청소년','성인']::text[],'v2','/s/425'),
(426,'열매 없는 무화과나무 비유','신약','누가복음',42,'눅 13:1-9',ARRAY['예수님','포도원지기']::text[],'예수님은 삼 년째 열매 맺지 못한 무화과나무를 찍어버리려는 주인에게 포도원지기가 한 해만 더 기다려달라 간청하는 비유로 회개할 기회와 시간의 소중함을 가르치셨다.','하나님은 열매 없는 삶에도 인내하시며 회개할 기회를 계속 허락하시지만 그 시간은 무한하지 않다.',ARRAY['회개와 용서','고난과 인내']::text[],'나는 주어진 은혜의 시간 동안 회개와 열매 맺는 삶으로 반응하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/426'),
(427,'불의한 청지기 비유','신약','누가복음',42,'눅 16:1-13',ARRAY['예수님','불의한 청지기']::text[],'해고를 앞둔 청지기가 주인의 빚진 자들의 빚을 줄여주며 장래를 지혜롭게 대비한 비유를 통해 예수님은 세상의 재물을 영원한 것을 위해 지혜롭게 사용하라 가르치셨다.','이 세상의 자원을 하나님 나라의 영원한 가치를 위해 지혜롭게 활용하는 것이 신실한 청지기의 자세이다.',ARRAY['지혜와 분별','사랑과 섬김']::text[],'나는 내게 맡겨진 재물과 자원을 영원한 가치를 위해 지혜롭게 사용하고 있는가?',ARRAY['성인']::text[],'v2','/s/427'),
(428,'참포도나무 비유','신약','요한복음',43,'요 15:1-17',ARRAY['예수님','제자들']::text[],'예수님은 자신을 참포도나무로, 아버지를 농부로 소개하시며 가지인 우리가 나무에 붙어 있어야 많은 열매를 맺을 수 있고 나를 떠나서는 아무것도 할 수 없다 말씀하셨다.','그리스도 안에 거하는 것이 풍성한 영적 열매를 맺는 유일한 길이다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나는 날마다 그리스도 안에 거하는 삶을 살고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/428'),
(429,'신실한 종과 악한 종 비유','신약','마태복음',40,'마 24:45-51',ARRAY['예수님','제자들']::text[],'예수님은 주인이 돌아올 때 맡겨진 일을 신실하게 하고 있는 종과, 주인이 더디 오리라 여기며 방탕하게 지내는 악한 종을 대조하며 늘 깨어 준비하라 가르치셨다.','주님의 재림을 기다리는 삶은 오늘 맡겨진 일에 신실하게 최선을 다하는 것으로 나타나야 한다.',ARRAY['종말과 소망','충성과 신실함']::text[],'나는 주님이 오늘 오신다면 부끄럽지 않을 만큼 신실하게 살고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/429'),
(430,'기도를 가르치심(구하라 찾으라 두드리라)','신약','누가복음',42,'눅 11:1-13',ARRAY['예수님','제자들']::text[],'제자들이 기도를 가르쳐달라 하자 예수님은 주기도문을 가르치시고 구하라 그리하면 주실 것이요 찾으라 그리하면 찾을 것이요 두드리라 그리하면 열릴 것이라며 좋은 것을 주시는 아버지의 마음을 설명하셨다.','하나님 아버지는 자녀가 간절히 구하는 것에 기꺼이 좋은 것으로 응답하기를 원하신다.',ARRAY['기도와 응답','하나님의 사랑']::text[],'나는 구하고 찾고 두드리는 간절함으로 기도하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/430'),
(431,'성령을 훼방하는 죄에 대한 경고','신약','마태복음',40,'마 12:22-32',ARRAY['예수님','바리새인들']::text[],'귀신 들려 눈멀고 벙어리 된 자를 고치신 예수님을 바리새인들이 귀신의 왕을 힘입은 것이라 모함하자, 예수님은 성령을 훼방하는 말은 사하심을 얻지 못한다 엄히 경고하셨다.','선한 일을 악하다 고집스럽게 왜곡하는 완악한 마음은 회개의 길을 스스로 막아버릴 수 있다.',ARRAY['죄와 타락','지혜와 분별']::text[],'나는 선한 것을 선한 것으로 인정하는 열린 마음을 가지고 있는가?',ARRAY['성인']::text[],'v2','/s/431'),
(432,'야고보와 요한의 요청, 섬기는 자가 되라','신약','마가복음',41,'막 10:35-45',ARRAY['야고보','요한','예수님','다른 제자들']::text[],'야고보와 요한이 영광의 자리를 구하자 다른 제자들이 분개했고, 예수님은 너희 중에 누구든지 크고자 하는 자는 섬기는 자가 되어야 한다며 자신도 섬기려고 자기 목숨을 대속물로 주려 왔다 말씀하셨다.','진정한 위대함은 높아짐이 아니라 자신을 내어주는 섬김으로 나타난다.',ARRAY['겸손과 교만','사랑과 섬김']::text[],'나는 높아지려는 마음과 섬기려는 마음 중 무엇이 더 큰가?',ARRAY['청소년','성인']::text[],'v2','/s/432'),
(433,'내가 곧 길이요 진리요 생명이니','신약','요한복음',43,'요 14:1-14',ARRAY['예수님','제자들','도마','빌립']::text[],'마음에 근심하지 말라 하신 예수님은 아버지 집에 거할 곳을 예비하러 가신다 위로하시며 ''내가 곧 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라'' 선포하셨다.','예수님은 하나님께 나아가는 유일하고 완전한 길이시며 우리 마음의 근심을 잠재우는 소망이시다.',ARRAY['예수 그리스도의 정체성','종말과 소망']::text[],'마음에 근심이 있을 때 나는 이 약속의 말씀으로 위로받고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/433'),
(434,'사울이 다메섹과 예루살렘에서 전도함','신약','사도행전',44,'행 9:20-31',ARRAY['사울','다메섹의 유대인들','바나바']::text[],'회심한 사울이 즉시 회당에서 예수가 하나님의 아들이심을 전파하니 유대인들이 그를 죽이려 했고, 예루살렘에서도 제자들이 두려워하자 바나바가 그를 받아들여 사도들에게 소개했다.','급진적인 변화를 겪은 사람을 향한 의심을 넘어 신뢰로 받아들이는 중재자의 역할이 공동체에 필요하다.',ARRAY['전도와 선교','교회와 공동체']::text[],'나는 변화된 사람을 의심하기보다 바나바처럼 신뢰로 받아들이고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/434'),
(435,'아볼로의 사역','신약','사도행전',44,'행 18:24-28',ARRAY['아볼로','브리스길라','아굴라']::text[],'성경에 능통했던 아볼로가 요한의 세례만 알고 열정적으로 전도하자, 브리스길라와 아굴라 부부가 그를 데려다가 하나님의 도를 더 정확하게 풀어 가르쳤다.','이미 은사가 뛰어난 사람이라도 겸손히 배우고 더 정확한 진리로 성장할 수 있어야 한다.',ARRAY['지혜와 분별','교회와 공동체']::text[],'나는 이미 잘 안다고 여기는 부분에서도 겸손히 더 배우려는 태도를 가지고 있는가?',ARRAY['성인']::text[],'v2','/s/435'),
(436,'이스라엘을 향한 바울의 안타까움','신약','로마서',45,'롬 9:1-5,11:25-36',ARRAY['바울','이스라엘 백성']::text[],'동족 이스라엘의 구원을 위해서라면 자신이 저주를 받아도 좋다고 할 만큼 안타까워한 바울은 하나님의 지혜와 지식의 풍성함, 그 판단의 헤아리지 못할 것을 찬양하며 이 부분을 마무리했다.','동족과 사랑하는 이들의 구원을 향한 간절한 마음은 깊은 기도와 눈물로 이어져야 한다.',ARRAY['기도와 응답','사랑과 섬김']::text[],'나는 아직 믿지 않는 가족이나 동족을 위해 바울처럼 간절히 마음 아파하는가?',ARRAY['성인']::text[],'v2','/s/436'),
(437,'형제를 비판하지 말라','신약','로마서',45,'롬 14:1-13',ARRAY['바울','로마 교회']::text[],'음식이나 날을 지키는 문제로 서로 다르게 확신하는 성도들에게 바울은 각자 자기 마음으로 확정할 것이며 형제를 비판하거나 업신여기지 말라 권면하며 모든 사람은 하나님 앞에 서게 될 것이라 가르쳤다.','신앙의 자유로운 영역에서는 서로 다른 확신을 존중하며 함부로 판단하지 않아야 한다.',ARRAY['시기와 갈등','교회와 공동체']::text[],'나는 나와 다른 신앙적 확신을 가진 형제를 함부로 판단한 적은 없는가?',ARRAY['성인']::text[],'v2','/s/437'),
(438,'몸은 성령의 전','신약','고린도전서',46,'고전 6:12-20',ARRAY['바울','고린도 교회']::text[],'바울은 성도의 몸이 성령이 거하시는 전임을 강조하며 음행을 피하고 값으로 산 것이 되었으니 그 몸으로 하나님께 영광을 돌리라 권면했다.','우리의 몸은 성령이 거하시는 거룩한 처소이니 그에 합당한 삶으로 하나님께 영광을 돌려야 한다.',ARRAY['예배와 경배','순종과 믿음']::text[],'나는 내 몸을 성령이 거하시는 거룩한 처소로 여기며 살고 있는가?',ARRAY['성인']::text[],'v2','/s/438'),
(439,'주의 만찬의 규례','신약','고린도전서',46,'고전 11:23-34',ARRAY['바울','고린도 교회']::text[],'바울은 주께 받은 것을 전한다며 최후의 만찬에서 예수님이 떡과 잔으로 자신을 기념하라 하신 말씀을 전하고, 합당하지 않게 참여하는 것을 경계하며 자신을 살피고 성찬에 참여하라 가르쳤다.','성찬에 참여하기 전 자신을 돌아보며 합당한 마음가짐으로 나아가는 것이 중요하다.',ARRAY['예배와 경배','회개와 용서']::text[],'나는 성찬에 참여하기 전 내 마음을 얼마나 신중히 살피는가?',ARRAY['성인']::text[],'v2','/s/439'),
(440,'그리스도 안에서 하나 됨','신약','갈라디아서',48,'갈 3:23-29',ARRAY['바울']::text[],'바울은 믿음이 온 후로는 율법의 감독 아래 있지 않다며 누구든지 그리스도와 합하여 세례를 받은 자는 유대인이나 헬라인이나 종이나 자유인이나 남자나 여자나 다 그리스도 예수 안에서 하나라 선포했다.','그리스도 안에서는 세상의 모든 신분과 차별의 장벽이 사라지고 온전한 하나 됨을 이룬다.',ARRAY['교회와 공동체','사랑과 섬김']::text[],'나는 그리스도 안에서 신분과 배경을 넘어선 하나 됨을 실천하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/440'),
(441,'그리스도와 교회, 부부의 관계','신약','에베소서',49,'엡 5:22-33',ARRAY['바울']::text[],'바울은 남편에게 그리스도가 교회를 사랑하여 자신을 주심같이 아내를 사랑하라 하고 아내에게는 교회가 그리스도께 하듯 남편에게 순종하라 권면하며 이 비밀이 그리스도와 교회에 대한 것이라 설명했다.','결혼 관계는 그리스도와 교회의 희생적 사랑과 순종의 관계를 반영하는 거룩한 그림이다.',ARRAY['가정과 관계','사랑과 섬김']::text[],'우리 부부(혹은 가정)의 관계는 그리스도와 교회의 사랑을 얼마나 반영하고 있는가?',ARRAY['성인']::text[],'v2','/s/441'),
(442,'푯대를 향하여 달려감','신약','빌립보서',50,'빌 3:7-14',ARRAY['바울']::text[],'바울은 무엇이든지 내게 유익하던 것을 그리스도를 위해 다 해로 여긴다 고백하며 뒤에 있는 것은 잊어버리고 푯대를 향하여 그리스도 예수 안에서 하나님이 위에서 부르신 부름의 상을 위해 좇아간다 고백했다.','과거의 성취나 실패에 머물지 않고 그리스도를 아는 지식을 향해 계속 나아가는 것이 성숙한 신앙이다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 과거에 머물지 않고 그리스도를 향한 푯대를 좇아 나아가고 있는가?',ARRAY['성인']::text[],'v2','/s/442'),
(443,'세상과 벗됨은 하나님과 원수 됨','신약','야고보서',59,'약 4:1-10',ARRAY['야고보']::text[],'야고보는 성도들 사이의 다툼이 정욕에서 비롯된다 지적하며 세상과 벗 됨이 하나님과 원수 됨이라 경고하고 하나님을 가까이하면 하나님도 가까이하시리라 하며 겸손히 주 앞에서 낮추라 권면했다.','세상적 욕심을 내려놓고 하나님께 온전히 순복하는 겸손함이 참된 신앙의 자리이다.',ARRAY['겸손과 교만','시기와 갈등']::text[],'나는 세상적 욕심과 하나님을 향한 순복 중 어느 쪽으로 더 기울어 있는가?',ARRAY['성인']::text[],'v2','/s/443'),
(444,'병든 자를 위한 기도','신약','야고보서',59,'약 5:13-18',ARRAY['야고보']::text[],'야고보는 병든 자가 있으면 교회의 장로들을 청하여 기름을 바르며 기도할 것을 권면하고 믿음의 기도는 병든 자를 구원하리라 하며 의인의 간구는 역사하는 힘이 크다고 가르쳤다.','공동체가 함께 드리는 간절한 기도는 병든 자를 향한 하나님의 치유와 회복을 이끌어낼 수 있다.',ARRAY['기도와 응답','교회와 공동체']::text[],'나는 아픈 이를 위해 공동체와 함께 간절히 기도하고 있는가?',ARRAY['성인']::text[],'v2','/s/444'),
(445,'아내와 남편에게 주는 권면','신약','베드로전서',60,'벧전 3:1-7',ARRAY['베드로']::text[],'베드로는 아내들에게 순종함으로 말없는 행실로 남편을 얻게 하는 정결한 삶을, 남편들에게는 아내를 더 연약한 그릇으로 여겨 지식을 따라 귀히 여기라 권면했다.','부부 관계 속에서 서로를 존중하고 배려하는 삶은 신앙의 향기를 드러내는 구체적인 실천이다.',ARRAY['가정과 관계','사랑과 섬김']::text[],'나는 가정에서 배우자를 얼마나 존중하고 귀히 여기고 있는가?',ARRAY['성인']::text[],'v2','/s/445'),
(446,'형제 사랑과 나그네 대접','신약','히브리서',58,'히 13:1-6',ARRAY['저자','성도들']::text[],'히브리서 저자는 형제 사랑하기를 계속하고 나그네 대접하기를 잊지 말라며 이로써 부지중에 천사들을 대접한 이들도 있었다 하고, 돈을 사랑하지 말고 있는 바를 족한 줄로 알라 권면했다.','일상적인 환대와 자족하는 삶은 신앙 공동체가 세상에 보여주는 구체적인 사랑의 증거이다.',ARRAY['사랑과 섬김','가정과 관계']::text[],'나는 나그네와 낯선 이를 환대하는 일에 얼마나 열려 있는가?',ARRAY['성인']::text[],'v2','/s/446'),
(447,'세상을 이기는 승리는 우리의 믿음','신약','요한일서',62,'요일 5:1-5',ARRAY['요한']::text[],'요한은 예수를 하나님의 아들로 믿는 자마다 하나님께로부터 났다 하며 세상을 이기는 승리는 이것이니 우리의 믿음이라 선포했다.','세상의 유혹과 시련을 이기는 참된 힘의 근원은 그리스도를 향한 굳건한 믿음이다.',ARRAY['순종과 믿음','고난과 인내']::text[],'나는 세상을 이기는 힘의 근원을 어디에서 찾고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/447'),
(448,'야곱의 자녀들이 출생함','구약','창세기',1,'창 29:31-30:24',ARRAY['야곱','레아','라헬','빌하','실바']::text[],'레아와 라헬, 그리고 두 여종을 통해 야곱이 열두 아들과 딸 디나를 얻는 과정에서 자매간의 경쟁과 하나님을 향한 감사가 아들들의 이름에 담겼다.','가정 안의 경쟁과 아픔 속에서도 하나님은 이스라엘 열두 지파를 이루시는 계획을 이루어가셨다.',ARRAY['가정과 관계','하나님의 섭리']::text[],'가정 안의 아픔이나 경쟁 속에서도 하나님의 더 큰 계획을 신뢰할 수 있는가?',ARRAY['성인']::text[],'v2','/s/448'),
(449,'여호와의 이름과 속성을 선포하심','구약','출애굽기',2,'출 34:5-9',ARRAY['모세','하나님']::text[],'시내산에서 하나님이 모세 앞으로 지나가시며 ''여호와라 여호와라 자비롭고 은혜롭고 노하기를 더디하고 인자와 진실이 많은 하나님''이라 자신의 이름과 성품을 선포하셨다.','하나님을 아는 지식의 핵심은 그분의 자비와 은혜, 인자하심에 있다.',ARRAY['하나님의 사랑','예배와 경배']::text[],'나는 하나님을 심판자로만 아는가, 자비와 은혜의 하나님으로도 깊이 아는가?',ARRAY['청소년','성인']::text[],'v2','/s/449'),
(450,'북이스라엘의 멸망','구약','열왕기하',12,'왕하 17:1-23',ARRAY['호세아 왕','앗수르 왕','이스라엘 백성']::text[],'오랜 우상숭배와 불순종 끝에 북이스라엘은 앗수르에게 정복당해 멸망하고 백성은 포로로 흩어졌으니, 이는 하나님의 거듭된 경고를 듣지 않은 결과였다.','반복된 경고에도 돌이키지 않는 불순종은 결국 공동체 전체의 멸망으로 이어질 수 있다.',ARRAY['하나님의 심판','우상숭배 경계']::text[],'우리 공동체나 나라가 반복해서 듣고도 무시하는 경고는 없는지 살펴보자.',ARRAY['성인']::text[],'v2','/s/450'),
(451,'여호와의 책망과 회복의 약속','구약','이사야',23,'사 1:1-20',ARRAY['이사야','이스라엘 백성']::text[],'이사야는 형식적 제사만 드리며 불의를 행하는 백성을 책망하며 ''오라 우리가 서로 변론하자 너희 죄가 주홍 같을지라도 눈과 같이 희어질 것이요'' 회개하면 주어질 회복을 약속했다.','아무리 깊은 죄라도 진실한 회개 앞에서는 완전한 정결함으로 바뀔 수 있다.',ARRAY['회개와 용서','하나님의 심판']::text[],'나는 내 죄가 너무 깊어 용서받을 수 없다고 여긴 적은 없는가?',ARRAY['성인']::text[],'v2','/s/451'),
(452,'새 하늘과 새 땅에 대한 예언','구약','이사야',23,'사 65:17-25',ARRAY['이사야','하나님']::text[],'이사야는 하나님이 새 하늘과 새 땅을 창조하실 것이며 그곳에는 다시 우는 소리와 부르짖는 소리가 들리지 않고 이리와 어린 양이 함께 먹을 것이라 예언했다.','구약의 선지자들도 이미 고통 없는 영원한 회복의 나라를 바라보며 소망을 노래했다.',ARRAY['종말과 소망','하나님의 구원']::text[],'구약에서부터 이어져 온 새 하늘과 새 땅의 소망이 오늘 내게 주는 위로는 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/452'),
(453,'선한 목자와 악한 목자','구약','에스겔',26,'겔 34:1-31',ARRAY['에스겔','하나님','이스라엘의 목자들']::text[],'자기 배만 채우고 양떼를 돌보지 않은 이스라엘의 목자들을 책망하신 하나님은 자신이 친히 목자가 되어 잃어버린 자를 찾고 상한 자를 싸매어 주시겠다 약속하셨다.','참된 지도자는 자신의 유익이 아니라 맡겨진 이들을 향한 헌신적인 돌봄으로 평가받는다.',ARRAY['지도자의 리더십','사랑과 섬김']::text[],'나는 맡겨진 사람들을 목자의 심정으로 돌보고 있는가?',ARRAY['성인']::text[],'v2','/s/453'),
(454,'성전에서 흘러나오는 생명의 강','구약','에스겔',26,'겔 47:1-12',ARRAY['에스겔','천사']::text[],'에스겔이 환상 중에 성전 문지방 밑에서 흘러나오는 물이 점점 깊어져 강을 이루고 그 물이 이르는 곳마다 생물이 살고 나무 잎사귀가 치료제가 되는 것을 보았다.','하나님의 임재로부터 흘러나오는 생명은 닿는 모든 곳에 회복과 치유를 가져온다.',ARRAY['하나님의 구원','종말과 소망']::text[],'하나님의 임재가 내 삶과 주변에 어떤 생명력과 치유를 가져오고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/454'),
(455,'여호와께로 돌아가자','구약','호세아',28,'호 14:1-9',ARRAY['호세아','이스라엘 백성']::text[],'호세아는 이스라엘에게 여호와께로 돌아가자 권면하며 하나님이 그들의 반역을 고치시고 이슬같이 되사 백합화같이 피어나게 하시겠다는 회복의 약속을 전했다.','진심으로 돌아오는 자에게 하나님은 이슬처럼 신선한 회복과 풍성한 생명을 허락하신다.',ARRAY['회개와 용서','하나님의 사랑']::text[],'나는 하나님께 돌아가는 것을 미루고 있는 부분은 없는가?',ARRAY['청소년','성인']::text[],'v2','/s/455'),
(456,'다윗의 무너진 장막을 다시 일으키리라','구약','아모스',30,'암 9:11-15',ARRAY['아모스','하나님']::text[],'아모스는 심판의 메시지 끝에 하나님이 다윗의 무너진 장막을 다시 일으키시고 포로된 백성을 다시 돌아오게 하여 그 땅에서 다시는 뽑히지 않게 하시겠다 약속하며 마무리했다.','가장 엄중한 심판의 메시지 끝에도 하나님은 언제나 회복의 소망을 남겨두신다.',ARRAY['하나님의 심판','종말과 소망']::text[],'가장 어두운 심판의 메시지 속에서도 나는 회복의 소망을 붙들 수 있는가?',ARRAY['성인']::text[],'v2','/s/456'),
(457,'제자도의 대가','신약','마태복음',40,'마 8:18-22,눅 9:57-62',ARRAY['예수님','서기관','제자 후보들']::text[],'예수님을 따르겠다는 사람들에게 예수님은 여우도 굴이 있고 새도 집이 있으되 인자는 머리 둘 곳이 없다 하시며, 아버지를 장사한 후 따르겠다는 이에게도 죽은 자들이 죽은 자를 장사하게 하라며 즉각적인 헌신을 요구하셨다.','예수님을 따르는 길은 편안함이 보장된 길이 아니라 모든 것을 제쳐두는 즉각적이고 전적인 헌신을 요구한다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 예수님을 따르는 데 있어 무엇을 핑계로 미루고 있지는 않은가?',ARRAY['청소년','성인']::text[],'v2','/s/457'),
(458,'대제사장적 기도','신약','요한복음',43,'요 17:1-26',ARRAY['예수님','아버지 하나님','제자들']::text[],'십자가를 앞둔 마지막 밤, 예수님은 자신의 영광과 제자들의 보호, 그리고 장차 믿을 모든 사람들이 하나 되게 해달라고 아버지께 간절히 기도하셨다.','예수님의 마지막 기도의 중심은 자신의 안위가 아니라 제자들의 보호와 성도의 하나 됨이었다.',ARRAY['기도와 응답','교회와 공동체']::text[],'나는 나 자신보다 공동체의 하나 됨과 보호를 위해 얼마나 기도하는가?',ARRAY['성인']::text[],'v2','/s/458'),
(459,'하나님의 동역자, 하나님의 밭과 집','신약','고린도전서',46,'고전 3:1-15',ARRAY['바울','아볼로','고린도 교회']::text[],'바울과 아볼로 중 누구를 따르느냐로 분쟁하던 고린도 교회에게 바울은 심는 자와 물 주는 자는 아무것도 아니요 오직 자라나게 하시는 하나님만이 중요하다며 우리는 하나님의 동역자라 가르쳤다.','사역자를 우상화하기보다 오직 자라게 하시는 하나님께 영광을 돌리는 것이 건강한 신앙 공동체이다.',ARRAY['교회와 공동체','겸손과 교만']::text[],'나는 특정 사람이 아닌 하나님께 영광을 돌리는 신앙을 가지고 있는가?',ARRAY['성인']::text[],'v2','/s/459'),
(460,'선한 일에 힘쓰는 성도','신약','디도서',56,'딛 3:1-8',ARRAY['바울','디도']::text[],'바울은 디도에게 성도들이 위에 있는 자들에게 복종하고 모든 사람에게 온유함을 나타내라 권면하며 우리도 전에는 어리석었으나 성령으로 새롭게 하심을 입어 선한 일에 힘쓰게 되었다 가르쳤다.','은혜로 새로워진 성도의 정체성은 세상 속에서 구체적인 선행과 겸손한 관계로 드러나야 한다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나는 새로워진 은혜에 합당하게 선한 일에 힘쓰고 있는가?',ARRAY['성인']::text[],'v2','/s/460'),
(461,'각각 자기 직분을 다하라','신약','디모데후서',55,'딤후 2:1-13',ARRAY['바울','디모데']::text[],'바울은 디모데에게 예수 그리스도 안에 있는 은혜 가운데서 강하고, 좋은 군사와 경기하는 자, 수고하는 농부처럼 각자의 자리에서 최선을 다하라 권면하며 우리가 죽었으면 함께 살고 참으면 함께 왕 노릇 하리라 격려했다.','신앙의 삶은 군사와 운동선수, 농부처럼 각자의 자리에서 성실하게 최선을 다하는 훈련의 연속이다.',ARRAY['충성과 신실함','고난과 인내']::text[],'나는 내게 맡겨진 자리에서 군사와 농부처럼 성실히 최선을 다하고 있는가?',ARRAY['성인']::text[],'v2','/s/461'),
(462,'쉬지 말고 기도하라','신약','데살로니가전서',52,'살전 5:12-24',ARRAY['바울','데살로니가 교회']::text[],'바울은 데살로니가 성도들에게 항상 기뻐하라, 쉬지 말고 기도하라, 범사에 감사하라 권면하며 성령을 소멸하지 말고 범사에 헤아려 좋은 것을 취하라 당부했다.','기쁨과 기도와 감사는 상황에 좌우되지 않고 끊임없이 이어가야 할 신앙의 생활 습관이다.',ARRAY['기도와 응답','예배와 경배']::text[],'나는 기뻐함과 기도와 감사를 일상의 습관으로 얼마나 실천하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/462'),
(463,'성경의 마지막 경고와 축복','신약','요한계시록',66,'계 22:6-16',ARRAY['요한','예수 그리스도','천사']::text[],'천사는 이 책의 예언의 말씀을 인봉하지 말라 하였고 예수님은 ''보라 내가 속히 오리니 내가 줄 상이 내게 있어 각 사람에게 그가 행한 대로 갚아 주리라'' 거듭 약속하시며 자신을 알파와 오메가, 처음과 나중이라 선포하셨다.','성경 전체의 결론은 반드시 다시 오실 그리스도를 향한 확실한 소망과 그에 합당한 삶의 촉구이다.',ARRAY['종말과 소망','예수 그리스도의 정체성']::text[],'''내가 속히 오리라''는 약속을 기다리며 나는 오늘 어떤 삶을 살아야 하는가?',ARRAY['청소년','성인']::text[],'v2','/s/463'),
(464,'가인의 후손과 라멕의 노래','구약','창세기',1,'창 4:17-24',ARRAY['가인','라멕','에녹']::text[],'가인의 후손 중 문명(성읍 건축, 가축 치기, 악기, 기술)이 발전했으나 라멕은 자신의 상처에 대해 과도한 복수를 노래하며 죄악이 더욱 깊어지는 모습을 보였다.','문명과 기술의 발전이 반드시 도덕적 성숙을 의미하지는 않으며, 오히려 죄가 더 교묘해질 수 있다.',ARRAY['죄와 타락','분노 다스림']::text[],'나는 발전과 성취 속에서도 마음의 죄성을 경계하고 있는가?',ARRAY['성인']::text[],'v2','/s/464'),
(465,'에서의 후손(에돔)','구약','창세기',1,'창 36:1-8',ARRAY['에서','에돔 족속']::text[],'야곱과 갈라선 에서는 가나안을 떠나 세일산으로 가서 살았으며 그의 후손이 에돔 족속을 이루었다.','하나님의 언약 계보 밖에 있어도 각 사람에게는 나름의 역사와 자리가 있음을 성경은 기록한다.',ARRAY['가정과 관계','하나님의 섭리']::text[],'하나님의 특별한 부르심의 길과 그렇지 않은 삶의 길을 어떻게 이해할 수 있을까?',ARRAY['성인']::text[],'v2','/s/465'),
(466,'반석에서 물이 남(르비딤)','구약','출애굽기',2,'출 17:1-7',ARRAY['모세','이스라엘 백성','하나님']::text[],'목마른 백성이 원망하자 하나님은 모세에게 지팡이로 반석을 치라 명하시니 물이 솟아나 백성이 마셨고, 그곳을 맛사와 므리바라 불렀다.','불평과 원망 속에서도 하나님은 필요를 채우시는 신실하심으로 반응하신다.',ARRAY['인도하심과 보호','순종과 믿음']::text[],'나는 결핍의 순간에 원망보다 하나님께 구하는 믿음으로 반응하는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/466'),
(467,'아론의 지팡이에 싹이 남','구약','민수기',4,'민 17:1-13',ARRAY['아론','모세','이스라엘 백성']::text[],'각 지파의 지팡이 중 레위 지파를 대표한 아론의 지팡이에서만 싹이 나고 꽃이 피고 살구 열매가 열려 하나님이 아론을 제사장으로 택하셨음이 확증되었다.','하나님이 세우신 직분은 사람의 다툼이 아니라 그분의 살아있는 증거로 확증된다.',ARRAY['지도자의 리더십','하나님의 섭리']::text[],'나는 하나님이 세우신 질서와 직분을 인정하고 존중하는가?',ARRAY['성인']::text[],'v2','/s/467'),
(468,'비느하스의 열심','구약','민수기',4,'민 25:1-18',ARRAY['비느하스','모세','이스라엘 백성']::text[],'이스라엘 백성이 모압 여인들과 음행하며 바알을 섬기자 전염병이 임했고, 제사장 비느하스가 죄악을 단호히 처리하는 열심을 보이니 하나님이 그 열심을 칭찬하시며 평화의 언약을 주셨다.','죄악에 대한 단호한 거절과 열심은 때로 공동체 전체를 재앙에서 구하는 역할을 한다.',ARRAY['순종과 믿음','우상숭배 경계']::text[],'나는 죄악 앞에서 타협하지 않는 단호함을 가지고 있는가?',ARRAY['성인']::text[],'v2','/s/468'),
(469,'드보라의 노래','구약','사사기',7,'삿 5:1-31',ARRAY['드보라','바락','야엘']::text[],'시스라를 물리친 승리 후 드보라와 바락이 함께 부른 승전가는 하나님의 도우심과 헌신적으로 싸운 지파들, 야엘의 용기를 찬양하며 여호와를 사랑하는 자들은 해가 힘 있게 돋음 같으라 노래했다.','승리 후에는 사람의 공로가 아니라 하나님께 영광을 돌리는 찬양이 마땅히 뒤따라야 한다.',ARRAY['예배와 경배','용기와 결단']::text[],'나는 승리와 성공의 순간에 하나님께 영광을 돌리는 찬양을 잊지 않는가?',ARRAY['성인']::text[],'v2','/s/469'),
(470,'사무엘이 백성 앞에서 결백을 증언함','구약','사무엘상',9,'삼상 12:1-5',ARRAY['사무엘','이스라엘 백성']::text[],'늙어 물러나는 사무엘이 백성 앞에서 자신이 누구의 소나 나귀를 빼앗거나 누구를 속이거나 뇌물을 받은 일이 없음을 증언하니 백성도 그것을 인정했다.','오랜 세월 섬긴 지도자가 떠날 때 정직함으로 떳떳이 설 수 있다는 것은 참으로 귀한 신뢰의 유산이다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 내가 맡은 자리를 떠날 때 떳떳하게 설 수 있는 정직함을 쌓고 있는가?',ARRAY['성인']::text[],'v2','/s/470'),
(471,'다윗이 인구를 조사하여 재앙이 임함','구약','사무엘하',10,'삼하 24:1-25',ARRAY['다윗','갓 선지자','하나님']::text[],'다윗이 교만한 마음으로 군사력을 확인하려 인구조사를 하자 하나님이 전염병으로 심판하셨고, 다윗은 오르난의 타작마당에서 제단을 쌓아 재앙을 그치게 했다.','자신의 힘과 능력을 의지하려는 교만은 하나님과의 관계를 흔드는 심각한 죄가 될 수 있다.',ARRAY['겸손과 교만','회개와 용서']::text[],'나는 나의 능력과 자원을 의지하려는 교만을 경계하고 있는가?',ARRAY['성인']::text[],'v2','/s/471'),
(472,'엘리야가 바알 선지자들과 대결하기 전 기도','구약','열왕기상',11,'왕상 18:36-40',ARRAY['엘리야','이스라엘 백성']::text[],'갈멜산에서 제물을 쌓은 엘리야는 물을 세 번이나 부어 제단을 적신 후 ''오늘 주께서 하나님이신 것과 내가 주의 종인 것을 알게 하소서'' 짧고 간절하게 기도하니 하늘에서 불이 내려왔다.','화려한 말보다 확신에 찬 짧고 간절한 기도가 하나님의 응답을 이끌어낸다.',ARRAY['기도와 응답','순종과 믿음']::text[],'나의 기도는 얼마나 확신에 차 있고 간절한가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/472'),
(473,'기근과 가뭄 중의 기도','구약','예레미야',24,'렘 14:1-22',ARRAY['예레미야','이스라엘 백성']::text[],'극심한 가뭄과 기근 속에서 예레미야는 백성의 죄를 자백하며 그럼에도 우리를 버리지 마시기를 간구했으나, 하나님은 이 백성이 거짓 선지자들의 헛된 위로에 미혹되었음을 지적하셨다.','재난의 때에 진실한 회개 없이 값싼 위로만 구하는 것은 참된 회복으로 이어지지 못한다.',ARRAY['회개와 용서','기도와 응답']::text[],'나는 어려움 중에 값싼 위로가 아닌 진실한 회개로 하나님께 나아가는가?',ARRAY['성인']::text[],'v2','/s/473'),
(474,'성전을 떠나는 하나님의 영광','구약','에스겔',26,'겔 8:1-11:25',ARRAY['에스겔','하나님의 영광']::text[],'우상숭배로 가득한 성전의 참상을 환상으로 본 에스겔은 하나님의 영광이 성전 문지방을 떠나 동문 산 위로 머무는 것을 보며 하나님이 더 이상 함께하지 않으실 것을 깨달았다.','지속적인 죄와 우상숭배는 결국 하나님의 임재조차 떠나게 만드는 무서운 결과를 낳을 수 있다.',ARRAY['우상숭배 경계','하나님의 심판']::text[],'나는 내 삶이나 공동체에 하나님의 임재가 온전히 머물 수 있도록 지키고 있는가?',ARRAY['성인']::text[],'v2','/s/474'),
(475,'다니엘의 마지막 환상','구약','다니엘',27,'단 10:1-12:13',ARRAY['다니엘','천사']::text[],'말년의 다니엘이 큰 전쟁에 관한 환상을 받고 삼 주간 금식하며 기도하니 천사가 나타나 영적 전쟁의 실재를 설명하고 마지막 때의 부활과 심판에 대해 알려주었다.','간절한 기도와 금식은 때로 보이지 않는 영적 전쟁의 영역에까지 영향을 미친다.',ARRAY['기도와 응답','종말과 소망']::text[],'나는 응답이 지체될 때도 다니엘처럼 끈질기게 기도하는가?',ARRAY['성인']::text[],'v2','/s/475'),
(476,'가나안 여인 이후 무리를 고치심과 찬양','신약','마태복음',40,'마 15:29-31',ARRAY['예수님','무리']::text[],'갈릴리 해변 산에 오르신 예수님께 많은 무리가 다리 저는 자, 불구자, 맹인, 말 못하는 자를 데려오니 다 고쳐주시매 무리가 이스라엘의 하나님께 영광을 돌렸다.','예수님의 자비는 특정한 몇 사람이 아니라 나아오는 모든 이에게 동일하게 베풀어진다.',ARRAY['예수님의 기적','사랑과 섬김']::text[],'나는 예수님의 자비가 나뿐 아니라 모든 이에게 열려 있음을 믿고 함께 나누는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/476'),
(477,'안식일은 사람을 위하여 있는 것','신약','마가복음',41,'막 2:23-28',ARRAY['예수님','제자들','바리새인들']::text[],'안식일에 제자들이 밀 이삭을 잘라 먹자 바리새인들이 비난했으나 예수님은 ''안식일이 사람을 위하여 있는 것이요 사람이 안식일을 위하여 있는 것이 아니라'' 말씀하셨다.','하나님이 주신 규례의 본질은 사람을 억압하는 것이 아니라 참된 안식과 유익을 위한 것이다.',ARRAY['율법과 계명','지혜와 분별']::text[],'나는 신앙의 규례를 사람을 살리는 방향으로 이해하고 적용하는가?',ARRAY['청소년','성인']::text[],'v2','/s/477'),
(478,'작은 자를 실족케 하지 말라','신약','누가복음',42,'눅 17:1-4',ARRAY['예수님','제자들']::text[],'예수님은 실족하게 하는 일이 없을 수는 없으나 그 일으키는 자에게는 화가 있다 경고하시며, 소자 중 하나를 실족케 하느니 연자맷돌을 목에 매고 바다에 던져지는 것이 나으리라 강하게 말씀하셨다.','믿음이 연약한 이를 넘어지게 하는 말과 행동에 대해 우리는 매우 신중하고 책임감 있게 행동해야 한다.',ARRAY['사랑과 섬김','지혜와 분별']::text[],'나는 신앙이 연약한 이들을 실족케 하지 않도록 얼마나 조심하고 있는가?',ARRAY['성인']::text[],'v2','/s/478'),
(479,'안식일에 맹인을 고치심으로 인한 논쟁','신약','요한복음',43,'요 9:13-34',ARRAY['맹인이었던 사람','바리새인들','예수님']::text[],'날 때부터 맹인이었다가 안식일에 눈을 뜬 사람을 바리새인들이 거듭 추궁하자 그는 ''한 가지 아는 것은 내가 맹인으로 있다가 지금 보는 그것이니이다'' 담대히 증언하다 출교당했다.','진리를 경험한 사람의 담대한 증언은 종교적 권위의 압박 앞에서도 흔들리지 않는다.',ARRAY['순종과 믿음','용기와 결단']::text[],'나는 경험한 은혜를 압박 속에서도 담대히 증언할 수 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/479'),
(480,'가말리엘의 조언','신약','사도행전',44,'행 5:33-42',ARRAY['가말리엘','공회','사도들']::text[],'사도들을 죽이려는 공회 앞에서 존경받는 율법교사 가말리엘이 ''이 사상이나 이 소행이 사람에게서 났으면 무너질 것이요 만일 하나님께로부터 났으면 너희가 무너뜨릴 수 없다'' 조언하여 사도들이 생명을 건졌다.','지혜로운 신중함은 때로 성급한 판단이 저지를 수 있는 큰 잘못을 막아준다.',ARRAY['지혜와 분별','하나님의 섭리']::text[],'나는 성급한 판단보다 신중하게 하나님의 뜻을 분별하려 하는가?',ARRAY['성인']::text[],'v2','/s/480'),
(481,'브리스길라와 아굴라','신약','사도행전',44,'행 18:1-3,18-19',ARRAY['브리스길라','아굴라','바울']::text[],'천막 만드는 일을 하던 브리스길라와 아굴라 부부는 바울과 함께 일하며 동역했고, 이후 곳곳에서 함께 사역하며 복음을 위해 헌신했다.','생업과 신앙의 동역이 자연스럽게 어우러질 때 부부가 함께 하나님 나라를 위해 크게 쓰임받을 수 있다.',ARRAY['가정과 관계','전도와 선교']::text[],'우리 부부(혹은 동역자)는 일상과 신앙의 동역을 얼마나 자연스럽게 이루고 있는가?',ARRAY['성인']::text[],'v2','/s/481'),
(482,'심는 대로 거두리라(연보에 대한 가르침)','신약','고린도후서',47,'고후 9:1-15',ARRAY['바울','고린도 교회']::text[],'바울은 적게 심는 자는 적게 거두고 많이 심는 자는 많이 거둔다며 각자 마음에 정한 대로 인색함이나 억지로 하지 말고 하나님은 즐겨 내는 자를 사랑하신다 가르쳤다.','드림은 마지못해 하는 의무가 아니라 기쁨으로 자원하여 심는 것이며 그만큼 풍성한 열매로 돌아온다.',ARRAY['사랑과 섬김','순종과 믿음']::text[],'나는 드림을 억지가 아닌 기쁨으로 실천하고 있는가?',ARRAY['성인']::text[],'v2','/s/482'),
(483,'기도에 항상 힘쓰라','신약','골로새서',51,'골 4:2-6',ARRAY['바울','골로새 교회']::text[],'바울은 기도를 계속하고 기도에 감사함으로 깨어 있으라 권면하며, 외인에게 대해서는 지혜로 행하여 말을 항상 은혜 가운데서 소금으로 맛을 냄과 같이 하라 가르쳤다.','깨어 있는 기도와 지혜로운 말은 신앙인의 일상적 삶의 태도를 형성하는 두 기둥이다.',ARRAY['기도와 응답','지혜와 분별']::text[],'나의 말과 기도 생활은 얼마나 깨어 있고 은혜로운가?',ARRAY['성인']::text[],'v2','/s/483'),
(484,'선을 행함으로 고난받을지언정','신약','베드로전서',60,'벧전 3:13-17',ARRAY['베드로']::text[],'베드로는 선을 행함으로 고난받는 것이 하나님의 뜻일진대 악을 행함으로 고난받는 것보다 낫다며, 속에 있는 소망에 관한 이유를 묻는 자에게 대답할 것을 항상 준비하라 권면했다.','의로운 고난은 부끄러운 것이 아니며, 우리는 언제나 소망의 이유를 설명할 준비가 되어 있어야 한다.',ARRAY['고난과 인내','전도와 선교']::text[],'나는 내 안의 소망에 대해 묻는 이에게 답할 준비가 되어 있는가?',ARRAY['성인']::text[],'v2','/s/484'),
(485,'가인이 아벨을 쳐죽인 후 하나님과의 대화','구약','창세기',1,'창 4:6-15',ARRAY['가인','하나님']::text[],'분노한 가인에게 하나님은 ''네가 죄를 다스릴지니라'' 경고하셨으나 가인은 결국 아벨을 죽였고, 하나님이 ''네 아우가 어디 있느냐'' 물으시자 ''내가 알지 못하나이다 내가 내 아우를 지키는 자니이까'' 반문했다.','하나님은 죄를 짓기 전에도 경고하시며 기회를 주시지만, 책임을 회피하려는 태도는 죄를 더 깊게 만든다.',ARRAY['죄와 타락','분노 다스림']::text[],'나는 잘못을 저지른 후 책임을 회피하기보다 정직하게 인정하는가?',ARRAY['청소년','성인']::text[],'v2','/s/485'),
(486,'브살렐과 오홀리압에게 성령의 지혜를 채우심','구약','출애굽기',2,'출 35:30-35',ARRAY['브살렐','오홀리압','모세']::text[],'하나님이 브살렐에게 하나님의 영을 충만하게 하사 지혜와 총명과 지식으로 정교한 일을 하게 하시고 오홀리압과 함께 가르치는 재능도 주셨다.','예술과 기술의 재능도 하나님이 주신 성령의 은사이며 거룩한 목적을 위해 존귀하게 쓰일 수 있다.',ARRAY['창조와 섭리','성령의 역사']::text[],'나는 내 손의 기술과 재능을 하나님이 주신 은사로 여기고 있는가?',ARRAY['성인']::text[],'v2','/s/486'),
(487,'여호와의 군대 대장을 만남','구약','여호수아',6,'수 5:13-15',ARRAY['여호수아','여호와의 군대 대장']::text[],'여리고 앞에서 칼을 든 사람을 만난 여호수아가 ''너는 우리를 위하느냐 우리의 대적을 위하느냐'' 묻자 그는 ''나는 여호와의 군대 대장으로 지금 왔느니라'' 답하니 여호수아가 엎드려 경배했다.','전쟁과 사명의 순간에도 우리는 편을 나누기보다 하나님의 뜻 앞에 겸손히 엎드려야 한다.',ARRAY['겸손과 교만','예배와 경배']::text[],'나는 내 편을 만들려 하기보다 하나님의 뜻에 나를 맞추고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/487'),
(488,'솔로몬의 잠언과 지혜의 명성','구약','열왕기상',11,'왕상 4:29-34',ARRAY['솔로몬']::text[],'하나님이 솔로몬에게 지혜와 총명을 심히 많이 주시니 그 지혜가 동양의 모든 사람과 애굽의 모든 지혜보다 뛰어나 잠언 삼천 가지와 노래 천다섯 편을 지었고 그 명성이 사방에 퍼졌다.','하나님이 주신 지혜는 한 사람을 넘어 시대와 문화를 초월하는 영향력을 지닌다.',ARRAY['지혜와 분별','하나님의 섭리']::text[],'나는 하나님이 주신 지혜를 얼마나 폭넓게 나누고 있는가?',ARRAY['성인']::text[],'v2','/s/488'),
(489,'기근과 반석 사이에서(예레미야의 내적 고백)','구약','예레미야',24,'렘 20:7-18',ARRAY['예레미야','하나님']::text[],'박해와 조롱 속에서 예레미야는 ''여호와여 주께서 나를 권유하시므로 내가 그 권유를 받았사오며'' 솔직한 탄식을 쏟아내면서도 ''그러나 여호와는 두려운 용사같이 나와 함께 계시는 고로'' 결국 찬양으로 돌아섰다.','고통 중의 솔직한 탄식조차 하나님과의 진실한 대화의 한 형태이며 결국 찬양으로 이어질 수 있다.',ARRAY['고난과 인내','기도와 응답']::text[],'나는 고통 중에 하나님께 솔직한 탄식을 쏟아낼 수 있는가?',ARRAY['성인']::text[],'v2','/s/489'),
(490,'예수님이 사람들의 필요를 불쌍히 여기심','신약','마태복음',40,'마 9:35-38',ARRAY['예수님','제자들','무리']::text[],'예수님은 여러 마을을 다니시며 천국 복음을 전하시고 병을 고치셨으며, 목자 없는 양처럼 고생하는 무리를 보시고 불쌍히 여기사 제자들에게 추수할 일꾼을 보내달라 기도하라 하셨다.','영혼을 향한 예수님의 긍휼은 오늘도 일꾼을 보내달라는 간절한 기도로 우리를 초청하신다.',ARRAY['사랑과 섬김','전도와 선교']::text[],'나는 목자 없는 양 같은 이들을 향해 얼마나 긍휼한 마음을 갖고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/490'),
(491,'열두 제자를 세우심','신약','마가복음',41,'막 3:13-19',ARRAY['예수님','열두 제자']::text[],'예수님이 산에 오르사 자기가 원하는 자들을 부르시니 그들이 나아왔고, 예수님은 자기와 함께 있게 하시고 또 보내어 전도하며 귀신을 내쫓는 권능을 주시려고 열두 명을 세우셨다.','제자도의 핵심은 먼저 예수님과 함께 있는 것이며, 그 후에 보내심을 받아 사역하는 것이다.',ARRAY['순종과 믿음','전도와 선교']::text[],'나는 사역하기 전에 먼저 예수님과 함께하는 시간을 충분히 갖고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/491'),
(492,'일흔 명을 파송하심','신약','누가복음',42,'눅 10:1-24',ARRAY['예수님','칠십 인']::text[],'예수님은 칠십 명을 둘씩 앞서 보내시며 추수할 것은 많되 일꾼이 적다 하시고, 그들이 기쁨으로 돌아와 귀신들도 항복했다 보고하자 예수님은 그들의 이름이 하늘에 기록된 것을 더 기뻐하라 하셨다.','사역의 성과보다 하나님 나라에 속한 정체성 자체를 더 기뻐하는 것이 균형 잡힌 신앙이다.',ARRAY['전도와 선교','겸손과 교만']::text[],'나는 사역의 결과와 하나님 안에서의 정체성 중 무엇을 더 기뻐하는가?',ARRAY['청소년','성인']::text[],'v2','/s/492'),
(493,'선한 목자와 삯꾼','신약','요한복음',43,'요 10:22-42',ARRAY['예수님','유대인들']::text[],'수전절에 예수님은 ''내 양은 내 음성을 들으며 나는 그들을 알며 그들은 나를 따르느니라 내가 그들에게 영생을 주노니 영원히 멸망하지 아니할 것이요'' 말씀하시며 아버지와 하나임을 선포하셨다.','예수님의 양이 된다는 것은 그 음성을 알아듣고 결코 빼앗기지 않는 영원한 보호 속에 있다는 뜻이다.',ARRAY['인도하심과 보호','예수 그리스도의 정체성']::text[],'나는 예수님의 음성을 분별하고 따르는 훈련이 되어 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/493'),
(494,'아나니아가 사울에게 안수함','신약','사도행전',44,'행 9:10-19',ARRAY['아나니아','사울','예수님']::text[],'환상 중에 사울에게 안수하라는 명을 받은 아나니아가 두려워했으나 순종하여 나아가 그에게 안수하니 사울의 눈에서 비늘 같은 것이 벗어지며 다시 보게 되고 성령이 충만해졌다.','두려운 순종이라도 하나님의 명령을 따를 때 한 사람의 인생을 완전히 변화시키는 통로가 된다.',ARRAY['순종과 믿음','성령의 역사']::text[],'나는 두려움에도 불구하고 하나님이 명하신 순종의 발걸음을 내딛을 수 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/494'),
(495,'그리스도인의 실제적 삶의 지침','신약','로마서',45,'롬 12:9-21',ARRAY['바울','로마 교회']::text[],'바울은 사랑에는 거짓이 없게 하고 악을 미워하며 선에 속하라, 소망 중에 즐거워하고 환난 중에 참으며 기도에 항상 힘쓰라, 원수를 갚지 말고 선으로 악을 이기라 실제적인 삶의 지침들을 나열했다.','신앙의 성숙은 추상적 교리를 넘어 관계와 일상 속 구체적인 실천으로 완성된다.',ARRAY['사랑과 섬김','분노 다스림']::text[],'오늘 나열된 지침 중 내게 가장 도전이 되는 것은 무엇인가?',ARRAY['청소년','성인']::text[],'v2','/s/495'),
(496,'은사는 다양하나 성령은 같음','신약','고린도전서',46,'고전 12:1-11',ARRAY['바울','고린도 교회']::text[],'바울은 은사는 여러 가지나 성령은 같고 직분은 여러 가지나 주는 같다며 각 사람에게 성령을 나타내심은 유익하게 하려 하심이라 가르쳤다.','다양한 은사는 경쟁의 이유가 아니라 공동의 유익을 위해 함께 조화를 이루어야 할 하나님의 선물이다.',ARRAY['교회와 공동체','성령의 역사']::text[],'나는 나와 다른 은사를 가진 사람을 경쟁이 아닌 협력의 대상으로 보는가?',ARRAY['성인']::text[],'v2','/s/496'),
(497,'한 몸과 한 성령','신약','에베소서',49,'엡 4:17-32',ARRAY['바울','에베소 교회']::text[],'바울은 성도들에게 이방인처럼 허망한 것으로 행하지 말고 심령이 새롭게 되어 하나님을 따라 의와 진리의 거룩함으로 지으심을 받은 새 사람을 입으라 권면하며 서로 인자하게 하며 용서하라 가르쳤다.','새로운 정체성을 입은 성도는 이전과는 다른 성품과 관계의 방식으로 살아가야 한다.',ARRAY['순종과 믿음','회개와 용서']::text[],'나는 옛 사람의 습관을 벗고 새 사람의 성품으로 얼마나 살아가고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/497'),
(498,'말씀을 행하는 자가 되라','신약','야고보서',59,'약 1:19-27',ARRAY['야고보']::text[],'야고보는 성도들에게 듣기는 속히 하고 말하기는 더디 하며 성내기도 더디 하라 권면하고 말씀을 듣기만 하고 행하지 않으면 자신을 속이는 것이라며 고아와 과부를 돌보는 것이 참된 경건이라 가르쳤다.','참된 경건은 말씀을 듣는 것에 그치지 않고 실제적인 사랑의 행동으로 완성된다.',ARRAY['순종과 믿음','사랑과 섬김']::text[],'나의 신앙은 듣는 것에 머무는가, 구체적인 행함으로 나아가는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/498'),
(499,'일곱 인, 일곱 나팔, 일곱 대접의 상징적 의미','신약','요한계시록',66,'계 16:12-21',ARRAY['요한','여섯째와 일곱째 천사']::text[],'여섯째 대접에서 아마겟돈으로 왕들이 모이고 일곱째 대접이 쏟아지자 ''되었다'' 하는 큰 음성과 함께 번개와 우렛소리, 큰 지진이 있었으니 하나님의 심판이 완전히 성취되었음을 보여준다.','역사의 마지막 심판은 하나님의 뜻대로 한 치의 오차도 없이 완전하게 성취될 것이다.',ARRAY['하나님의 심판','종말과 소망']::text[],'완전한 하나님의 심판 앞에서 나는 오늘 어떻게 준비하며 살아야 하는가?',ARRAY['성인']::text[],'v2','/s/499'),
(500,'삼손과 블레셋 사람들(결혼 잔치의 수수께끼)','구약','사사기',7,'삿 14:1-15:20',ARRAY['삼손','딤나 여인','블레셋 사람들']::text[],'삼손이 블레셋 여인과의 혼인 잔치에서 낸 수수께끼를 아내를 통해 알아낸 블레셋 사람들에게 분노한 삼손은 여우 삼백 마리로 그들의 밭을 태우는 등 힘으로 보복을 거듭하며 블레셋과 갈등을 키워갔다.','분노와 보복이 반복되는 관계는 결국 더 큰 갈등과 파괴로 이어질 뿐이다.',ARRAY['분노 다스림','시기와 갈등']::text[],'나는 갈등이 생겼을 때 보복보다 다른 지혜로운 방법을 찾으려 하는가?',ARRAY['청소년','성인']::text[],'v2','/s/500'),
(501,'오른손이 하는 것을 왼손이 모르게 하라','신약','마태복음',40,'마 6:1-4,16-18',ARRAY['예수님','제자들']::text[],'예수님은 구제할 때 오른손이 하는 것을 왼손이 모르게 은밀히 하고 금식할 때도 사람에게 보이려 하지 말고 은밀한 중에 보시는 아버지께 보이라 가르치셨다.','신앙의 선행은 사람의 인정이 아니라 은밀한 중에 보시는 하나님을 향한 진실함이어야 한다.',ARRAY['겸손과 교만','사랑과 섬김']::text[],'나의 선행과 경건은 사람에게 보이기 위함인가, 하나님을 향한 진심인가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/501'),
(502,'다윗의 마지막 말','구약','사무엘하',10,'삼하 23:1-7',ARRAY['다윗','하나님']::text[],'죽음을 앞둔 다윗은 자신이 이스라엘의 노래 잘하는 자로서 하나님의 영이 자기를 통해 말씀하셨다 고백하며 공의로 다스리는 자가 아침 햇살과 같다는 마지막 시를 남겼다.','신실하게 하나님의 영으로 살아온 인생은 마지막 순간까지 그분의 성품을 증언하는 삶이 된다.',ARRAY['지도자의 리더십','충성과 신실함']::text[],'나는 인생의 마지막에 어떤 고백을 남기고 싶은가?',ARRAY['성인']::text[],'v2','/s/502'),
(503,'이새의 줄기에서 난 싹(메시아 예언)','구약','이사야',23,'사 11:1-9',ARRAY['이사야']::text[],'이사야는 이새의 줄기에서 한 싹이 나며 그 뿌리에서 한 가지가 나서 결실할 것이요 여호와의 영이 그 위에 강림하시리니 그 때에 이리가 어린 양과 함께 거하는 평화의 나라가 임할 것이라 예언했다.','메시아가 다스리시는 나라는 모든 피조물이 조화를 이루는 완전한 평화의 나라이다.',ARRAY['예수 그리스도의 정체성','종말과 소망']::text[],'이리와 어린 양이 함께하는 평화의 그림이 내게 주는 소망은 무엇인가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/503'),
(504,'새 마음과 새 영을 주리라','구약','에스겔',26,'겔 36:22-32',ARRAY['에스겔','하나님','이스라엘 백성']::text[],'하나님은 자기 이름을 위해 흩어진 백성을 모으시고 맑은 물을 뿌려 정결케 하며 굳은 마음을 제하고 부드러운 새 마음과 새 영을 주어 율례를 따르게 하겠다 약속하셨다.','진정한 변화는 외적 규례의 강요가 아니라 하나님이 주시는 새로운 마음과 영으로부터 시작된다.',ARRAY['성령의 역사','회개와 용서']::text[],'나는 새 마음과 새 영을 주시는 하나님의 은혜를 날마다 구하고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/504'),
(505,'율법을 완전케 하러 오심','신약','마태복음',40,'마 5:17-20',ARRAY['예수님','제자들']::text[],'예수님은 자신이 율법이나 선지자를 폐하러 온 것이 아니라 완전하게 하려 오셨다 말씀하시며 우리의 의가 서기관과 바리새인보다 더 낫지 않으면 결코 천국에 들어가지 못하리라 가르치셨다.','예수님은 율법의 외형적 준수를 넘어 그 본래의 정신과 마음의 중심까지 온전하게 하러 오셨다.',ARRAY['율법과 계명','예수 그리스도의 정체성']::text[],'나의 의는 형식적 준수를 넘어 마음의 중심까지 이르고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/505'),
(506,'평지 설교의 축복과 화','신약','누가복음',42,'눅 6:20-26',ARRAY['예수님','제자들','무리']::text[],'산상수훈과 유사하지만 평지에서 전해진 이 말씀에서 예수님은 가난한 자, 주린 자, 우는 자는 복이 있다 하시고 반대로 부요하고 배부르고 웃는 자에게는 화가 있으리라는 강렬한 대조로 가르치셨다.','하나님 나라의 가치는 세상이 부러워하는 것과 정반대의 기준으로 복과 화를 나눈다.',ARRAY['하나님 나라','겸손과 교만']::text[],'나는 세상의 기준과 하나님 나라의 기준 중 무엇으로 복을 판단하는가?',ARRAY['청소년','성인']::text[],'v2','/s/506'),
(507,'나는 세상의 빛이라','신약','요한복음',43,'요 8:12-30',ARRAY['예수님','바리새인들']::text[],'예수님은 ''나는 세상의 빛이니 나를 따르는 자는 어둠에 다니지 아니하고 생명의 빛을 얻으리라'' 선포하시며 자신이 아버지로부터 보내심을 받은 이임을 거듭 증언하셨다.','예수님을 따르는 삶은 더 이상 어둠 속에서 헤매지 않고 생명의 빛 가운데 걷는 삶이다.',ARRAY['예수 그리스도의 정체성','인도하심과 보호']::text[],'나는 삶의 어두운 영역에서 예수님을 빛으로 삼아 걷고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/507'),
(508,'귀먹고 말 더듬는 자를 고치심','신약','마가복음',41,'막 7:31-37',ARRAY['예수님','귀먹고 말 더듬는 사람']::text[],'사람들이 데려온 귀먹고 말 더듬는 사람의 귀에 손가락을 넣고 침 뱉어 그 혀에 손을 대시며 ''에바다(열리라)'' 하시니 귀가 열리고 혀가 풀려 말이 분명해졌다.','예수님은 닫혀 있던 감각과 소통의 길을 여시어 온전한 관계와 표현이 가능하게 하신다.',ARRAY['예수님의 기적','인도하심과 보호']::text[],'내 삶에서 닫혀 있는 소통이나 관계의 영역이 열리기를 예수님께 구하고 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/508'),
(509,'벳새다의 맹인을 고치심','신약','마가복음',41,'막 8:22-26',ARRAY['예수님','벳새다의 맹인']::text[],'벳새다에서 맹인을 데려오자 예수님이 눈에 침을 뱉고 안수하시니 처음에는 사람이 나무처럼 보였고 다시 안수하시자 밝히 보게 되었다.','때로 하나님의 은혜는 단번이 아니라 점진적인 과정을 통해 온전한 회복으로 나아간다.',ARRAY['예수님의 기적','고난과 인내']::text[],'나는 은혜가 단번에 임하지 않아도 점진적인 회복 과정을 인내로 기다릴 수 있는가?',ARRAY['어린이','청소년','성인']::text[],'v2','/s/509'),
(510,'우상에게 바친 제물에 대하여','신약','고린도전서',46,'고전 8:1-13',ARRAY['바울','고린도 교회']::text[],'우상은 세상에 아무것도 아니라는 지식이 있어도 연약한 형제가 실족할 수 있다면 차라리 고기를 영원히 먹지 않겠다며 바울은 지식보다 사랑으로 서로를 세우라 권면했다.','내가 자유롭게 여기는 것이라도 연약한 형제를 배려하는 사랑이 지식보다 우선되어야 한다.',ARRAY['사랑과 섬김','지혜와 분별']::text[],'나는 나의 자유보다 연약한 형제를 배려하는 사랑을 우선하고 있는가?',ARRAY['성인']::text[],'v2','/s/510'),
(511,'서로 짐을 지라','신약','갈라디아서',48,'갈 6:1-10',ARRAY['바울','갈라디아 교회']::text[],'바울은 형제가 범죄한 일이 드러나거든 온유한 심령으로 바로잡고 서로 짐을 지라 그리하여 그리스도의 법을 성취하라 권면하며 선을 행하되 낙심하지 말라 격려했다.','공동체 안에서 서로의 연약함과 짐을 온유하게 나누어 지는 것이 그리스도의 법을 실천하는 길이다.',ARRAY['사랑과 섬김','교회와 공동체']::text[],'나는 형제의 짐을 온유하게 함께 지고 있는가?',ARRAY['청소년','성인']::text[],'v2','/s/511'),
(512,'성령이 교회들에게 하시는 말씀','신약','요한계시록',66,'계 2:7,11,17,29,3:6,13,22',ARRAY['요한','성령','일곱 교회']::text[],'일곱 교회에게 보낸 각 편지는 ''귀 있는 자는 성령이 교회들에게 하시는 말씀을 들을지어다''라는 동일한 권면으로 마무리되며 이기는 자에게 주어질 약속을 전한다.','성령의 음성에 귀 기울이는 것은 모든 시대, 모든 교회에게 변함없이 중요한 신앙의 태도이다.',ARRAY['성령의 역사','순종과 믿음']::text[],'나는 오늘도 성령이 내 삶과 공동체에 주시는 말씀에 귀 기울이고 있는가?',ARRAY['성인']::text[],'v2','/s/512')
